INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27366, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "让", "is_correct": true, "explanation": "让：第四声，表示“使别人做某事”。"}, {"text": "忘", "is_correct": false, "explanation": "wàng（第四声）与 ràng 声母不同（w 与 r），意思是忘记。"}, {"text": "壤", "is_correct": false, "explanation": "rǎng（第三声）与 ràng 声调不同，意思是土壤。"}, {"text": "葬", "is_correct": false, "explanation": "zàng（第四声）与 ràng 声母不同（z 与 r），意思是埋葬。"}], "explanations": {"让": "让：第四声，表示“使别人做某事”。", "忘": "wàng（第四声）与 ràng 声母不同（w 与 r），意思是忘记。", "壤": "rǎng（第三声）与 ràng 声调不同，意思是土壤。", "葬": "zàng（第四声）与 ràng 声母不同（z 与 r），意思是埋葬。"}, "sentence_index": null, "correct_answer": "让"}, "level_3": {"options": [{"text": "让", "is_correct": true, "explanation": "让：使役动词，表示“使别人做某事”，句中“让小王给客户打电话”是兼语结构。"}, {"text": "扶", "is_correct": false, "explanation": "语义：“扶”指搀扶身体，不能表示“使人去打电话”。"}, {"text": "拍", "is_correct": false, "explanation": "搭配：“拍”不能带兼语结构“小王给客户打电话”，句子不通。"}, {"text": "抱", "is_correct": false, "explanation": "配价：“抱”是及物动词，不能带兼语结构，句子不通。"}], "explanations": {"让": "让：使役动词，表示“使别人做某事”，句中“让小王给客户打电话”是兼语结构。", "扶": "语义：“扶”指搀扶身体，不能表示“使人去打电话”。", "拍": "搭配：“拍”不能带兼语结构“小王给客户打电话”，句子不通。", "抱": "配价：“抱”是及物动词，不能带兼语结构，句子不通。"}, "sentence_index": 6, "correct_answer": "让"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服可以再让五十块钱吗？", "explanation": "这里的“让”是“减价、少收”的意思（让价），不表示“使别人做事”。"}, {"text": "这盘棋他让我三个子，我还是输了。", "explanation": "这里的“让”是下棋时让对方先放几子、减少对方优势的意思（让子），不是“使别人做事”的意思。"}, {"text": "请大家让一让，我要过去。", "explanation": "这里的“让”是“躲开、让出路”的意思（让开），不是“使别人做事”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27366, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈让不弟弟看电视。", "corrected_sentence": "妈妈不让弟弟看电视。", "error_description": "否定词“不”应放在“让”前面，应说“不让”，不能说“让不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27366, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店长让给顾客拿样品。", "corrected_sentence": "店长让小李给顾客拿样品。", "error_description": "“让”后面要有兼语，即指出谁去做事。应说“让小李给顾客拿样品”，这里缺少“小李”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
