INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27368, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "内容就是东西里面有什么。", "primary_collocate": null, "pronunciation": "nèi róng", "ipa": "neɪ˥˩ ɻʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "信里的内容很短，只有两行字。", "target_word": "内容", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你打开盒子，看看里面的内容。", "target_word": "内容", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "包裹外面写着里面的内容。", "target_word": "内容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关要检查每个箱子里的内容。", "target_word": "内容", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你把信里的内容读给我听。", "target_word": "内容", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我没看过这个文件夹的内容。", "target_word": "内容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瓶子上的字说明了里面的内容。", "target_word": "内容", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不愿意说出信封里的内容。", "target_word": "内容", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察问他背包里的内容是什么。", "target_word": "内容", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个单子写清楚了盒子的内容。", "target_word": "内容", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "内容：容器、信件等里面装着的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6dab98-14d7-4430-bd0f-b102915e1fde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27368, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内容", "is_correct": true, "explanation": "正确：「信里的内容」指信中写着的东西，「很短，只有两行字」与之相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「很短」描述长度，「颜色」不能用长短来形容，「信里的颜色很短」不通。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：「重量」用“重”或“轻”来形容，不说“很短”，此处搭配不当。"}, {"text": "味道", "is_correct": false, "explanation": "语义：「味道」是感官特征，不是信件的长度，与「只有两行字」的语义不符。"}], "explanations": {"内容": "正确：「信里的内容」指信中写着的东西，「很短，只有两行字」与之相符。", "颜色": "搭配：「很短」描述长度，「颜色」不能用长短来形容，「信里的颜色很短」不通。", "重量": "搭配：「重量」用“重”或“轻”来形容，不说“很短”，此处搭配不当。", "味道": "语义：「味道」是感官特征，不是信件的长度，与「只有两行字」的语义不符。"}, "sentence_index": 0, "correct_answer": "内容"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "海关要称每个箱子的内容。", "explanation": "这里应该用〈重量〉。称的是重量，“内容”指箱子里装的东西，不能用“称”来说明它。"}, {"text": "这辆车的内容很快。", "explanation": "这里应该用〈速度〉。说车的快慢用“速度”，“内容”指东西里面有什么，不指快慢。"}, {"text": "这杯水的内容很烫。", "explanation": "这里应该用〈温度〉。说水的冷热用“温度”，“内容”指东西里面有什么，不指冷热。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27368, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内容", "is_correct": true, "explanation": "正确：「里面的内容」指瓶内或包装内装的东西，「说明了」与之搭配。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不在瓶子里，「说明了里面的价格」语义不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：「身高」是人的体貌特征，不能作为瓶子里的东西来说明。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：「寿命」指生物的存活时间，与瓶子里装的东西不搭配。"}], "explanations": {"内容": "正确：「里面的内容」指瓶内或包装内装的东西，「说明了」与之搭配。", "价格": "语义：价格不在瓶子里，「说明了里面的价格」语义不通。", "身高": "体貌：「身高」是人的体貌特征，不能作为瓶子里的东西来说明。", "寿命": "语义：「寿命」指生物的存活时间，与瓶子里装的东西不搭配。"}, "sentence_index": 6, "correct_answer": "内容"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个瓶子的内容很低。", "explanation": "这里应该用〈温度〉。说“低”形容温度，“内容”不用高低来描述。"}, {"text": "这束花的内容很香。", "explanation": "这里应该用〈气味〉。说花的香味用“气味”，“内容”指东西里面有什么，不指气味。"}, {"text": "这盏灯的内容很亮。", "explanation": "这里应该用〈亮度〉。说灯的明暗用“亮度”，“内容”指东西里面有什么，不指明暗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27368, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海关仔细检查了箱子里内容。", "corrected_sentence": "海关仔细检查了箱子里的内容。", "error_description": "错误：“箱子里内容”。正确：“箱子里的内容”。方位短语修饰名词时要加“的”，漏掉“的”语序不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27368, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张纸上写清楚了箱子里内容。", "corrected_sentence": "这张纸上写清楚了箱子里的内容。", "error_description": "错误：“箱子里内容”。正确：“箱子里的内容”。方位短语“箱子里”修饰名词“内容”时要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
