INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27374, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "你可以做你想做的事，别人不能随便阻止你。", "primary_collocate": null, "pronunciation": "quán lì", "ipa": "tɕʰɥɛn˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "这是我的权利，你不能拦着我。", "target_word": "权利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有权利决定自己的事。", "target_word": "权利", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "每个人都有自由说话的权利。", "target_word": "权利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你有权利不回答这个问题。", "target_word": "权利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买东西时，你有权利自己选。", "target_word": "权利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁也不能不让我表达自己的看法，这是我的权利。", "target_word": "权利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有权利过自己喜欢的生活。", "target_word": "权利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们要你签字，你有权利拒绝。", "target_word": "权利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想穿什么颜色的衣服，那是他的权利。", "target_word": "权利", "complexity_tier": "T3", "furigana": "tā xiǎng chuān shénme yánsè de yīfu, nà shì tā de quán lì。", "sentence_source": "generated"}, {"text": "老师说，学生有权利提出自己的想法。", "target_word": "权利", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项权利", "label": "量词"}, {"form": "權利", "label": "繁体"}, {"form": "权利人", "label": "复合"}], "register": "中性", "sense_fingerprint": "个人可以自己决定、自由去做的事，别人无权阻止（我的权利、有权利决定）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fa5d8e-2296-45e3-ab90-df9c0be39312') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27374, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "权利", "is_correct": true, "explanation": "正确：“这是我的权利，你不能拦着我”表示这件事别人无权阻止，语义通顺。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不能被“拦着”，“这是我的天气”句意荒谬。"}, {"text": "眼镜", "is_correct": false, "explanation": "搭配：“拦着”针对的是人的行动，“眼镜”作为被拦的对象不搭配，句意不通。"}, {"text": "脚", "is_correct": false, "explanation": "语义：“脚”不是可以用来说明所有权和他人阻止关系的东西，句意不通。"}], "explanations": {"权利": "正确：“这是我的权利，你不能拦着我”表示这件事别人无权阻止，语义通顺。", "天气": "语义：“天气”不能被“拦着”，“这是我的天气”句意荒谬。", "眼镜": "搭配：“拦着”针对的是人的行动，“眼镜”作为被拦的对象不搭配，句意不通。", "脚": "语义：“脚”不是可以用来说明所有权和他人阻止关系的东西，句意不通。"}, "sentence_index": 0, "correct_answer": "权利"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你有权利按时交税。", "explanation": "这里应该用〈义务〉。“权利”指可以自己选择做与不做，按时交税是必须履行的义务，应说“义务”。"}, {"text": "他对家人负有权利。", "explanation": "这里应该用〈责任〉。“负有”后面接“责任”，不能接“权利”。"}, {"text": "这笔存款的权利很高。", "explanation": "这里应该用〈利息〉。“利息”指存款或借款产生的钱，“权利”指法律或道德允许的资格，不能用来说存款的收益。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27374, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "权利", "is_correct": true, "explanation": "正确：“她有权利过自己喜欢的生活”表示她有资格这样生活，语义通顺。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”不能作为过生活的资格，“她有手机过自己喜欢的生活”句意不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不是可以拥有并借以过生活的资格，句意荒谬。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“有……过生活”需要能被拥有的资格或条件，“眼睛”不能与之搭配。"}], "explanations": {"权利": "正确：“她有权利过自己喜欢的生活”表示她有资格这样生活，语义通顺。", "手机": "语义：“手机”不能作为过生活的资格，“她有手机过自己喜欢的生活”句意不通。", "石头": "语义：“石头”不是可以拥有并借以过生活的资格，句意荒谬。", "眼睛": "搭配：“有……过生活”需要能被拥有的资格或条件，“眼睛”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "权利"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他担任了班长的权利。", "explanation": "这里应该用〈职务〉。“担任”后面接职务、职位，“权利”不能被担任。"}, {"text": "市长的权利很大，能管很多事。", "explanation": "这里应该用〈权力〉。“权力”指管理、支配别人的力量；“权利”指自己可以做某事、别人不能阻止。"}, {"text": "司机的权利是保证安全。", "explanation": "这里应该用〈职责〉。保证安全是司机必须履行的责任，应说“职责”，不能说“权利”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27374, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一把重要的权利，别人不能随便干涉。", "corrected_sentence": "他有一项重要的权利，别人不能随便干涉。", "error_description": "量词错误：“权利”的量词应为“项”，不能用“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27374, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有权利人拒绝不合理的要求。", "corrected_sentence": "他有权利拒绝不合理的要求。", "error_description": "复合词误用：“权利人”指权利的持有者，这里表示“权利”本身，应说“有权利拒绝”，不能用“权利人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
