INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27376, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示事情紧接着发生或很快发生。", "primary_collocate": null, "pronunciation": "jiù", "ipa": "tɕjoʊ̯⁵¹", "syllable_count": 1, "sentences": [{"text": "他骑车很快，一会儿就到了。", "target_word": "就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影马上就开始了。", "target_word": "就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我五分钟就能到。", "target_word": "就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题他很快就解决了。", "target_word": "就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭很快就做好了。", "target_word": "就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家离学校很近，走路十分钟就到。", "target_word": "就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌很好听，我很快就学会了。", "target_word": "就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你刚到就要走吗？", "target_word": "就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一会儿他就回来。", "target_word": "就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭刚端上来，他就吃了个精光。", "target_word": "就", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "表示事情很快、马上或紧接着发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47c36c6a-10d1-484f-a144-0a730fa56e1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27376, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "就", "is_correct": true, "explanation": "就（第四声）是本词，表示事情发生得快或马上发生。"}, {"text": "九", "is_correct": false, "explanation": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是数字“九”。"}, {"text": "久", "is_correct": false, "explanation": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是“时间长”。"}, {"text": "酒", "is_correct": false, "explanation": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是“酒水”。"}, {"text": "绣", "is_correct": false, "explanation": "xiù（第四声）与 jiù（第四声）声母不同（x 与 j），意思是“刺绣”。"}], "explanations": {"就": "就（第四声）是本词，表示事情发生得快或马上发生。", "九": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是数字“九”。", "久": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是“时间长”。", "酒": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是“酒水”。", "绣": "xiù（第四声）与 jiù（第四声）声母不同（x 与 j），意思是“刺绣”。"}, "sentence_index": null, "correct_answer": "就"}, "level_3": {"options": [{"text": "就", "is_correct": true, "explanation": "就：表示很快发生，与“一会儿”搭配，指很快就到了。"}, {"text": "再", "is_correct": false, "explanation": "语法：“再”表示将来重复，不能与表示完成的“了”连用，“一会儿再到了”不成立。"}, {"text": "却", "is_correct": false, "explanation": "搭配：“却”不与“一会儿…到”搭配，表示转折，句意不通。"}, {"text": "还", "is_correct": false, "explanation": "语义：还表示仍然，与“一会儿”的快速到达不相容。"}], "explanations": {"就": "就：表示很快发生，与“一会儿”搭配，指很快就到了。", "再": "语法：“再”表示将来重复，不能与表示完成的“了”连用，“一会儿再到了”不成立。", "却": "搭配：“却”不与“一会儿…到”搭配，表示转折，句意不通。", "还": "语义：还表示仍然，与“一会儿”的快速到达不相容。"}, "sentence_index": 0, "correct_answer": "就"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们说的就是这件事，别忘了。", "explanation": "此处的“就是”表示“正是”，强调肯定，不表示事情发生得快。"}, {"text": "这个问题就他一个人解决了。", "explanation": "此处的“就”表示“只有”，限定施事，不表示事情发生得快。"}, {"text": "他就着饭喝了点汤。", "explanation": "此处的“就”表示“借着、伴随”，与“就着某物”搭配，不表示事情发生得快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '571872f6-9807-451a-bc7d-5a66fa6060b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27376, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "就", "is_correct": true, "explanation": "就（第四声）是本词，表示事情发生得快或马上发生。"}, {"text": "秀", "is_correct": false, "explanation": "xiù（第四声）与 jiù（第四声）声母不同（x 与 j），意思是“优秀、秀丽”。"}, {"text": "袖", "is_correct": false, "explanation": "xiù（第四声）与 jiù（第四声）声母不同（x 与 j），意思是“衣袖”。"}, {"text": "韭", "is_correct": false, "explanation": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是“韭菜”。"}], "explanations": {"就": "就（第四声）是本词，表示事情发生得快或马上发生。", "秀": "xiù（第四声）与 jiù（第四声）声母不同（x 与 j），意思是“优秀、秀丽”。", "袖": "xiù（第四声）与 jiù（第四声）声母不同（x 与 j），意思是“衣袖”。", "韭": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是“韭菜”。"}, "sentence_index": null, "correct_answer": "就"}, "level_3": {"options": [{"text": "就", "is_correct": true, "explanation": "就：表示很快学会，与“很快”搭配，句意通顺。"}, {"text": "才", "is_correct": false, "explanation": "语义：才表示“晚、仅此时”，与“很快”矛盾。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“很快只学会”不成立，“只”不与“很快”组合。"}, {"text": "再", "is_correct": false, "explanation": "语义：再表示又一次，与“很快学会”的一次性完成不符。"}], "explanations": {"就": "就：表示很快学会，与“很快”搭配，句意通顺。", "才": "语义：才表示“晚、仅此时”，与“很快”矛盾。", "只": "搭配：“很快只学会”不成立，“只”不与“很快”组合。", "再": "语义：再表示又一次，与“很快学会”的一次性完成不符。"}, "sentence_index": 6, "correct_answer": "就"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这么多苹果，我就要这一个。", "explanation": "此处的“就”表示“只”，限定范围，不表示事情很快发生。"}, {"text": "前面那座白房子就是我家。", "explanation": "此处的“就”表示“正是”，加强肯定，不表示事情很快发生。"}, {"text": "他就着灯光看书。", "explanation": "此处的“就”是动词，“就着”表示“借着”，不表示事情很快发生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '571872f6-9807-451a-bc7d-5a66fa6060b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27376, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电影很快要就开始了。", "corrected_sentence": "电影很快就要开始了。", "error_description": "“就”位置错误：应说“就要”，不能说“要就”，“就”要放在“要”的前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '571872f6-9807-451a-bc7d-5a66fa6060b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27376, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们很快才到家了。", "corrected_sentence": "我们很快就到家了。", "error_description": "错误形式是「很快才到家了」，正确形式是「很快就到家了」：「很快」表示时间短，要用「就」；「才」表示晚或慢，与「很快」矛盾。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '571872f6-9807-451a-bc7d-5a66fa6060b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
