INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27380, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示确定，不会改变。", "primary_collocate": null, "pronunciation": "yí dìng", "ipa": "i˧˥ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "明天一定会下雨，出门带伞吧。", "target_word": "一定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事他一定知道。", "target_word": "一定", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他是医生，每天一定很忙。", "target_word": "一定", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "红队这么强，一定会赢。", "target_word": "一定", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "灯还亮着，他一定在家。", "target_word": "一定", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "看他的样子，他一定很累。", "target_word": "一定", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个办法一定行，不会错。", "target_word": "一定", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他说过一定回来，我相信他。", "target_word": "一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么晚了，她一定已经睡了。", "target_word": "一定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没吃早饭，现在一定很饿。", "target_word": "一定", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "不一定", "label": "否定式"}], "register": "中性", "sense_fingerprint": "副词，表示对事实或将来的情况很有把握、肯定不变：一定会、一定是", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d3e40a-5887-46ae-a092-87880ccdc4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27380, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一定", "is_correct": true, "explanation": "一定：表示确定，修饰「会下雨」，符合句意。"}, {"text": "已经", "is_correct": false, "explanation": "搭配：「已经」表示已经发生，与「明天」的将来时间不搭配。"}, {"text": "从不", "is_correct": false, "explanation": "语义：「从不」表示从来不，与「会下雨」的预测相矛盾。"}, {"text": "总是", "is_correct": false, "explanation": "语义：「总是」表示经常，不能用于说明某一天的天气。"}], "explanations": {"一定": "一定：表示确定，修饰「会下雨」，符合句意。", "已经": "搭配：「已经」表示已经发生，与「明天」的将来时间不搭配。", "从不": "语义：「从不」表示从来不，与「会下雨」的预测相矛盾。", "总是": "语义：「总是」表示经常，不能用于说明某一天的天气。"}, "sentence_index": 0, "correct_answer": "一定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们一定去吃饭吧，我请客。", "explanation": "这里应该用〈一起〉。一定表示有把握的判断，不能用来邀请别人一同做事。"}, {"text": "我一定饿了，想吃点东西。", "explanation": "这里应该用〈很〉。一定用来推断，自己的感觉自己清楚，不用推断。"}, {"text": "这本书我一定看完了，很好看。", "explanation": "这里应该用〈已经〉。一定表示推断，自己做完的事直接说已经。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308fac2f-75d3-4b72-bab7-3881ffc7e4ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27380, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一定", "is_correct": true, "explanation": "一定：表示确定，修饰「行」，符合句意。"}, {"text": "从没", "is_correct": false, "explanation": "语义：「从没」表示从未发生，与「不会错」的肯定相矛盾。"}, {"text": "刚才", "is_correct": false, "explanation": "搭配：「刚才」表示不久前，不能用于说明办法的一般效果。"}, {"text": "也许", "is_correct": false, "explanation": "语义：「也许」表示不确定，与「不会错」的肯定相矛盾。"}], "explanations": {"一定": "一定：表示确定，修饰「行」，符合句意。", "从没": "语义：「从没」表示从未发生，与「不会错」的肯定相矛盾。", "刚才": "搭配：「刚才」表示不久前，不能用于说明办法的一般效果。", "也许": "语义：「也许」表示不确定，与「不会错」的肯定相矛盾。"}, "sentence_index": 6, "correct_answer": "一定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们一定唱首歌吧，大家都来。", "explanation": "这里应该用〈一起〉。一定表示有把握的判断，不能用来邀请别人一同做事。"}, {"text": "我一定渴了，给我一杯水。", "explanation": "这里应该用〈很〉。一定用来推断，自己的感觉自己清楚，不用推断。"}, {"text": "我一定吃过饭了，不用等我。", "explanation": "这里应该用〈已经〉。一定表示推断，自己做过的事直接说已经。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308fac2f-75d3-4b72-bab7-3881ffc7e4ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27380, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很一定会来，我们等他。", "corrected_sentence": "他一定会来，我们等他。", "error_description": "错误形式：「很一定会来」；正确形式：「一定会来」。「很」用于修饰形容词或少数动词，不能放在副词「一定」前面；「一定」直接放在能愿动词「会」之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308fac2f-75d3-4b72-bab7-3881ffc7e4ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27380, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们明天很一定出发。", "corrected_sentence": "我们明天一定出发。", "error_description": "错误形式：「很一定出发」；正确形式：「一定出发」。「很」是程度副词，不能修饰副词「一定」，应删去「很」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308fac2f-75d3-4b72-bab7-3881ffc7e4ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
