INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27382, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "表示事情应当这样做。", "primary_collocate": null, "pronunciation": "yīng gāi", "ipa": "iŋ˥ kaɪ˥", "syllable_count": 2, "sentences": [{"text": "过马路时应该看红绿灯。", "target_word": "应该", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你应该早点儿睡觉。", "target_word": "应该", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "在图书馆里应该小声说话。", "target_word": "应该", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃饭以前应该先洗手。", "target_word": "应该", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小朋友应该听老师的话。", "target_word": "应该", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "开车的人不应该喝酒。", "target_word": "应该", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们应该把垃圾放进垃圾桶。", "target_word": "应该", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐公共汽车时应该给老人让座。", "target_word": "应该", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友有困难，我们应该帮忙。", "target_word": "应该", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "借了别人的东西，应该按时还。", "target_word": "应该", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不应该", "label": "否定式"}], "register": "中性", "sense_fingerprint": "应该：表示事情应当这样做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6dab98-14d7-4430-bd0f-b102915e1fde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27382, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "应该", "is_correct": true, "explanation": "正确：「过马路时应该看红绿灯」表示事情应当这样做，与句意相符。"}, {"text": "敢", "is_correct": false, "explanation": "语义：「敢」表示有胆量去做某事，「过马路时敢看红绿灯」不表示应当。"}, {"text": "肯", "is_correct": false, "explanation": "搭配：「肯」需要有意愿的主体，此处不能用「肯」来表示应当，搭配不当。"}, {"text": "愿意", "is_correct": false, "explanation": "语义：「愿意」表示乐意去做，与「过马路时……看红绿灯」表示的规范义不符。"}], "explanations": {"应该": "正确：「过马路时应该看红绿灯」表示事情应当这样做，与句意相符。", "敢": "语义：「敢」表示有胆量去做某事，「过马路时敢看红绿灯」不表示应当。", "肯": "搭配：「肯」需要有意愿的主体，此处不能用「肯」来表示应当，搭配不当。", "愿意": "语义：「愿意」表示乐意去做，与「过马路时……看红绿灯」表示的规范义不符。"}, "sentence_index": 0, "correct_answer": "应该"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天应该了一本书。", "explanation": "这里应该用〈买〉。“应该”是情态动词，不能单独带“了”和宾语。"}, {"text": "这个苹果很应该。", "explanation": "这里应该用〈好吃〉。“应该”不是形容词，不能用“很”修饰来描述东西。"}, {"text": "他应该一个好学生。", "explanation": "这里应该用〈是〉。“应该”后面要接动词，不能直接接名词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27382, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "应该", "is_correct": true, "explanation": "正确：「我们应该把垃圾放进垃圾桶」表示事情应当这样做，与句意相符。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，不能直接修饰“把”字句，“我们很把垃圾放进……”不通。"}, {"text": "太", "is_correct": false, "explanation": "语法：“太”修饰形容词，不能用在“把”字句前，“我们太把垃圾放进……”不通。"}, {"text": "最", "is_correct": false, "explanation": "语法：“最”表示程度最高，不能修饰“把垃圾放进垃圾桶”这样的动作。"}], "explanations": {"应该": "正确：「我们应该把垃圾放进垃圾桶」表示事情应当这样做，与句意相符。", "很": "语法：“很”是程度副词，不能直接修饰“把”字句，“我们很把垃圾放进……”不通。", "太": "语法：“太”修饰形容词，不能用在“把”字句前，“我们太把垃圾放进……”不通。", "最": "语法：“最”表示程度最高，不能修饰“把垃圾放进垃圾桶”这样的动作。"}, "sentence_index": 6, "correct_answer": "应该"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我应该了他一支笔。", "explanation": "这里应该用〈借〉。“应该”是情态动词，不能单独带“了”和宾语。"}, {"text": "这件衣服太应该了。", "explanation": "这里应该用〈贵〉。“应该”不是形容词，不能说“太应该了”来描述衣服。"}, {"text": "他每天都应该学校。", "explanation": "这里应该用〈去〉。“应该”后面要接动词，不能直接接地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27382, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子没应该玩火。", "corrected_sentence": "孩子不应该玩火。", "error_description": "错误：“没应该玩火”。正确：“不应该玩火”。情态动词“应该”的否定只能用“不”，不能用“没”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27382, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在公共场所要应该保持安静。", "corrected_sentence": "在公共场所应该保持安静。", "error_description": "错误：“要应该保持”。正确：“应该保持”。“应该”与“要”都是情态动词，不能连用，应去掉多余的“要”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
