INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27384, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打开看看里面有什么。", "primary_collocate": null, "pronunciation": "liú lǎn", "ipa": "ljoʊ˧˥ lan˨˩˦", "syllable_count": 2, "sentences": [{"text": "我打开相册，浏览了里面的照片。", "target_word": "浏览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网上浏览各种旅行信息。", "target_word": "浏览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以先浏览一下这个文件夹。", "target_word": "浏览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书店里随意浏览，看看有没有新书。", "target_word": "浏览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用手机浏览网上商店的衣服。", "target_word": "浏览", "complexity_tier": "T3", "furigana": "tā yòng shǒujī liúlǎn wǎngshàng shāngdiàn de yīfu", "sentence_source": "generated"}, {"text": "请浏览一下网站首页，看看有什么新内容。", "target_word": "浏览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在电脑上浏览着动画片的目录。", "target_word": "浏览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想浏览这个网页，但是打不开。", "target_word": "浏览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打开邮箱，浏览了新来的邮件。", "target_word": "浏览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "点开这个链接可以浏览所有图片。", "target_word": "浏览", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "浏览了", "label": "体标"}, {"form": "浏览过", "label": "体标"}, {"form": "浏览着", "label": "体标"}, {"form": "浏览器", "label": "复合"}], "register": "中性", "sense_fingerprint": "打开页面或文件看看里面有什么", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34a0e51c-73da-4535-940d-e3dbc7c8f001') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27384, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浏览", "is_correct": true, "explanation": "正确：“打开相册，浏览了里面的照片”，指打开后快速看看里面有什么。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：照片不能吃，与“打开相册”后的查看动作不合。"}, {"text": "煮", "is_correct": false, "explanation": "语义：照片不能煮，与“打开相册”的语境完全无关。"}, {"text": "洗涤", "is_correct": false, "explanation": "搭配：“洗涤”多用于衣物、餐具，不能说“洗涤照片”。"}], "explanations": {"浏览": "正确：“打开相册，浏览了里面的照片”，指打开后快速看看里面有什么。", "吃掉": "语义：照片不能吃，与“打开相册”后的查看动作不合。", "煮": "语义：照片不能煮，与“打开相册”的语境完全无关。", "洗涤": "搭配：“洗涤”多用于衣物、餐具，不能说“洗涤照片”。"}, "sentence_index": 0, "correct_answer": "浏览"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "质检员仔细浏览每一个零件，确保没有裂缝。", "explanation": "这里应该用〈检查〉。浏览只是快速看看，不能与“仔细”和“确保没有裂缝”搭配。"}, {"text": "科学家用三年时间浏览这种病毒的传播规律。", "explanation": "这里应该用〈研究〉。浏览只是打开看看里面有什么，不能用来表示长期深入地探究规律。"}, {"text": "老师逐字浏览作业，确保每个字都正确。", "explanation": "这里应该用〈批改〉。浏览不检查细节，与“逐字”和“确保每个字都正确”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7812589b-bd5d-49c3-abbb-fb9c8bbc75d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27384, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浏览", "is_correct": true, "explanation": "正确：“在电脑上浏览着动画片的目录”，指快速看看目录内容。"}, {"text": "煎", "is_correct": false, "explanation": "语义：煎是烹饪动作，与“在电脑上”的语境完全不符。"}, {"text": "缝补", "is_correct": false, "explanation": "语义：缝补用于布料，不能用于动画片的目录。"}, {"text": "晾晒", "is_correct": false, "explanation": "搭配：“晾晒”用于衣物等物品，不能用于电脑上的目录。"}], "explanations": {"浏览": "正确：“在电脑上浏览着动画片的目录”，指快速看看目录内容。", "煎": "语义：煎是烹饪动作，与“在电脑上”的语境完全不符。", "缝补": "语义：缝补用于布料，不能用于动画片的目录。", "晾晒": "搭配：“晾晒”用于衣物等物品，不能用于电脑上的目录。"}, "sentence_index": 6, "correct_answer": "浏览"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸每天早上浏览一杯咖啡，然后去上班。", "explanation": "浏览的对象应是文字、页面、图片等信息，“一杯咖啡”不能被浏览，这里应该用〈喝〉。"}, {"text": "我浏览了一下那只小狗，然后把它抱回家。", "explanation": "浏览的对象应是信息，不能用于“小狗”这样的动物，这里应该用〈抚摸〉。"}, {"text": "我浏览了一下那张桌子，然后坐下来吃饭。", "explanation": "“桌子”不是可以快速看的信息，不能用“浏览”，这里应该用〈擦〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7812589b-bd5d-49c3-abbb-fb9c8bbc75d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27384, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她浏览很快，几分钟就翻完了网页。", "corrected_sentence": "她浏览得很快，几分钟就翻完了网页。", "error_description": "错误：“浏览很快”，缺少连接状态补语的“得”；正确：“浏览得很快”。动词后接形容词作状态补语时要用“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7812589b-bd5d-49c3-abbb-fb9c8bbc75d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27384, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在电脑前浏览了着网页，很久没有说话。", "corrected_sentence": "他在电脑前浏览着网页，很久没有说话。", "error_description": "体标错误：“了”与“着”不能同时附着在同一个动词后。应只用“着”，说“浏览着网页”表示动作持续。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7812589b-bd5d-49c3-abbb-fb9c8bbc75d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
