INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27396, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不服判决，向上级请求重新处理。", "primary_collocate": null, "pronunciation": "shēn sù", "ipa": "ʂən˥ su˥˩", "syllable_count": 2, "sentences": [{"text": "他不服判决，向上级申诉。", "target_word": "申诉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她觉得判得太重，决定申诉。", "target_word": "申诉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们不满意法院的决定，一直在申诉。", "target_word": "申诉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法院罚了王先生的款，他不同意，去申诉了。", "target_word": "申诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人申诉了很多次，终于有了结果。", "target_word": "申诉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "母亲为女儿的案子到处申诉。", "target_word": "申诉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不服这个判决，想向上级法院申诉。", "target_word": "申诉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你对判决不服，有权利申诉。", "target_word": "申诉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她申诉了两年，案子才重新审理。", "target_word": "申诉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人写了一封信，向上级申诉。", "target_word": "申诉", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "申诉了", "label": "完成体"}, {"form": "申诉过", "label": "经历体"}, {"form": "申诉书", "label": "复合"}], "register": "书面", "sense_fingerprint": "不服判决，请上级重新处理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34a0e51c-73da-4535-940d-e3dbc7c8f001') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27396, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "申诉", "is_correct": true, "explanation": "正确：shēn sù，不服判决，向上级请求重新处理。"}, {"text": "神速", "is_correct": false, "explanation": "声调不同：神速（shén sù）第一音节为阳平，与申诉（shēn sù）的阴平不同，意思是非常迅速。"}, {"text": "声速", "is_correct": false, "explanation": "韵尾不同：声速（shēng sù）第一音节为 -ng，与申诉的 -n 不同，意思是声音传播的速度。"}, {"text": "伸缩", "is_correct": false, "explanation": "韵母不同：伸缩（shēn suō）第二音节为 suō，与申诉的 sù 不同，意思是变长变短。"}], "explanations": {"申诉": "正确：shēn sù，不服判决，向上级请求重新处理。", "神速": "声调不同：神速（shén sù）第一音节为阳平，与申诉（shēn sù）的阴平不同，意思是非常迅速。", "声速": "韵尾不同：声速（shēng sù）第一音节为 -ng，与申诉的 -n 不同，意思是声音传播的速度。", "伸缩": "韵母不同：伸缩（shēn suō）第二音节为 suō，与申诉的 sù 不同，意思是变长变短。"}, "sentence_index": null, "correct_answer": "申诉"}, "level_3": {"options": [{"text": "申诉", "is_correct": true, "explanation": "正确：“他不服判决，向上级申诉”表示对判决不服，请上级重新处理。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与不服判决、请上级处理的语境完全不符，句意不通。"}, {"text": "鼓掌", "is_correct": false, "explanation": "语义：“鼓掌”表示赞同或高兴，与“不服判决”的态度相矛盾。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”指随意走动、休闲，与“不服判决、请上级重新处理”的语境无关，句意不通。"}], "explanations": {"申诉": "正确：“他不服判决，向上级申诉”表示对判决不服，请上级重新处理。", "睡觉": "语义：“睡觉”与不服判决、请上级处理的语境完全不符，句意不通。", "鼓掌": "语义：“鼓掌”表示赞同或高兴，与“不服判决”的态度相矛盾。", "散步": "语义：“散步”指随意走动、休闲，与“不服判决、请上级重新处理”的语境无关，句意不通。"}, "sentence_index": 0, "correct_answer": "申诉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向领导申诉了工作进展。", "explanation": "这里应该用〈报告〉。“申诉”是对判决不服、请求重新处理，汇报工作进展应说“报告”。"}, {"text": "邻居每天申诉噪音太大。", "explanation": "这里应该用〈抱怨〉。“申诉”针对不服的判决或决定，平日里对噪音的不满应说“抱怨”。"}, {"text": "他向朋友申诉考试时间。", "explanation": "这里应该用〈打听〉。“申诉”不用于询问信息，问考试时间应说“打听”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7812589b-bd5d-49c3-abbb-fb9c8bbc75d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27396, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "申诉", "is_correct": true, "explanation": "正确：“想向上级法院申诉”表示对判决不服，想请法院重新处理。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与对判决不服、请求重新处理的语境无关，句意不通。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清理环境，不能用来向法院提出请求。"}, {"text": "发呆", "is_correct": false, "explanation": "语义：“发呆”指呆坐出神，与“对判决不服、请法院重新处理”的语境无关，句意不通。"}], "explanations": {"申诉": "正确：“想向上级法院申诉”表示对判决不服，想请法院重新处理。", "唱歌": "语义：“唱歌”与对判决不服、请求重新处理的语境无关，句意不通。", "打扫": "语义：“打扫”指清理环境，不能用来向法院提出请求。", "发呆": "语义：“发呆”指呆坐出神，与“对判决不服、请法院重新处理”的语境无关，句意不通。"}, "sentence_index": 6, "correct_answer": "申诉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把欠钱的人告上法庭，进行申诉。", "explanation": "这里应该用〈诉讼〉。“申诉”针对的是对判决或决定不服，普通债务纠纷应说“诉讼”。"}, {"text": "老人向儿子申诉了搬家的原因。", "explanation": "这里应该用〈解释〉。“申诉”是对决定不服、请求重新处理，说明搬家的原因应说“解释”。"}, {"text": "他申诉参加了比赛。", "explanation": "这里应该用〈报名〉。“申诉”不用于参加活动，报名参加比赛应说“报名”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7812589b-bd5d-49c3-abbb-fb9c8bbc75d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27396, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老人不服这次判决，上级申诉。", "corrected_sentence": "老人不服这次判决，向上级申诉。", "error_description": "错误：省略了介词“向”。正确：“申诉”的对象要用“向”引出，应说“向上级申诉”，不能说“上级申诉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7812589b-bd5d-49c3-abbb-fb9c8bbc75d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27396, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "母亲申诉了一个，法院才重新审理。", "corrected_sentence": "母亲申诉了一次，法院才重新审理。", "error_description": "错误：计算动作的次数要用量词“次”，不能用“个”。正确：应说“申诉了一次”，“次”专用于计量动作的次数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7812589b-bd5d-49c3-abbb-fb9c8bbc75d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
