INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27398, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "东西从哪里来，就是它的来源。", "primary_collocate": null, "pronunciation": "lái yuán", "ipa": "lai˧˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这杯水的来源是山上的小河。", "target_word": "来源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你知道这个苹果的来源吗？", "target_word": "来源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不告诉我钱的来源。", "target_word": "来源", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这篇文章的资料来源很清楚。", "target_word": "来源", "complexity_tier": "T3", "furigana": "Zhè piān wénzhāng de zīliào láiyuán hěn qīngchu.", "sentence_source": "generated"}, {"text": "好的食品都要写清楚来源。", "target_word": "来源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想知道这件衣服的来源。", "target_word": "来源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些鱼的来源是一个大湖。", "target_word": "来源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生活里的快乐有很多来源。", "target_word": "来源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问我们：这个词的来源是什么？", "target_word": "来源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈很关心菜的来源，所以常去农场买菜。", "target_word": "来源", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "信息来源", "label": "复合"}, {"form": "來源", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西从哪里来，就是它的来源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '228a4112-dbe4-4f55-9364-4edc773aa3f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27398, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "来源", "is_correct": true, "explanation": "正确：“来源”指水从哪里来，与“这杯水的”搭配，符合句意。"}, {"text": "出身", "is_correct": false, "explanation": "搭配：“出身”指人的家庭背景，不能说“这杯水的出身”。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”指人的性情，水没有性格，句子不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指人或生物的岁数，水不能说年龄，句子不通。"}], "explanations": {"来源": "正确：“来源”指水从哪里来，与“这杯水的”搭配，符合句意。", "出身": "搭配：“出身”指人的家庭背景，不能说“这杯水的出身”。", "性格": "语义：“性格”指人的性情，水没有性格，句子不通。", "年龄": "语义：“年龄”指人或生物的岁数，水不能说年龄，句子不通。"}, "sentence_index": 0, "correct_answer": "来源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子的来源很复杂，父母一直没有告诉他。", "explanation": "这里应该用〈身世〉。来源指东西的出处；说人的家世、遭遇要用身世。"}, {"text": "这位年轻人的来源很好，父母都是大学教授。", "explanation": "这里应该用〈出身〉。来源指东西从哪里来；说人的家庭背景要用出身。"}, {"text": "他的来源是广东，他从小在那里长大。", "explanation": "这里应该用〈籍贯〉。来源指东西的出处；说人的祖籍或出生地要用籍贯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4ef227a-ccf3-4885-bd62-7a306efce275') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27398, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "来源", "is_correct": true, "explanation": "正确：“来源”指鱼从哪里来，与“这些鱼的”搭配，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指外观，不能说鱼的颜色是一个大湖，句子不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”后面接数量或重量，不能说“体重是一个大湖”。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”只用于人或生物的高度，不能说鱼的身高是一个大湖。"}], "explanations": {"来源": "正确：“来源”指鱼从哪里来，与“这些鱼的”搭配，符合句意。", "颜色": "语义：“颜色”指外观，不能说鱼的颜色是一个大湖，句子不通。", "体重": "搭配：“体重”后面接数量或重量，不能说“体重是一个大湖”。", "身高": "搭配：“身高”只用于人或生物的高度，不能说鱼的身高是一个大湖。"}, "sentence_index": 6, "correct_answer": "来源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜的来源很辣，我吃不了。", "explanation": "这里应该用〈味道〉。来源指东西的出处，不能形容口感；说菜辣不辣、好不好吃要用味道。"}, {"text": "那位老人的来源很神秘，没人知道他从哪里来。", "explanation": "这里应该用〈来历〉。来源指东西从哪里来；说人的身世背景要用来历。"}, {"text": "这个年轻人的来源很特别，大家都很好奇。", "explanation": "这里应该用〈身份〉。来源指东西的出处；说人的身份、经历要用身份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4ef227a-ccf3-4885-bd62-7a306efce275') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27398, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想问一下这张来源可靠吗？", "corrected_sentence": "我想问一下这个来源可靠吗？", "error_description": "量词错误：“来源”前应用“个”，“张”用于纸张、桌子等平面物。正确形式为“这个来源”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4ef227a-ccf3-4885-bd62-7a306efce275') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27398, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个食品来源们很安全，你放心吃吧。", "corrected_sentence": "这个食品来源很安全，你放心吃吧。", "error_description": "错误：“来源”是抽象名词，不能加“们”。“这个食品来源”指单数，应去掉“们”。正确形式为“这个食品来源”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4ef227a-ccf3-4885-bd62-7a306efce275') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
