INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27402, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情结束后的结果，通常是不好的。", "primary_collocate": null, "pronunciation": "hòu guǒ", "ipa": "xou˥˩ kuo˨˩˦", "syllable_count": 2, "sentences": [{"text": "他后来才明白，那样做的后果很严重。", "target_word": "后果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乱花钱的后果，就是月底没钱吃饭。", "target_word": "后果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明不带伞，后果是淋了一身雨。", "target_word": "后果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "熬夜太多，后果就是白天没有精神。", "target_word": "后果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也不想承担这种后果。", "target_word": "后果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司没有想过这个决定的后果。", "target_word": "后果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道不睡觉的后果吗？", "target_word": "后果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试没考好，是他不努力的后果。", "target_word": "后果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么严重的后果，我们一定要避免。", "target_word": "后果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，不吃药的后果可能很麻烦。", "target_word": "后果", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个后果", "label": "量词"}, {"form": "後果", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事情结束后出现的坏结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0340599b-d1b3-4420-a126-e8eea9bfd3af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27402, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后果", "is_correct": true, "explanation": "正确：后果指事情结束后产生的坏结果，与“很严重”搭配。"}, {"text": "经验", "is_correct": false, "explanation": "搭配：“很严重”修饰的是后果、问题、错误，“经验”不能说“很严重”。"}, {"text": "效率", "is_correct": false, "explanation": "语义：效率说的是做事快慢高低，不会说“很严重”。"}, {"text": "结论", "is_correct": false, "explanation": "语义：结论是推断的内容，不能说“很严重”。"}], "explanations": {"后果": "正确：后果指事情结束后产生的坏结果，与“很严重”搭配。", "经验": "搭配：“很严重”修饰的是后果、问题、错误，“经验”不能说“很严重”。", "效率": "语义：效率说的是做事快慢高低，不会说“很严重”。", "结论": "语义：结论是推断的内容，不能说“很严重”。"}, "sentence_index": 0, "correct_answer": "后果"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次旅行的后果在北京。", "explanation": "这里应该用〈目的地〉。后果指事情产生的结果，不能用来表示地点。"}, {"text": "我每天练琴，后果是为了参加比赛。", "explanation": "后果指事情结束后的结果，“为了参加比赛”说明的是目的，应该用〈目的〉。"}, {"text": "他没有睡好，后果是昨晚喝了咖啡。", "explanation": "后果指产生的结果，喝咖啡是睡不好的原因，应该用〈原因〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27402, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后果", "is_correct": true, "explanation": "正确：后果指不睡觉引出的坏结果，句中“你知道”后面要的正是这个词。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是事物的外观，不能指不睡觉带来的结果。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字是称呼，不是不睡觉引出的结果。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“不睡觉”不会有味道，“味道”不能与这一行为搭配。"}], "explanations": {"后果": "正确：后果指不睡觉引出的坏结果，句中“你知道”后面要的正是这个词。", "颜色": "语义：颜色是事物的外观，不能指不睡觉带来的结果。", "名字": "语义：名字是称呼，不是不睡觉引出的结果。", "味道": "搭配：“不睡觉”不会有味道，“味道”不能与这一行为搭配。"}, "sentence_index": 6, "correct_answer": "后果"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次聚会的后果在三楼的餐厅。", "explanation": "后果指事情产生的结果，聚会的地点应该用〈地点〉。"}, {"text": "这个后果是我们昨天制定的计划。", "explanation": "后果指事情结束后的结果，这里指事先制定的方案，应该用〈方案〉。"}, {"text": "这件事的后果很热情地接待了我们。", "explanation": "后果指事情结束后的结果，不能做“接待”的动作，这里应该用〈主人〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27402, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只后果让他很难受。", "corrected_sentence": "这种后果让他很难受。", "error_description": "量词错误：“后果”的量词应为“种”（或“个”），“只”不能用于“后果”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27402, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不关门地后果很严重。", "corrected_sentence": "他不关门的后果很严重。", "error_description": "结构助词错误：修饰名词“后果”应用“的”，“地”用于修饰动词、形容词，写成“地后果”不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
