INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27410, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "教一个人学做一件事。", "primary_collocate": null, "pronunciation": "péi xùn", "ipa": "pʰei˧˥ ɕyn˥˩", "syllable_count": 2, "sentences": [{"text": "公司要培训新员工。", "target_word": "培训", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师正在培训新来的同事。", "target_word": "培训", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他培训过很多厨师。", "target_word": "培训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理想培训我做销售。", "target_word": "培训", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们培训他们使用新机器。", "target_word": "培训", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店培训服务员怎么和客人说话。", "target_word": "培训", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师傅用一个月培训了三个新人。", "target_word": "培训", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂每年培训几百名工人。", "target_word": "培训", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他负责培训刚来的司机。", "target_word": "培训", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院请专家来培训护士。", "target_word": "培训", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "培训了", "label": "体标"}, {"form": "培训过", "label": "体标"}, {"form": "培训着", "label": "体标"}, {"form": "培訓", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：教某人学会做某件事，带宾语，如培训新员工", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12968ab-dfb2-45a1-8c6f-73fe3fd501b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27410, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "培训", "is_correct": true, "explanation": "培训：教某人学做某件事，符合“公司要……新员工”的语境。"}, {"text": "种植", "is_correct": false, "explanation": "语义：种植指栽种植物，不能用于人，句意荒谬。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：烘焙指烤制食品，与员工无关，句意荒谬。"}, {"text": "粉刷", "is_correct": false, "explanation": "搭配：“粉刷”用于墙面等，不能用于人，句意荒谬。"}], "explanations": {"培训": "培训：教某人学做某件事，符合“公司要……新员工”的语境。", "种植": "语义：种植指栽种植物，不能用于人，句意荒谬。", "烘焙": "语义：烘焙指烤制食品，与员工无关，句意荒谬。", "粉刷": "搭配：“粉刷”用于墙面等，不能用于人，句意荒谬。"}, "sentence_index": 0, "correct_answer": "培训"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民每年培训很多花卉，销量很好。", "explanation": "这里应该用〈培育〉。培育用于花卉、树苗等植物，培训的对象是人，不能用于花卉。"}, {"text": "父母培训孩子的兴趣。", "explanation": "这里应该用〈培养〉。兴趣要慢慢培养，“培训”指短期的教导和练习，不能用于兴趣。"}, {"text": "农民培训这块荒地。", "explanation": "这里应该用〈开垦〉。培训的对象必须是人，荒地只能开垦，不能培训。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff36a586-0261-4afb-a08e-4606642a5be4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27410, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "培训", "is_correct": true, "explanation": "培训：教某人学做某件事，符合“老师傅用一个月……了三个新人”的语境。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：欢迎指表示接纳和问候，不是持续一个月的教导，句意不通。"}, {"text": "播种", "is_correct": false, "explanation": "语义：“播种”指撒种子，不能用于人，句意荒谬。"}, {"text": "参观", "is_correct": false, "explanation": "配价：“参观”的宾语是场所，不能直接带“新人”作宾语。"}], "explanations": {"培训": "培训：教某人学做某件事，符合“老师傅用一个月……了三个新人”的语境。", "欢迎": "语义：欢迎指表示接纳和问候，不是持续一个月的教导，句意不通。", "播种": "语义：“播种”指撒种子，不能用于人，句意荒谬。", "参观": "配价：“参观”的宾语是场所，不能直接带“新人”作宾语。"}, "sentence_index": 6, "correct_answer": "培训"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司每年都培训员工的业绩。", "explanation": "这里应该用〈考核〉。业绩要考核，培训的对象是人，不能用于业绩。"}, {"text": "医生培训病人的感冒。", "explanation": "这里应该用〈治疗〉。感冒要治疗，培训的对象是人的能力或技能，不能用于疾病。"}, {"text": "工人培训了那座桥。", "explanation": "这里应该用〈修建〉。培训的对象是人，不能用于桥梁；桥要修建。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff36a586-0261-4afb-a08e-4606642a5be4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27410, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店长正在培训了我们做收银。", "corrected_sentence": "店长正在培训我们做收银。", "error_description": "体标错误：“正在”表示动作正在进行，不能与表示完成的“了”同用。应去掉“了”，改为“正在培训我们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff36a586-0261-4afb-a08e-4606642a5be4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27410, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司每年都把几十名员工培训。", "corrected_sentence": "这家公司每年都把几十名员工培训成技术工人。", "error_description": "把字句错误：“把”字句中的动词后不能光秃秃结束，必须带补语或其他成分。应改为“把几十名员工培训成技术工人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff36a586-0261-4afb-a08e-4606642a5be4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
