INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27412, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在固定的时间看看东西有没有问题。", "primary_collocate": null, "pronunciation": "dìng qī jiǎn chá", "ipa": "tiŋ˥˩ tɕʰi˥ tɕjɛn˨˩˦ tʂʰa˧˥", "syllable_count": 4, "sentences": [{"text": "我每个星期定期检查一次自行车。", "target_word": "定期检查", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸定期检查家里的水和电，怕出问题。", "target_word": "定期检查", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师定期检查教室的灯，坏了就换新的。", "target_word": "定期检查", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民定期检查田里的水管，看看有没有漏水的地方。", "target_word": "定期检查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院定期检查药房，不让坏药留下来。", "target_word": "定期检查", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人定期检查电线，所以房子里很少出事。", "target_word": "定期检查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要定期检查手机，看看有没有坏的地方。", "target_word": "定期检查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每年定期检查眼睛，怕视力越来越差。", "target_word": "定期检查", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你定期检查灭火器，看看有没有问题。", "target_word": "定期检查", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "管理员定期检查电梯，让大家坐得放心。", "target_word": "定期检查", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "定期檢查", "label": "繁体"}], "register": "中性", "sense_fingerprint": "定期检查：在固定时间看东西有没有问题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12968ab-dfb2-45a1-8c6f-73fe3fd501b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27412, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "定期检查", "is_correct": true, "explanation": "定期检查：在固定时间查看自行车有没有问题，与“每个星期一次”相符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能带“自行车”作宾语，句子不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“自行车”搭配，句子不通。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”的对象是人或活动，不能用于自行车。"}], "explanations": {"定期检查": "定期检查：在固定时间查看自行车有没有问题，与“每个星期一次”相符。", "唱": "搭配：“唱”不能带“自行车”作宾语，句子不通。", "吃": "搭配：“吃”不能与“自行车”搭配，句子不通。", "欢迎": "语义：“欢迎”的对象是人或活动，不能用于自行车。"}, "sentence_index": 0, "correct_answer": "定期检查"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老人每天定期检查花园的风景，心情很好。", "explanation": "这里应该用〈欣赏〉。欣赏指欣喜地观赏美好事物；检查指查看有没有问题，不用于赏景。"}, {"text": "学校每年定期检查运动会，让同学们很开心。", "explanation": "这里应该用〈举办〉。举办指组织进行活动；检查指查看问题，不能用来指组织运动会。"}, {"text": "爷爷每晚定期检查那片夕阳，拍给孩子们看。", "explanation": "这里应该用〈拍摄〉。拍摄指用相机把景物拍下来；检查指查看有没有问题，不能用于夕阳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff36a586-0261-4afb-a08e-4606642a5be4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27412, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "定期检查", "is_correct": true, "explanation": "定期检查：按固定时间查看手机有没有坏的地方，与句意相符。"}, {"text": "喂", "is_correct": false, "explanation": "配价：“喂”要求有生命的对象，手机不能作宾语。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记手机”与“看看有没有坏的地方”的目的矛盾。"}, {"text": "叠", "is_correct": false, "explanation": "搭配：“叠”一般用于衣物、纸张，不能说叠手机。"}], "explanations": {"定期检查": "定期检查：按固定时间查看手机有没有坏的地方，与句意相符。", "喂": "配价：“喂”要求有生命的对象，手机不能作宾语。", "忘记": "语义：“忘记手机”与“看看有没有坏的地方”的目的矛盾。", "叠": "搭配：“叠”一般用于衣物、纸张，不能说叠手机。"}, "sentence_index": 6, "correct_answer": "定期检查"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每年定期检查故乡，心里很想念。", "explanation": "这里应该用〈思念〉。思念指想念亲人或故乡的感情；检查指查看有没有问题，不能用来表达想念。"}, {"text": "讲解员每天定期检查展柜的云朵，给观众讲一讲。", "explanation": "这里应该用〈介绍〉。介绍指向观众说明展品；检查指查看有没有问题，云朵不是展品，也不能检查。"}, {"text": "朋友们每年定期检查他的生日，一起吃饭庆祝。", "explanation": "这里应该用〈祝贺〉。祝贺指表示庆贺和祝福；检查指查看问题，不能用于生日。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff36a586-0261-4afb-a08e-4606642a5be4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27412, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民定期检查了田里的电线，看看有没有漏电的地方。", "corrected_sentence": "农民定期检查田里的电线，看看有没有漏电的地方。", "error_description": "错误形式：“定期检查了田里的电线”，“了”表示动作已经完成，与“定期”这种按时反复进行的习惯动作不合。正确形式：“定期检查田里的电线”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff36a586-0261-4afb-a08e-4606642a5be4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27412, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "管理员定期检查着消防门，让大家住得放心。", "corrected_sentence": "管理员定期检查消防门，让大家住得放心。", "error_description": "错误形式：“定期检查着消防门”，“着”表示动作正在持续进行，与“定期”这种间隔反复的进行方式不合。正确形式：“定期检查消防门”，去掉“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff36a586-0261-4afb-a08e-4606642a5be4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
