INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27414, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27414, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "每年一次的；按一年计算的（作定语，如“年度大会”）。", "primary_collocate": null, "pronunciation": "nián dù", "ipa": "njɛn˧˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "到了年度大会的时候，大家都来了。", "target_word": "年度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的年度运动会在秋天举行。", "target_word": "年度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年度大会上，公司会给大家发奖金。", "target_word": "年度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年度晚会上，同事们唱歌跳舞。", "target_word": "年度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司组织年度体检，大家都要参加。", "target_word": "年度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个年度节目很受欢迎。", "target_word": "年度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年度比赛开始前，选手们很紧张。", "target_word": "年度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年度活动下个月在城里举办。", "target_word": "年度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年度聚会是一年一次，大家都很期待。", "target_word": "年度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在年度表演里讲了一个故事。", "target_word": "年度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "年度报告", "label": "复合"}, {"form": "年度计划", "label": "复合"}], "register": "中性", "sense_fingerprint": "年度|每年一次的、按年计算的，如年度大会、年度报告", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0340599b-d1b3-4420-a126-e8eea9bfd3af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27414, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地铁", "is_correct": false, "explanation": "语义：地铁不是大会的一种，“地铁大会”不合逻辑。"}, {"text": "年度", "is_correct": true, "explanation": "正确：“年度”修饰“大会”，指每年一次的大会，句意完整。"}, {"text": "深夜", "is_correct": false, "explanation": "搭配：“深夜”指时间，不能修饰“大会”组成词组，与“到了……的时候”不协调。"}, {"text": "病房", "is_correct": false, "explanation": "语义：病房是医疗场所，与“大会”不相容。"}], "explanations": {"地铁": "语义：地铁不是大会的一种，“地铁大会”不合逻辑。", "年度": "正确：“年度”修饰“大会”，指每年一次的大会，句意完整。", "深夜": "搭配：“深夜”指时间，不能修饰“大会”组成词组，与“到了……的时候”不协调。", "病房": "语义：病房是医疗场所，与“大会”不相容。"}, "sentence_index": 0, "correct_answer": "年度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司今年举办十年度庆典，很多老员工都来了。", "explanation": "这里应该用〈周年〉。周年用于计算某事过去的整年数，如十周年；年度指每年一次的时候，不能用来计数。"}, {"text": "我们公司每天都有年度晨会，大家都很忙。", "explanation": "这里应该用〈日常〉。日常指每天都有的事，年度指一年一次的时候，不能用来修饰每天都开的晨会。"}, {"text": "今天是学校的年度，同学们都很开心。", "explanation": "这里应该用〈纪念日〉。纪念日指某一个具体的日子；年度指每年定期出现的时候，不指某一天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27414, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "葬礼", "is_correct": false, "explanation": "语义：葬礼是一种仪式，不能修饰“比赛”，“葬礼比赛”不合逻辑。"}, {"text": "年度", "is_correct": true, "explanation": "正确：“年度”修饰“比赛”，指每年定期举行的比赛，句意通顺。"}, {"text": "婚礼", "is_correct": false, "explanation": "语义：婚礼不是比赛，“婚礼比赛”不合逻辑。"}, {"text": "寿宴", "is_correct": false, "explanation": "搭配：“寿宴”不能与“比赛”组成词组，搭配不当。"}], "explanations": {"葬礼": "语义：葬礼是一种仪式，不能修饰“比赛”，“葬礼比赛”不合逻辑。", "年度": "正确：“年度”修饰“比赛”，指每年定期举行的比赛，句意通顺。", "婚礼": "语义：婚礼不是比赛，“婚礼比赛”不合逻辑。", "寿宴": "搭配：“寿宴”不能与“比赛”组成词组，搭配不当。"}, "sentence_index": 6, "correct_answer": "年度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天是我的年度，朋友们都来看我。", "explanation": "这里应该用〈生日〉。生日是某人出生的那一天，年度不能指某个人的个人日子。"}, {"text": "会议的年度是十点整。", "explanation": "这里应该用〈时刻〉。时刻指一天中某个具体的时间点，年度指一年一次的时候，不能用来说会议开始的钟点。"}, {"text": "这间屋子的年度是十平方米。", "explanation": "这里应该用〈面积〉。面积指平面的大小，年度指一年一次的时候，不能用来说房间的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27414, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司每年办一场年度地晚会。", "corrected_sentence": "公司每年办一场年度晚会。", "error_description": "“年度”修饰名词“晚会”时中间不应加“地”。应删去“地”，改为“一场年度晚会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27414, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一只年度大会在十二月举行。", "corrected_sentence": "一场年度大会在十二月举行。", "error_description": "量词错误：“大会”的量词应为“场”，“只”不能用来修饰“大会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
