INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27416, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示事情做完了。", "primary_collocate": null, "pronunciation": "yǐ", "ipa": "i˨˩˦", "syllable_count": 1, "sentences": [{"text": "作业已写完，可以玩了。", "target_word": "已", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "饭已做好，快来吃吧。", "target_word": "已", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "车票已买好，明天出发。", "target_word": "已", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "信已寄出，请放心。", "target_word": "已", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "衣服已洗好，放在床上。", "target_word": "已", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "客人已到，请你开门。", "target_word": "已", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "会已开完，大家回家吧。", "target_word": "已", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "钱已付了，不用再给。", "target_word": "已", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "门已关好，你放心走吧。", "target_word": "已", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件事我已告诉他了。", "target_word": "已", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "已经", "label": "复合"}], "register": "书面", "sense_fingerprint": "副词，用在动词前，表示事情已经做完", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06ef7b24-878b-4d84-b099-4f00efa873d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27416, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "已", "is_correct": true, "explanation": "正确答案：已（yǐ），副词，表示事情已经做完。"}, {"text": "也", "is_correct": false, "explanation": "也（yě）与已（yǐ）韵母不同（e／i），意思是“也”，不表示事情完成。"}, {"text": "一", "is_correct": false, "explanation": "一（yī）与已（yǐ）声调不同（第一声／第三声），意思是“一”。"}, {"text": "亿", "is_correct": false, "explanation": "亿（yì）与已（yǐ）声调不同（第四声／第三声），意思是“亿”。"}, {"text": "雨", "is_correct": false, "explanation": "雨（yǔ）与已（yǐ）韵母不同（ü／i），意思是“雨”。"}], "explanations": {"已": "正确答案：已（yǐ），副词，表示事情已经做完。", "也": "也（yě）与已（yǐ）韵母不同（e／i），意思是“也”，不表示事情完成。", "一": "一（yī）与已（yǐ）声调不同（第一声／第三声），意思是“一”。", "亿": "亿（yì）与已（yǐ）声调不同（第四声／第三声），意思是“亿”。", "雨": "雨（yǔ）与已（yǐ）韵母不同（ü／i），意思是“雨”。"}, "sentence_index": null, "correct_answer": "已"}, "level_3": {"options": [{"text": "已", "is_correct": true, "explanation": "已表示“写完”这件事已经发生，与“写完，可以玩了”的语境相符。"}, {"text": "正在", "is_correct": false, "explanation": "语义：“正在”表示动作进行中，与“写完”的完成义矛盾。"}, {"text": "还", "is_correct": false, "explanation": "语义：“还”表示仍然，与“作业写完、可以玩了”的完成义不符。"}, {"text": "未", "is_correct": false, "explanation": "语义：“未”表示没有，“未写完”与“可以玩了”矛盾。"}], "explanations": {"已": "已表示“写完”这件事已经发生，与“写完，可以玩了”的语境相符。", "正在": "语义：“正在”表示动作进行中，与“写完”的完成义矛盾。", "还": "语义：“还”表示仍然，与“作业写完、可以玩了”的完成义不符。", "未": "语义：“未”表示没有，“未写完”与“可以玩了”矛盾。"}, "sentence_index": 0, "correct_answer": "已"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们明天已去北京。", "explanation": "这里应该用〈将〉。已表示动作已经完成，“明天”指将来，不能与已搭配，应说“我们明天将去北京”。"}, {"text": "他下个月已毕业。", "explanation": "这里应该用〈要〉。已表示动作已经完成，“下个月”尚未到来，将要发生的事应说“他下个月要毕业”。"}, {"text": "他明天已回来。", "explanation": "这里应该用〈会〉。已表示已经完成，“明天”是将来，不能用已，应说“他明天会回来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27416, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "已", "is_correct": true, "explanation": "正确答案：已（yǐ），副词，表示事情已经做完。"}, {"text": "衣", "is_correct": false, "explanation": "衣（yī）与已（yǐ）声调不同（第一声／第三声），意思是“衣服”。"}, {"text": "姨", "is_correct": false, "explanation": "姨（yí）与已（yǐ）声调不同（第二声／第三声），意思是“阿姨”。"}, {"text": "意", "is_correct": false, "explanation": "意（yì）与已（yǐ）声调不同（第四声／第三声），意思是“意思”。"}, {"text": "语", "is_correct": false, "explanation": "语（yǔ）与已（yǐ）韵母不同（ü／i），意思是“语言”。"}], "explanations": {"已": "正确答案：已（yǐ），副词，表示事情已经做完。", "衣": "衣（yī）与已（yǐ）声调不同（第一声／第三声），意思是“衣服”。", "姨": "姨（yí）与已（yǐ）声调不同（第二声／第三声），意思是“阿姨”。", "意": "意（yì）与已（yǐ）声调不同（第四声／第三声），意思是“意思”。", "语": "语（yǔ）与已（yǐ）韵母不同（ü／i），意思是“语言”。"}, "sentence_index": null, "correct_answer": "已"}, "level_3": {"options": [{"text": "已", "is_correct": true, "explanation": "已表示会议已经开完，与“大家回家吧”的语境相符。"}, {"text": "将", "is_correct": false, "explanation": "语义：“将”表示将来，“会将开完”与“大家回家吧”矛盾。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”表示过去的经历，与“会开完”的当下完成义不合。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”表示持续，不能与“开完”这种瞬时完成的动作搭配。"}], "explanations": {"已": "已表示会议已经开完，与“大家回家吧”的语境相符。", "将": "语义：“将”表示将来，“会将开完”与“大家回家吧”矛盾。", "曾经": "语义：“曾经”表示过去的经历，与“会开完”的当下完成义不合。", "一直": "搭配：“一直”表示持续，不能与“开完”这种瞬时完成的动作搭配。"}, "sentence_index": 6, "correct_answer": "已"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天已吃早饭。", "explanation": "这里应该用〈总〉。已表示某件事已经完成，每天重复的习惯动作不能用已，应说“我每天总吃早饭”。"}, {"text": "请你已坐下，我们开始吧。", "explanation": "这里应该用〈先〉。已表示动作已经完成，请对方做某事要用“先”表示先后，应说“请你先坐下”。"}, {"text": "请你已说一遍。", "explanation": "这里应该用〈再〉。已表示动作已经完成，要求对方重复做某事要用“再”，应说“请你再说一遍”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27416, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐已没收拾好房间。", "corrected_sentence": "姐姐已收拾好房间。", "error_description": "“已”表示动作已经完成，与否定词“没”放在同一动作上互相矛盾（“没收拾好”指未完成）；应去掉“没”。若要表示尚未完成，应改用“还没”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27416, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把已作业写完了。", "corrected_sentence": "他已把作业写完了。", "error_description": "错误：“他把已作业写完了”。正确：“他已把作业写完了”。“已”是副词，要放在“把”字结构之前，不能夹在“把”和宾语之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
