INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27418, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做一件事时，最重要的那一步。", "primary_collocate": null, "pronunciation": "guān jiàn bù zhòu", "ipa": "kwan˥ tɕjɛn˥˩ pu˥˩ ʈʂoʊ̯˥˩", "syllable_count": 4, "sentences": [{"text": "买房子时，签合同是关键步骤。", "target_word": "关键步骤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学游泳的关键步骤是不怕水。", "target_word": "关键步骤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做蛋糕时，搅拌是关键步骤，不能太快。", "target_word": "关键步骤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "写作文的关键步骤，是先想好题目。", "target_word": "关键步骤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他找到了解决问题的关键步骤。", "target_word": "关键步骤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "种花的关键步骤是选对时间。", "target_word": "关键步骤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这一步是整个工作的关键步骤。", "target_word": "关键步骤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坐飞机前，换登机牌是关键步骤。", "target_word": "关键步骤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你知道这件事的关键步骤是什么吗？", "target_word": "关键步骤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师把关键步骤写在黑板上，让大家照着做。", "target_word": "关键步骤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个关键步骤", "label": "量词"}, {"form": "關鍵步驟", "label": "繁体"}], "register": "中性", "sense_fingerprint": "关键步骤|做一件事时最重要的那一步", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0340599b-d1b3-4420-a126-e8eea9bfd3af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27418, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "关键步骤", "is_correct": true, "explanation": "指做事情中最重要的一步，签合同正是买房的关键一步。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：签合同是买房的必经环节，不是装饰品。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体型，与签合同无关。"}, {"text": "玩笑", "is_correct": false, "explanation": "语义：签合同是正式的法律行为，不是玩笑。"}], "explanations": {"关键步骤": "指做事情中最重要的一步，签合同正是买房的关键一步。", "装饰": "语义：签合同是买房的必经环节，不是装饰品。", "身材": "体貌：“身材”指人的体型，与签合同无关。", "玩笑": "语义：签合同是正式的法律行为，不是玩笑。"}, "sentence_index": 0, "correct_answer": "关键步骤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是这部戏的关键步骤。", "explanation": "这里应该用〈关键角色〉。“步骤”指做事的环节，不指戏里的人物。"}, {"text": "我把关键步骤放进了书包里。", "explanation": "这里应该用〈课本〉。“关键步骤”是做事的环节，不是能放进书包的东西。"}, {"text": "他是我最好的关键步骤。", "explanation": "这里应该用〈伙伴〉。“关键步骤”不能用来指人，应说“最好的伙伴”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27418, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "关键步骤", "is_correct": true, "explanation": "指整个工作中最重要的一步，与句中“是……的”的判断相符。"}, {"text": "颜值", "is_correct": false, "explanation": "体貌：“颜值”指外貌好看的程度，是口语说法，不能用来形容工作的步骤。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：宠物是动物，不能是工作中的一个步骤。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：这一步是整个工作的重要环节，不能是玩具。"}], "explanations": {"关键步骤": "指整个工作中最重要的一步，与句中“是……的”的判断相符。", "颜值": "体貌：“颜值”指外貌好看的程度，是口语说法，不能用来形容工作的步骤。", "宠物": "语义：宠物是动物，不能是工作中的一个步骤。", "玩具": "语义：这一步是整个工作的重要环节，不能是玩具。"}, "sentence_index": 6, "correct_answer": "关键步骤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈煮了关键步骤。", "explanation": "这里应该用〈饭〉。步骤不能被煮，应说“煮饭”。"}, {"text": "他穿了一件新的关键步骤去上班。", "explanation": "这里应该用〈衣服〉。“关键步骤”是做事的环节，不能穿在身上。"}, {"text": "这一下午的关键步骤很好闻。", "explanation": "这里应该用〈饭菜〉。步骤没有气味，“好闻”只用于有气味的事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27418, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们已经确定了关键步骤们。", "corrected_sentence": "他们已经确定了关键步骤。", "error_description": "“们”只用于指人的名词，“步骤”不能加“们”，应为“他们已经确定了关键步骤”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27418, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一步是整个工作的一只关键步骤。", "corrected_sentence": "这一步是整个工作的一个关键步骤。", "error_description": "量词错误：“步骤”的量词应为“个”，“只”不能用来修饰“步骤”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
