INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27420, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做事情或说话时，要遵守的规则或标准。", "primary_collocate": null, "pronunciation": "yuán zé", "ipa": "ɥɛn˧˥ tsɤ˧˥", "syllable_count": 2, "sentences": [{"text": "我们公司的原则是：先听客人说完。", "target_word": "原则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "遇到困难时，我们也要坚持原则。", "target_word": "原则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做事有自己的原则，从来不说假话。", "target_word": "原则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸常说，做人要讲原则。", "target_word": "原则", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她从来不破坏原则，也不占别人的便宜。", "target_word": "原则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买东西时，我有自己的原则：不用信用卡。", "target_word": "原则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们定了三条原则，大家都要记住。", "target_word": "原则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "按照原则办事，大家才会觉得公平。", "target_word": "原则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是原则问题，谁也不能让步。", "target_word": "原则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子小的时候，父母要说明家里的原则。", "target_word": "原则", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条原则", "label": "量词"}, {"form": "原则性", "label": "复合"}, {"form": "原则上", "label": "复合"}, {"form": "原則", "label": "繁体"}], "register": "中性", "sense_fingerprint": "原则|做事说话要遵守的规则或标准", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0340599b-d1b3-4420-a126-e8eea9bfd3af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27420, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "早餐", "is_correct": false, "explanation": "语义：早餐是饮食，不能说“公司的早餐是先听客人说完”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与做事的规则无关，句意不通。"}, {"text": "原则", "is_correct": true, "explanation": "正确：“原则”指做事遵守的标准，与“公司的……是”搭配，句意通顺。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”不能用来说明公司的行事标准，搭配不当。"}], "explanations": {"早餐": "语义：早餐是饮食，不能说“公司的早餐是先听客人说完”。", "颜色": "语义：颜色与做事的规则无关，句意不通。", "原则": "正确：“原则”指做事遵守的标准，与“公司的……是”搭配，句意通顺。", "身高": "搭配：“身高”不能用来说明公司的行事标准，搭配不当。"}, "sentence_index": 0, "correct_answer": "原则"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张桌子的原则是红木做的。", "explanation": "这里应该用〈材料〉。材料指制作物品所用的东西，原则指做事依据的标准，不能用来说桌子是什么木料做的。"}, {"text": "她的原则很温柔，大家都愿意和她做朋友。", "explanation": "这里应该用〈性格〉。性格指一个人的心理特征，原则不能用来形容人的温柔。"}, {"text": "这块地的原则是三百平方米。", "explanation": "这里应该用〈面积〉。面积指平面的大小，原则指做事依据的标准，不能用来说地有多大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27420, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "河流", "is_correct": false, "explanation": "语义：河流不能被“定”，“老师给我们定了三条河流”句意不通。"}, {"text": "原则", "is_correct": true, "explanation": "正确：“三条原则”指三项需要遵守的标准，与“定了”搭配，句意完整。"}, {"text": "裤子", "is_correct": false, "explanation": "语义：裤子是衣物，不能由老师来制定。"}, {"text": "围巾", "is_correct": false, "explanation": "搭配：“定了”与“围巾”搭配不当，不能说定围巾。"}], "explanations": {"河流": "语义：河流不能被“定”，“老师给我们定了三条河流”句意不通。", "原则": "正确：“三条原则”指三项需要遵守的标准，与“定了”搭配，句意完整。", "裤子": "语义：裤子是衣物，不能由老师来制定。", "围巾": "搭配：“定了”与“围巾”搭配不当，不能说定围巾。"}, "sentence_index": 6, "correct_answer": "原则"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜的原则很辣，很多人都爱吃。", "explanation": "这里应该用〈味道〉。味道指食物的口感，原则不能用来形容菜的辣度。"}, {"text": "我今天的原则很好，想出去玩。", "explanation": "这里应该用〈心情〉。心情指一时的情绪，原则不表示人的情绪状态。"}, {"text": "车站的原则在北边。", "explanation": "这里应该用〈位置〉。位置指所在的地点，原则不表示地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27420, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们定了一只原则，大家都要遵守。", "corrected_sentence": "他们定了一条原则，大家都要遵守。", "error_description": "量词错误：“原则”的量词应为“条”，“只”不能用来修饰“原则”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27420, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她做事很原则性，从不乱来。", "corrected_sentence": "她做事很有原则性，从不乱来。", "error_description": "动词缺失：“很”后接名词性词语需加动词“有”，应说“很有原则性”，不能直接说“很原则性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27422, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隐瞒", "is_correct": true, "explanation": "隐瞒：不让人知道，与披露构成反义关系。"}, {"text": "扩大", "is_correct": false, "explanation": "扩大指范围变大，与披露没有对立关系。"}, {"text": "访问", "is_correct": false, "explanation": "访问指去拜访或查询，与披露不构成反义。"}, {"text": "维持", "is_correct": false, "explanation": "维持指保持现状，与披露没有反义关系。"}], "correct_answer": "隐瞒", "explanations": {"隐瞒": "隐瞒：不让人知道，与披露构成反义关系。", "扩大": "扩大指范围变大，与披露没有对立关系。", "访问": "访问指去拜访或查询，与披露不构成反义。", "维持": "维持指保持现状，与披露没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
