INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27428, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东西上破的一个小洞。", "primary_collocate": null, "pronunciation": "lòu dòng", "ipa": "lou˥˩ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "雨伞上有个漏洞，下雨会漏水。", "target_word": "漏洞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水壶底下有一个小漏洞。", "target_word": "漏洞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上的漏洞让冷风吹进来了。", "target_word": "漏洞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船底有漏洞，水慢慢流了进来。", "target_word": "漏洞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用布把桶上的漏洞堵住了。", "target_word": "漏洞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帐篷有漏洞，晚上蚊子飞进来了。", "target_word": "漏洞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋顶的漏洞太大，下雨时家里到处是水。", "target_word": "漏洞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个旧水管已经有好几个漏洞了。", "target_word": "漏洞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水桶有漏洞，水一会儿就漏光了。", "target_word": "漏洞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先找到桶上的漏洞在哪儿，再想办法补。", "target_word": "漏洞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个漏洞", "label": "量词"}], "register": "中性", "sense_fingerprint": "东西上破了的小洞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0340599b-d1b3-4420-a126-e8eea9bfd3af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27428, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "漏洞", "is_correct": true, "explanation": "正确：漏洞指东西上破的小洞，雨伞上有这样的洞才会漏水。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不会造成雨伞漏水，与句中的漏水结果无关。"}, {"text": "节目", "is_correct": false, "explanation": "语义：节目不是雨伞上的东西，与下雨漏水无关。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：雨伞上一般说有花纹或破洞，“味道”不能附着在雨伞上。"}], "explanations": {"漏洞": "正确：漏洞指东西上破的小洞，雨伞上有这样的洞才会漏水。", "颜色": "语义：颜色不会造成雨伞漏水，与句中的漏水结果无关。", "节目": "语义：节目不是雨伞上的东西，与下雨漏水无关。", "味道": "搭配：雨伞上一般说有花纹或破洞，“味道”不能附着在雨伞上。"}, "sentence_index": 0, "correct_answer": "漏洞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个茶杯上的漏洞很漂亮，我舍不得用。", "explanation": "漏洞指破损的小洞，漂亮的图样要用〈花纹〉。"}, {"text": "妈妈在碗上画了一个漏洞。", "explanation": "漏洞是破损处，不能用“画”来制作，这里应该用〈图案〉。"}, {"text": "院子里种了一个漏洞，每天都要浇水。", "explanation": "漏洞是破损的小洞，不能种植，这里说的是植物，应该用〈树苗〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27428, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "漏洞", "is_correct": true, "explanation": "正确：漏洞指东西上破的洞，屋顶有这样的洞，家里才会到处是水。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不会让家里到处是水，与句中的漏水结果无关。"}, {"text": "脾气", "is_correct": false, "explanation": "配价：“脾气”需要有生命的主语，屋顶不能有脾气。"}, {"text": "胃口", "is_correct": false, "explanation": "语义：胃口说的是食欲，与屋顶的状况无关。"}], "explanations": {"漏洞": "正确：漏洞指东西上破的洞，屋顶有这样的洞，家里才会到处是水。", "声音": "语义：声音不会让家里到处是水，与句中的漏水结果无关。", "脾气": "配价：“脾气”需要有生命的主语，屋顶不能有脾气。", "胃口": "语义：胃口说的是食欲，与屋顶的状况无关。"}, "sentence_index": 6, "correct_answer": "漏洞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子的漏洞很结实，坐上去很舒服。", "explanation": "漏洞是破损的小洞，不会“结实”，这里说的是椅子的部件，应该用〈椅腿〉。"}, {"text": "今晚的漏洞是一场音乐会。", "explanation": "漏洞是东西上破损的小洞，不是活动，这里应该用〈活动〉。"}, {"text": "我们要把这个漏洞送给朋友。", "explanation": "漏洞是破损处，不能当作礼物送人，这里应该用〈礼物〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27428, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块木板上有一只漏洞，要赶快修。", "corrected_sentence": "这块木板上有一个漏洞，要赶快修。", "error_description": "量词错误：“漏洞”的量词应为“个”，“只”不能用来修饰“漏洞”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27428, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋顶地漏洞已经修好了。", "corrected_sentence": "屋顶的漏洞已经修好了。", "error_description": "结构助词错误：修饰名词“漏洞”应用“的”，“地”用于修饰动词、形容词，写成“地漏洞”不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
