INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27432, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "条款就是写下来的规则或条件。", "primary_collocate": null, "pronunciation": "tiáo kuǎn", "ipa": "tʰiɑʊ³⁵ kʰuan²¹⁴", "syllable_count": 2, "sentences": [{"text": "租房的时候，要先看清楚条款。", "target_word": "条款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的退货条款很简单。", "target_word": "条款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用这个软件，你要同意它的条款。", "target_word": "条款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "条款上写着，三天内可以退钱。", "target_word": "条款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛有几项条款，大家要记住。", "target_word": "条款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些条款是公司定的。", "target_word": "条款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把条款重新读了一遍。", "target_word": "条款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对其中一项条款有意见。", "target_word": "条款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "条款里没有写这个问题。", "target_word": "条款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们改了条款，价格也变了。", "target_word": "条款", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "條款", "label": "繁体"}, {"form": "项", "label": "量词"}, {"form": "条", "label": "量词"}], "register": "书面", "sense_fingerprint": "写下来的规则或条件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9731bc0-27a4-4e2f-ae72-9377691b0db9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27432, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "条款", "is_correct": true, "explanation": "条款指写下来的规则或条件，租房时要看清楚，符合句意。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：租房时需要看清楚的是写下来的规则，花瓶不是要看清楚的内容。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头与租房的规则无关，「看清楚石头」与语境不符。"}, {"text": "气球", "is_correct": false, "explanation": "语境：租房时没有需要看清楚的气球，「看清楚气球」与句意不符。"}], "explanations": {"条款": "条款指写下来的规则或条件，租房时要看清楚，符合句意。", "花瓶": "语义：租房时需要看清楚的是写下来的规则，花瓶不是要看清楚的内容。", "石头": "语义：石头与租房的规则无关，「看清楚石头」与语境不符。", "气球": "语境：租房时没有需要看清楚的气球，「看清楚气球」与句意不符。"}, "sentence_index": 0, "correct_answer": "条款"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这碗汤的条款很鲜，大家都喜欢。", "explanation": "这里应该用〈味道〉。条款指写下来的规则或条件，不指食物的滋味；说汤鲜，应说“味道很鲜”。"}, {"text": "这条河的条款很长。", "explanation": "这里应该用〈河道〉。条款指写下来的规则或条件，不指河流；说这条河很长，应说“河道很长”。"}, {"text": "他的条款很高，打篮球很厉害。", "explanation": "这里应该用〈个子〉。条款指写下来的规则或条件，不能用来形容身高；形容人高，应说“个子很高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27432, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "条款", "is_correct": true, "explanation": "条款指写下来的规则，「我把条款重新读了一遍」符合句意。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不能被「读」，「我把蛋糕重新读了一遍」与句意不符。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不能被「读」，「把月亮重新读了一遍」不成立。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不是可以阅读的对象，「把花园重新读了一遍」与语境不符。"}], "explanations": {"条款": "条款指写下来的规则，「我把条款重新读了一遍」符合句意。", "蛋糕": "语义：蛋糕不能被「读」，「我把蛋糕重新读了一遍」与句意不符。", "月亮": "语义：月亮不能被「读」，「把月亮重新读了一遍」不成立。", "花园": "语义：花园不是可以阅读的对象，「把花园重新读了一遍」与语境不符。"}, "sentence_index": 6, "correct_answer": "条款"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这扇窗户的条款很干净，阳光很好。", "explanation": "这里应该用〈玻璃〉。条款指写下来的规则或条件，不指窗户的干净程度；说玻璃干净，应说“玻璃很干净”。"}, {"text": "这个房间的条款很高，热得让人出汗。", "explanation": "这里应该用〈温度〉。条款指写下来的规则或条件，不指冷热程度；说房间温度高，应说“温度很高”。"}, {"text": "这块地毯的条款很漂亮，铺在客厅正合适。", "explanation": "这里应该用〈花色〉。条款指写下来的规则或条件，不指地毯的图案；说图案漂亮，应说“花色很漂亮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27432, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "租房前，要仔细看清楚房东写的一把条款。", "corrected_sentence": "租房前，要仔细看清楚房东写的一项条款。", "error_description": "量词错误：条款应用「项」或「条」，「把」用于有柄的器具，不能修饰条款。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27432, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些条款们对大家很重要。", "corrected_sentence": "这些条款对大家很重要。", "error_description": "词缀错误：条款是抽象名词，不加「们」；「这些条款们」错误，应直接说「这些条款」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
