INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27434, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "按事物的性质或特征划分出的种类。", "primary_collocate": null, "pronunciation": "lèi bié", "ipa": "lei˥˩ pjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "这两种花的类别很容易分清。", "target_word": "类别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要先划清类别，再整理东西。", "target_word": "类别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把衣服按类别分开放好。", "target_word": "类别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个类别之间没有明确的界线。", "target_word": "类别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们分清动物的类别。", "target_word": "类别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同类别的垃圾要放进不同的桶。", "target_word": "类别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几本书类别不同，不能放在一起。", "target_word": "类别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在表格里写清楚人员的类别。", "target_word": "类别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生和老师属于不同的类别。", "target_word": "类别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些东西类别不同，要分开放。", "target_word": "类别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个类别", "label": "量词"}, {"form": "類別", "label": "繁体"}], "register": "中性", "sense_fingerprint": "按性质或特征划分出的种类", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e616806e-61bf-4de6-8b15-ca92d8620822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27434, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "类别", "is_correct": true, "explanation": "正确：指两种花各自所属的种类，“很容易分清”说的正是这两种花的类别，符合句意。"}, {"text": "学费", "is_correct": false, "explanation": "语义：花的“学费”与分清两种花毫无关系，句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“分清”不能与“体重”搭配，说花的体重不能被“分清”。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”是劳动报酬，不能用来说明两种花的区别。"}], "explanations": {"类别": "正确：指两种花各自所属的种类，“很容易分清”说的正是这两种花的类别，符合句意。", "学费": "语义：花的“学费”与分清两种花毫无关系，句意不通。", "体重": "搭配：“分清”不能与“体重”搭配，说花的体重不能被“分清”。", "工资": "语义：“工资”是劳动报酬，不能用来说明两种花的区别。"}, "sentence_index": 0, "correct_answer": "类别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两种花的类别是颜色不同。", "explanation": "这里应该用〈区别〉。类别指按性质划分的种类，“颜色不同”说的是差异，不是种类；说差异应用区别。"}, {"text": "这件衣服的类别是三百块钱。", "explanation": "这里应该用〈价格〉。类别指按性质划分的种类，不能表示多少钱；说多少钱应用价格。"}, {"text": "这两个城市之间的类别有一百公里。", "explanation": "这里应该用〈距离〉。类别指种类，不能表示远近；说两地远近应用距离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0820b03-5790-418e-b985-0acbbf7b8a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27434, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "类别", "is_correct": true, "explanation": "正确：指书的种类，“不同，不能放在一起”说的正是类别不同，符合句意。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”指人的品性，书没有性格，句意不通。"}, {"text": "学历", "is_correct": false, "explanation": "搭配：“学历”只用于人，书不能说“学历不同”。"}, {"text": "国籍", "is_correct": false, "explanation": "语义：“国籍”指人所属的国家，书没有国籍，句意不通。"}], "explanations": {"类别": "正确：指书的种类，“不同，不能放在一起”说的正是类别不同，符合句意。", "性格": "语义：“性格”指人的品性，书没有性格，句意不通。", "学历": "搭配：“学历”只用于人，书不能说“学历不同”。", "国籍": "语义：“国籍”指人所属的国家，书没有国籍，句意不通。"}, "sentence_index": 6, "correct_answer": "类别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子的类别很重。", "explanation": "这里应该用〈重量〉。类别指种类，不能用来表示轻重；说轻重应用重量。"}, {"text": "他的类别比去年高了不少。", "explanation": "这里应该用〈身高〉。类别指种类，不能表示身体的高矮；说高矮应用身高。"}, {"text": "这首歌的类别很动听。", "explanation": "这里应该用〈旋律〉。类别指种类，不能用来形容好听；说动听应指旋律。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0820b03-5790-418e-b985-0acbbf7b8a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27434, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师要求我们划清这两个类别们的界线。", "corrected_sentence": "老师要求我们划清这两个类别的界线。", "error_description": "词形错误：“们”只用于指人的复数，“类别”是事物名词，不能加“们”，应说“这两个类别的界线”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0820b03-5790-418e-b985-0acbbf7b8a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27434, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两只类别之间的界线很明显。", "corrected_sentence": "这两个类别之间的界线很明显。", "error_description": "量词错误：类别的量词应该用“个”，不能用“只”。正确的说法是“这两个类别”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0820b03-5790-418e-b985-0acbbf7b8a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
