INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27440, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个地方发生的一件事情，就像在电影里看到的那样。", "primary_collocate": null, "pronunciation": "chǎng jǐng", "ipa": "tʂʰɑŋ˨˩˦ tɕiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "机场里亲人见面的场景很感人。", "target_word": "场景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个场景我到现在还记得。", "target_word": "场景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到火车站的送别场景，我哭了。", "target_word": "场景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路边那对老人互相搀扶的场景，让路人都停下了脚步。", "target_word": "场景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在公园玩的场景真可爱。", "target_word": "场景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个场景好像在电影里见过。", "target_word": "场景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜市场里热闹的场景让他想起家乡。", "target_word": "场景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想把这个场景拍下来。", "target_word": "场景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一家人吃饭的场景总是很温暖。", "target_word": "场景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天都会想起那天海边的场景。", "target_word": "场景", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个场景", "label": "量词"}, {"form": "生活场景", "label": "复合"}], "register": "中性", "sense_fingerprint": "场景：某地发生的一件事，像电影画面一样让人看到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ff47f7-e50e-4937-9c6f-4d98586d83d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27440, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "场景", "is_correct": true, "explanation": "正确。这里指在机场发生的亲人见面的情形，“很感人”形容这样的场景。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不能让人感动，“很感人”不能修饰价格。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不能用来形容令人感动的情形，“感人”修饰的是事件或画面。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李是物品，不能是令人感动的情形，与“很感人”不合。"}], "explanations": {"场景": "正确。这里指在机场发生的亲人见面的情形，“很感人”形容这样的场景。", "价格": "语义：价格不能让人感动，“很感人”不能修饰价格。", "味道": "语义：味道不能用来形容令人感动的情形，“感人”修饰的是事件或画面。", "行李": "语义：行李是物品，不能是令人感动的情形，与“很感人”不合。"}, "sentence_index": 0, "correct_answer": "场景"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事给他的场景很深。", "explanation": "这里应该用〈印象〉。“很深”形容印象，场景指某地发生的一件事，不能说“深”。"}, {"text": "这道菜的场景很香。", "explanation": "这里应该用〈味道〉。“香”形容味道，场景指某地发生的一件事，不能说“香”。"}, {"text": "这首歌的场景很快。", "explanation": "这里应该用〈节奏〉。“快”描述音乐的节奏，场景不能用来描述速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27440, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "场景", "is_correct": true, "explanation": "正确。这里指菜市场里热闹的情形，与“热闹的”搭配，并让人想起家乡。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能用“热闹”来形容，这句话无法成立。"}, {"text": "心跳", "is_correct": false, "explanation": "搭配：“热闹”修饰场面或声音，不修饰心跳。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单不能是热闹的，这句话在语义上说不通。"}], "explanations": {"场景": "正确。这里指菜市场里热闹的情形，与“热闹的”搭配，并让人想起家乡。", "天气": "语义：天气不能用“热闹”来形容，这句话无法成立。", "心跳": "搭配：“热闹”修饰场面或声音，不修饰心跳。", "账单": "语义：账单不能是热闹的，这句话在语义上说不通。"}, "sentence_index": 6, "correct_answer": "场景"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位主持人的场景很流利。", "explanation": "这里应该用〈发言〉。“流利”形容说话的表达，场景指某地发生的一件事，不能形容讲话的熟练程度。"}, {"text": "这把小提琴的场景很清亮。", "explanation": "这里应该用〈声音〉。“清亮”形容声音，场景是某地发生的一件事，不能形容声音。"}, {"text": "他打篮球的场景很利落。", "explanation": "这里应该用〈动作〉。“利落”形容动作，场景不能用来描述动作是否利落。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27440, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一本很温暖的场景。", "corrected_sentence": "这是一个很温暖的场景。", "error_description": "“场景”前应用通用量词“个”；“本”用于书册等，不能用来数“场景”，故“这是一本很温暖的场景”错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27440, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这只场景讲得很生动。", "corrected_sentence": "他把这个场景讲得很生动。", "error_description": "“只”多用于动物、船只或成对物品中的一个，不能用来数“场景”；应改为“这个场景”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
