INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27446, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "写电脑程序时，人写的字和符号。", "primary_collocate": null, "pronunciation": "yuán dài mǎ", "ipa": "ɥɛn˧˥ taɪ̯˥˩ ma˨˩˦", "syllable_count": 3, "sentences": [{"text": "我写的源代码有一个错误。", "target_word": "源代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们看一下他的源代码。", "target_word": "源代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏的源代码很长。", "target_word": "源代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把源代码保存在电脑里。", "target_word": "源代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把源代码复制到了新文件里。", "target_word": "源代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "源代码里的符号不能写错。", "target_word": "源代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥正在电脑上写源代码。", "target_word": "源代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能帮我检查一下源代码吗？", "target_word": "源代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生交了作业，也交了源代码。", "target_word": "源代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些源代码是我自己写的。", "target_word": "源代码", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段源代码", "label": "量词"}, {"form": "一份源代码", "label": "量词"}, {"form": "开放源代码", "label": "复合"}, {"form": "源代碼", "label": "繁体"}], "register": "中性", "sense_fingerprint": "写程序时人亲手写下的文字和符号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e616806e-61bf-4de6-8b15-ca92d8620822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27446, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "源代码", "is_correct": true, "explanation": "正确：源代码指写程序时人写下的文字和符号，与“写的”相符，句意是程序里有错误。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人写下的文字和符号，不能说写的天气。"}, {"text": "汤", "is_correct": false, "explanation": "搭配：“写”用于文字、程序，不说写汤。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是人写下的文字和符号，与“写的”不符。"}], "explanations": {"源代码": "正确：源代码指写程序时人写下的文字和符号，与“写的”相符，句意是程序里有错误。", "天气": "语义：天气不是人写下的文字和符号，不能说写的天气。", "汤": "搭配：“写”用于文字、程序，不说写汤。", "月亮": "语义：月亮不是人写下的文字和符号，与“写的”不符。"}, "sentence_index": 0, "correct_answer": "源代码"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他双击了这个源代码，游戏就启动了。", "explanation": "这里应该用“软件”。源代码是人写的字和符号，不能双击启动游戏；能启动游戏的是软件。"}, {"text": "数学公式里有很多源代码。", "explanation": "这里应该用“符号”。源代码指写程序时用的字和符号，数学公式里的应说符号，不能说源代码。"}, {"text": "这台电脑的源代码很重，要两个人才能抬动。", "explanation": "这里应该用“主机”。源代码是人写的字和符号，没有重量；说电脑的重量应用主机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0820b03-5790-418e-b985-0acbbf7b8a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27446, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "源代码", "is_correct": true, "explanation": "正确：源代码是写程序用的文字和符号，在电脑上书写的正是它，与句意相符。"}, {"text": "面条", "is_correct": false, "explanation": "搭配：“写”用于文字、程序，不说写面条。"}, {"text": "火车", "is_correct": false, "explanation": "语义：火车是交通工具，不能在电脑上书写。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是地方，不是可以书写的文字或符号。"}], "explanations": {"源代码": "正确：源代码是写程序用的文字和符号，在电脑上书写的正是它，与句意相符。", "面条": "搭配：“写”用于文字、程序，不说写面条。", "火车": "语义：火车是交通工具，不能在电脑上书写。", "花园": "语义：花园是地方，不是可以书写的文字或符号。"}, "sentence_index": 6, "correct_answer": "源代码"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇作文的源代码写得很优美。", "explanation": "这里应该用“文字”。源代码指写程序时用的字和符号，不能用来形容作文的文字。"}, {"text": "他用这个源代码订了一张火车票。", "explanation": "这里应该用“程序”。源代码是写程序用的字和符号，本身不能用来订票。"}, {"text": "这部电影的源代码翻译得很准确。", "explanation": "这里应该用“字幕”。源代码指程序的字和符号，不能指电影的字幕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0820b03-5790-418e-b985-0acbbf7b8a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27446, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他下午把一棵源代码发给了同事。", "corrected_sentence": "他下午把一段源代码发给了同事。", "error_description": "错误：“一棵源代码”，应为“一段源代码”。“棵”用于树木，源代码的量词是段、份。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0820b03-5790-418e-b985-0acbbf7b8a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27446, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把一座源代码放进了邮件里。", "corrected_sentence": "他把一份源代码放进了邮件里。", "error_description": "错误：“一座源代码”，应为“一份源代码”。“座”用于山、建筑等大型固定物，源代码的量词是段、份。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0820b03-5790-418e-b985-0acbbf7b8a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
