INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27454, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "文档是写了很多字的一张纸或一个电脑文件。", "primary_collocate": null, "pronunciation": "wén dàng", "ipa": "wən˧˥ tɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "桌子上有一份文档。", "target_word": "文档", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把文档打印出来了。", "target_word": "文档", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个文档里有很多字。", "target_word": "文档", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把文档放进了书包。", "target_word": "文档", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把文档发到我的邮箱。", "target_word": "文档", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的电脑里有三个文档。", "target_word": "文档", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在文档上写了自己的名字。", "target_word": "文档", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份文档太长，我看不完。", "target_word": "文档", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文档不见了，我找不到。", "target_word": "文档", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们打开电脑里的文档。", "target_word": "文档", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "文檔", "label": "繁体"}], "register": "中性", "sense_fingerprint": "写了很多字的一张纸或电脑文件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfaf90dd-f4b7-4419-b579-a42415751b5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27454, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文档", "is_correct": true, "explanation": "与“桌子上”搭配，指放在桌上的纸质文件，符合语境。"}, {"text": "感情", "is_correct": false, "explanation": "语义：感情是抽象的，不能放在桌子上。"}, {"text": "责任", "is_correct": false, "explanation": "语义：责任是抽象的，不能作为放在桌子上的东西。"}, {"text": "回忆", "is_correct": false, "explanation": "配价：“有一份……”后接的事物要能放在桌上，回忆是抽象的，不符合这一要求。"}], "explanations": {"文档": "与“桌子上”搭配，指放在桌上的纸质文件，符合语境。", "感情": "语义：感情是抽象的，不能放在桌子上。", "责任": "语义：责任是抽象的，不能作为放在桌子上的东西。", "回忆": "配价：“有一份……”后接的事物要能放在桌上，回忆是抽象的，不符合这一要求。"}, "sentence_index": 0, "correct_answer": "文档"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天吃了一份文档当午饭。", "explanation": "这里把“文档”误当成了食物。文档指写了很多字的纸张或电子文件，不能当午饭吃，应该用〈面包〉之类的食物。"}, {"text": "这份文档很可爱，我每天都抱着它玩。", "explanation": "这里把“文档”误当成了宠物或玩具。文档是写了很多字的纸张或电子文件，不能说“可爱”，也不能抱着玩，形容文字应该用〈清楚〉〈整齐〉。"}, {"text": "这份文档在河里游得很快。", "explanation": "文档没有游泳的能力，“游”的主语不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27454, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文档", "is_correct": true, "explanation": "与“写名字”搭配，指可以书写的纸或文件，符合语境。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不能作为书写的平面，与句意不符。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：不说在“年龄”上写名字，二者不构成搭配。"}, {"text": "空气", "is_correct": false, "explanation": "配价：“在……上写”要求具体的书写平面，空气不能作为书写的平面。"}], "explanations": {"文档": "与“写名字”搭配，指可以书写的纸或文件，符合语境。", "时间": "语义：时间不能作为书写的平面，与句意不符。", "年龄": "搭配：不说在“年龄”上写名字，二者不构成搭配。", "空气": "配价：“在……上写”要求具体的书写平面，空气不能作为书写的平面。"}, "sentence_index": 6, "correct_answer": "文档"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把文档洗干净，放进了锅里。", "explanation": "这里把“文档”误当成了食材。文档指写了很多字的纸张或电子文件，不能清洗后放进锅里，应该用〈蔬菜〉之类的食材作宾语。"}, {"text": "我给文档穿上了新衣服。", "explanation": "这里把“文档”误当成了人或玩偶。文档是纸张或电子文件，不能穿衣服，应该用〈孩子〉或〈娃娃〉作“穿”的对象。"}, {"text": "这份文档喜欢听音乐，每天都唱歌。", "explanation": "文档没有生命，不会听音乐，也不会唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27454, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我已经把这只文档打印出来了。", "corrected_sentence": "我已经把这份文档打印出来了。", "error_description": "量词错误：“文档”应用〈份〉或〈个〉，“只”多用于动物，不能用来计量文档。正确形式是“这份文档”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27454, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些文档们都很重要。", "corrected_sentence": "这些文档都很重要。", "error_description": "错误：“文档”是物，不能加“们”表示复数。多个文档直接说“这些文档”即可，正确形式是“这些文档都很重要”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
