INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27458, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不一样的地方。", "primary_collocate": null, "pronunciation": "piān chā", "ipa": "pʰjɛn˥ ʈʂʰa˥", "syllable_count": 2, "sentences": [{"text": "我想的和实际的有偏差。", "target_word": "偏差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人说的话有一点偏差。", "target_word": "偏差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图和真实的路有偏差。", "target_word": "偏差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的时间和我记的有偏差。", "target_word": "偏差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两次称重的结果有偏差。", "target_word": "偏差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画和照片比起来，还是有偏差。", "target_word": "偏差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两张表上的数字有偏差。", "target_word": "偏差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的看法有偏差，需要谈一谈。", "target_word": "偏差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜谱上写的和我做的有偏差，味道不一样。", "target_word": "偏差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两块表的时间有偏差，相差五分钟。", "target_word": "偏差", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "标准偏差", "label": "复合"}, {"form": "偏差值", "label": "复合"}], "register": "中性", "sense_fingerprint": "两者之间不一样的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfaf90dd-f4b7-4419-b579-a42415751b5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27458, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偏差", "is_correct": true, "explanation": "正确：“偏差”指不一样的地方，“我想的和实际的有偏差”说的是两者不一致，与句意相符。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指人或事物存在的年数，不能说“想的和实际的有年龄”。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指气味或滋味，“想的和实际的有味道”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的身体特征，不能用来说想法和实际之间的关系。"}], "explanations": {"偏差": "正确：“偏差”指不一样的地方，“我想的和实际的有偏差”说的是两者不一致，与句意相符。", "年龄": "语义：“年龄”指人或事物存在的年数，不能说“想的和实际的有年龄”。", "味道": "语义：“味道”指气味或滋味，“想的和实际的有味道”说不通。", "身高": "体貌：“身高”指人的身体特征，不能用来说想法和实际之间的关系。"}, "sentence_index": 0, "correct_answer": "偏差"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家离学校的偏差是两公里。", "explanation": "这里应该用〈距离〉。“偏差”指不一样的地方，说两地之间的远近要用“距离”。"}, {"text": "这个偏差跑得很快。", "explanation": "这里应该用〈小狗〉。“跑”的主语要是人或动物；“偏差”指不一样的地方，是抽象的说法，不能跑。"}, {"text": "我昨天买了一个偏差。", "explanation": "这里应该用〈东西〉。“偏差”指不一样的地方，是抽象的说法，不是能买的东西，买东西要用“东西”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27458, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偏差", "is_correct": true, "explanation": "正确：“偏差”指不一样的地方，“数字有偏差”说的是两张表的数字不一致，与句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，数字不能有颜色，“数字有颜色”说不通。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”指听到的声响，数字不能有声音，“数字有声音”说不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，数字没有身材，这样说不成立。"}], "explanations": {"偏差": "正确：“偏差”指不一样的地方，“数字有偏差”说的是两张表的数字不一致，与句意相符。", "颜色": "语义：“颜色”指色彩，数字不能有颜色，“数字有颜色”说不通。", "声音": "语义：“声音”指听到的声响，数字不能有声音，“数字有声音”说不通。", "身材": "体貌：“身材”指人的体形，数字没有身材，这样说不成立。"}, "sentence_index": 6, "correct_answer": "偏差"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我的偏差。", "explanation": "这里应该用〈朋友〉。“偏差”指不一样的地方，是抽象的说法，不能用来指一个人，指人要说“朋友”。"}, {"text": "我把偏差放进了冰箱。", "explanation": "这里应该用〈水果〉。“偏差”指不一样的地方，是抽象的说法，不能放进冰箱。"}, {"text": "这个偏差很好吃。", "explanation": "这里应该用〈食物〉。“偏差”指不一样的地方，是抽象的说法，不能用来指可以吃的东西，要说“食物”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27458, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的估算和实际花费有一块偏差。", "corrected_sentence": "我的估算和实际花费有一点偏差。", "error_description": "量词错误：“偏差”用“点”，不用“块”。“块”多用于成块的东西，如“一块蛋糕”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27458, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两台仪器的读数有一份偏差。", "corrected_sentence": "这两台仪器的读数有一点偏差。", "error_description": "量词错误：“偏差”用“点”，不用“份”。“份”多用于文件或食物，如“一份报告”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
