INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27460, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "因为一个人的样子或想法不一样，就不公平地对他不好。", "primary_collocate": null, "pronunciation": "qí shì xìng", "ipa": "tɕʰi˧˥ ʂʐ̩˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "因为长相不同就笑人，这很有歧视性。", "target_word": "歧视性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话有歧视性，同学们都不高兴。", "target_word": "歧视性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不让她参加，只因为她想法不同，这很有歧视性。", "target_word": "歧视性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的称呼带有歧视性，请别用。", "target_word": "歧视性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师提醒大家，不要有歧视性的想法。", "target_word": "歧视性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个规定对外地人有歧视性。", "target_word": "歧视性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得这家店的态度有歧视性。", "target_word": "歧视性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只因为口音不同就冷落他，这是歧视性的行为。", "target_word": "歧视性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的笑话有歧视性，让新同学很难过。", "target_word": "歧视性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种歧视性的眼神让人不舒服。", "target_word": "歧视性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "非歧视性", "label": "复合"}, {"form": "歧視性", "label": "繁体"}], "register": "书面", "sense_fingerprint": "因样子或想法不同而不公平地待人不好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfaf90dd-f4b7-4419-b579-a42415751b5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27460, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歧视性", "is_correct": true, "explanation": "正确。「因为长相不同就笑人」正是因特征而不公平地对待，「歧视性」正合语境。"}, {"text": "观赏性", "is_correct": false, "explanation": "体貌：观赏性侧重好看、供人欣赏，与「笑人」的行为性质不符。"}, {"text": "透明性", "is_correct": false, "explanation": "语义：透明性指清楚可见、不隐藏，与“笑人”的行为无关，“这很有透明性”说不通。"}, {"text": "偶然性", "is_correct": false, "explanation": "语义：偶然性指事情不由确定原因决定，与「因为长相不同」的明确原因相反。"}], "explanations": {"歧视性": "正确。「因为长相不同就笑人」正是因特征而不公平地对待，「歧视性」正合语境。", "观赏性": "体貌：观赏性侧重好看、供人欣赏，与「笑人」的行为性质不符。", "透明性": "语义：透明性指清楚可见、不隐藏，与“笑人”的行为无关，“这很有透明性”说不通。", "偶然性": "语义：偶然性指事情不由确定原因决定，与「因为长相不同」的明确原因相反。"}, "sentence_index": 0, "correct_answer": "歧视性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条路很有歧视性。", "explanation": "这里应该用〈平坦〉。「路很平坦」形容路面；「歧视性」指因特征而不公平地区别对待，不能形容路。"}, {"text": "他的脚步很有歧视性。", "explanation": "这里应该用〈轻〉。「脚步很轻」形容走路的动作；「歧视性」不能用来形容脚步。"}, {"text": "这是一把歧视性的伞。", "explanation": "这里应该用〈红色〉。「红色的伞」说伞的颜色；「歧视性」指对人的不公平区别对待，不能用来修饰伞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27460, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歧视性", "is_correct": true, "explanation": "正确。「态度」对待外地人或新人时，不公平地因特征而区别对待，「歧视性」正合语境。"}, {"text": "娱乐性", "is_correct": false, "explanation": "语义：娱乐性指使人愉快，与「态度」对人的不公正评价无关。"}, {"text": "幽默性", "is_correct": false, "explanation": "语义：幽默性是积极特点，与句中对待他人的不公正态度相反。"}, {"text": "美观性", "is_correct": false, "explanation": "体貌：美观性指外观好看，不能用来描述对待他人的态度。"}], "explanations": {"歧视性": "正确。「态度」对待外地人或新人时，不公平地因特征而区别对待，「歧视性」正合语境。", "娱乐性": "语义：娱乐性指使人愉快，与「态度」对人的不公正评价无关。", "幽默性": "语义：幽默性是积极特点，与句中对待他人的不公正态度相反。", "美观性": "体貌：美观性指外观好看，不能用来描述对待他人的态度。"}, "sentence_index": 6, "correct_answer": "歧视性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家享有歧视性的权利。", "explanation": "这里应该用〈同样〉。「同样的权利」可以说；「歧视性」描述区别对待，不能说明权利的内容。"}, {"text": "两只小狗跑得很有歧视性。", "explanation": "这里应该用〈快〉。「跑得很快」形容速度；「歧视性」指对人的不公平区别对待，不能描述跑步。"}, {"text": "这座山很有歧视性。", "explanation": "这里应该用〈高〉。「山很高」形容山的高矮；「歧视性」不能用来形容山。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27460, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种眼神有很歧视性。", "corrected_sentence": "这种眼神很有歧视性。", "error_description": "语序错误：「有很歧视性」中「有」「很」次序颠倒。程度副词「很」应放在「有」之前，正确形式是「很有歧视性」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27460, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "只因为年纪大就不让他进门，这是歧视性地做法。", "corrected_sentence": "只因为年纪大就不让他进门，这是歧视性的做法。", "error_description": "错误：「歧视性」修饰名词「做法」要用「的」，不能用「地」。「地」用于修饰动词。正确形式是「歧视性的做法」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27462, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "凉快", "is_correct": false, "explanation": "与“合理”没有反义关系，指温度适中、不热。"}, {"text": "荒唐", "is_correct": true, "explanation": "与“合理”构成反义，指想法或做法不合道理、让人觉得奇怪。"}, {"text": "明亮", "is_correct": false, "explanation": "与“合理”没有反义关系，指光线充足。"}, {"text": "柔软", "is_correct": false, "explanation": "与“合理”没有反义关系，指质地软。"}], "correct_answer": "荒唐", "explanations": {"凉快": "与“合理”没有反义关系，指温度适中、不热。", "荒唐": "与“合理”构成反义，指想法或做法不合道理、让人觉得奇怪。", "明亮": "与“合理”没有反义关系，指光线充足。", "柔软": "与“合理”没有反义关系，指质地软。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021b7708-422e-43eb-844c-1e7609f00d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27462, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "富裕", "is_correct": false, "explanation": "与“合理”没有反义关系，指钱财多。"}, {"text": "清楚", "is_correct": false, "explanation": "与“合理”没有反义关系，指明白、不模糊。"}, {"text": "荒谬", "is_correct": true, "explanation": "与“合理”构成反义，指完全不合道理。"}, {"text": "陡峭", "is_correct": false, "explanation": "与“合理”没有反义关系，形容坡度大。"}], "correct_answer": "荒谬", "explanations": {"富裕": "与“合理”没有反义关系，指钱财多。", "清楚": "与“合理”没有反义关系，指明白、不模糊。", "荒谬": "与“合理”构成反义，指完全不合道理。", "陡峭": "与“合理”没有反义关系，形容坡度大。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021b7708-422e-43eb-844c-1e7609f00d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27462, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "事情做得对，不奇怪。", "primary_collocate": null, "pronunciation": "hé lǐ", "ipa": "xɤ˧˥ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "他生气是合理的，因为你迟到了。", "target_word": "合理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板这样做很合理，没有人不同意。", "target_word": "合理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事听起来不太合理。", "target_word": "合理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的想法很合理，我们试试吧。", "target_word": "合理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工资这么低，他不满意很合理。", "target_word": "合理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法合理，大家都能接受。", "target_word": "合理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的解释很合理，我不再问了。", "target_word": "合理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完饭休息一下是合理的。", "target_word": "合理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "迟到要道歉，这样的要求合理吗？", "target_word": "合理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的消费习惯很合理，从不乱花钱。", "target_word": "合理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "合理性", "label": "复合"}, {"form": "合理化", "label": "复合"}], "register": "中性", "sense_fingerprint": "合理|事情做得对，让人觉得不奇怪", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27fdbf91-5a57-494c-bcdf-8cffdfde2c0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27462, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”描写外貌，不能用来形容生气这种情绪是否说得通。"}, {"text": "甜蜜", "is_correct": false, "explanation": "语义：“甜蜜”指感情愉快，与“生气”的意思相矛盾。"}, {"text": "合理", "is_correct": true, "explanation": "正确：指生气符合事理、不奇怪，与“你迟到了”的原因相呼应。"}, {"text": "凉快", "is_correct": false, "explanation": "搭配：“凉快”用于天气或环境，不能描述生气这种情绪。"}], "explanations": {"漂亮": "语义：“漂亮”描写外貌，不能用来形容生气这种情绪是否说得通。", "甜蜜": "语义：“甜蜜”指感情愉快，与“生气”的意思相矛盾。", "合理": "正确：指生气符合事理、不奇怪，与“你迟到了”的原因相呼应。", "凉快": "搭配：“凉快”用于天气或环境，不能描述生气这种情绪。"}, "sentence_index": 0, "correct_answer": "合理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这双鞋的颜色很合理，我很喜欢。", "explanation": "这里应该用〈好看〉。合理指事情做得对、说得通，说颜色好看要用〈好看〉。"}, {"text": "这碗汤很合理，喝起来很舒服。", "explanation": "这里应该用〈合口味〉。合理指事情做得对，汤的味道对口要说〈合口味〉。"}, {"text": "这次考试的成绩合理了，大家都很高兴。", "explanation": "这里应该用〈合格〉。合理指事情做得对，成绩达到标准要说〈合格〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021b7708-422e-43eb-844c-1e7609f00d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27462, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”用于物体或天气，不能形容解释。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：“沉默”指不说话，与“解释很……，我不再问了”的意思不合。"}, {"text": "高大", "is_correct": false, "explanation": "语义：“高大”形容身材或体型，不能修饰解释。"}, {"text": "合理", "is_correct": true, "explanation": "正确：指解释说得通、不奇怪，与“我不再问了”的语境一致。"}], "explanations": {"潮湿": "搭配：“潮湿”用于物体或天气，不能形容解释。", "沉默": "语义：“沉默”指不说话，与“解释很……，我不再问了”的意思不合。", "高大": "语义：“高大”形容身材或体型，不能修饰解释。", "合理": "正确：指解释说得通、不奇怪，与“我不再问了”的语境一致。"}, "sentence_index": 6, "correct_answer": "合理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条裤子很合理，穿上很舒服。", "explanation": "这里应该用〈合身〉。合理指事情做得对，裤子尺寸贴身要说〈合身〉。"}, {"text": "这个笑话很合理，大家都笑得前仰后合。", "explanation": "这里应该用〈好笑〉。合理指事情做得对、说得通，说笑话让人发笑要用〈好笑〉。"}, {"text": "这首歌很合理，大家都很喜欢。", "explanation": "这里应该用〈好听〉。合理指事情做得对、说得通，说歌让人喜欢听要用〈好听〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021b7708-422e-43eb-844c-1e7609f00d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27462, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的想法变得合理着。", "corrected_sentence": "他的想法变得合理了。", "error_description": "错误在“着”：“变得合理”是已经完成的变化，应用“了”，不用“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021b7708-422e-43eb-844c-1e7609f00d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27462, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个解释讲很合理，大家都听懂了。", "corrected_sentence": "这个解释讲得很合理，大家都听懂了。", "error_description": "错误在“得”：“讲”后面带形容词作补语，要用“得”，应说“讲得很合理”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021b7708-422e-43eb-844c-1e7609f00d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
