INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27464, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "公平性就是每个人都能得到一样的对待，没有人被偏爱。", "primary_collocate": null, "pronunciation": "gōng píng xìng", "ipa": "kʊŋ˥ pʰiŋ˧˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "每个人都一样，这就是公平性。", "target_word": "公平性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈分苹果时，很注意公平性。", "target_word": "公平性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "排队买票体现了公平性。", "target_word": "公平性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游戏的公平性让大家都玩得开心。", "target_word": "公平性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想知道这个办法有没有公平性。", "target_word": "公平性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都有同样的机会，才有公平性。", "target_word": "公平性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给每人同样的时间，保证公平性。", "target_word": "公平性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们觉得这次分组缺少公平性。", "target_word": "公平性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛规则要讲究公平性。", "target_word": "公平性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也不偏爱，这样才有公平性。", "target_word": "公平性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "算法公平性", "label": "复合"}], "register": "书面", "sense_fingerprint": "每个人受到同样对待、无人被偏爱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfaf90dd-f4b7-4419-b579-a42415751b5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27464, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公平性", "is_correct": true, "explanation": "正确。「每个人都一样」说的就是公平性，即每个人受到同样对待。"}, {"text": "偶然性", "is_correct": false, "explanation": "语义：偶然性指事情不由规则决定，与「每个人都一样」的含义相反。"}, {"text": "独占性", "is_correct": false, "explanation": "语义：独占性指只归一方所有，与人人同样对待的含义相反。"}, {"text": "观赏性", "is_correct": false, "explanation": "体貌：观赏性侧重好看、供人欣赏，与「一样」的公平含义无关。"}], "explanations": {"公平性": "正确。「每个人都一样」说的就是公平性，即每个人受到同样对待。", "偶然性": "语义：偶然性指事情不由规则决定，与「每个人都一样」的含义相反。", "独占性": "语义：独占性指只归一方所有，与人人同样对待的含义相反。", "观赏性": "体貌：观赏性侧重好看、供人欣赏，与「一样」的公平含义无关。"}, "sentence_index": 0, "correct_answer": "公平性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个蛋糕的公平性很高。", "explanation": "这里应该用〈甜度〉。「甜度很高」说食物的甜味；「公平性」指对待的不偏不倚，不能形容蛋糕的味道。"}, {"text": "这朵花的公平性很鲜艳。", "explanation": "这里应该用〈颜色〉。「颜色很鲜艳」说花的色彩；「公平性」指对待的不偏不倚，不能形容花的颜色。"}, {"text": "他在浴室里洗公平性。", "explanation": "这里应该用〈碗〉。「洗」的对象是具体器物，「公平性」是抽象的对待方式，不能被洗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27464, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公平性", "is_correct": true, "explanation": "正确。老师给每人同样的时间，目的是保证公平，这正是「公平性」的意思。"}, {"text": "娱乐性", "is_correct": false, "explanation": "语义：娱乐性指使人愉快，与分配时间的公平无关。"}, {"text": "随意性", "is_correct": false, "explanation": "语义：随意性与「保证」相反，分配时间不能随意进行。"}, {"text": "美观性", "is_correct": false, "explanation": "体貌：美观性侧重外观，与分配时间的公平无关。"}], "explanations": {"公平性": "正确。老师给每人同样的时间，目的是保证公平，这正是「公平性」的意思。", "娱乐性": "语义：娱乐性指使人愉快，与分配时间的公平无关。", "随意性": "语义：随意性与「保证」相反，分配时间不能随意进行。", "美观性": "体貌：美观性侧重外观，与分配时间的公平无关。"}, "sentence_index": 6, "correct_answer": "公平性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台收音机的公平性很响。", "explanation": "这里应该用〈声音〉。「声音很响」说声响的大小；「公平性」指对待的不偏不倚，不能形容收音机的声响。"}, {"text": "他把这张纸折成了公平性。", "explanation": "这里应该用〈飞机〉。「折成」可以指把纸折成具体的物件；「公平性」是抽象的对待方式，不能被折成东西。"}, {"text": "厨房里的公平性烧开了。", "explanation": "这里应该用〈水〉。「烧开」用于液体；「公平性」是抽象概念，不能被烧开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27464, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校要保证考试地公平性。", "corrected_sentence": "学校要保证考试的公平性。", "error_description": "错误：「考试的公平性」中的「的」误写成了「地」。「地」用于修饰动词、形容词，修饰名词「公平性」要用「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27464, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套规则的公平性们很高。", "corrected_sentence": "这套规则的公平性很高。", "error_description": "错误：「公平性」是抽象名词，不能加「们」表示复数。正确形式是「公平性」，去掉「们」即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
