INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27470, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种计划，变成法律后大家要遵守。", "primary_collocate": null, "pronunciation": "fǎ àn", "ipa": "fa˨˩˦ an˥˩", "syllable_count": 2, "sentences": [{"text": "这个法案变成法律后，人人都要遵守。", "target_word": "法案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新法案规定，开车不能玩手机。", "target_word": "法案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项法案要求工厂少排污水。", "target_word": "法案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民希望政府提出一项禁烟的法案。", "target_word": "法案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法案通过以后，大家都要照着做。", "target_word": "法案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校附近禁止停车的法案通过了。", "target_word": "法案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在课上学习了这个法案。", "target_word": "法案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个法案对老人很有帮助。", "target_word": "法案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上说，新法案下个月正式实施。", "target_word": "法案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们写了一项关于环保的法案。", "target_word": "法案", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}], "register": "正式", "sense_fingerprint": "法案：变成法律后大家都要遵守的计划（名词，正式）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27fdbf91-5a57-494c-bcdf-8cffdfde2c0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27470, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "法案", "is_correct": true, "explanation": "法案 fǎ àn：变成法律后大家都要遵守的计划，即听到的词。"}, {"text": "发案", "is_correct": false, "explanation": "fā（第一声）与 fǎ（第三声）声调不同，fā àn 意思是案件发生。"}, {"text": "翻案", "is_correct": false, "explanation": "fān（第一声）与 fǎ（第三声）韵母与声调不同，fān àn 意思是推翻原来的判决。"}, {"text": "犯案", "is_correct": false, "explanation": "fàn（第四声）与 fǎ（第三声）韵母与声调不同，fàn àn 意思是作案。"}], "explanations": {"法案": "法案 fǎ àn：变成法律后大家都要遵守的计划，即听到的词。", "发案": "fā（第一声）与 fǎ（第三声）声调不同，fā àn 意思是案件发生。", "翻案": "fān（第一声）与 fǎ（第三声）韵母与声调不同，fān àn 意思是推翻原来的判决。", "犯案": "fàn（第四声）与 fǎ（第三声）韵母与声调不同，fàn àn 意思是作案。"}, "sentence_index": null, "correct_answer": "法案"}, "level_3": {"options": [{"text": "法案", "is_correct": true, "explanation": "法案：变成法律后大家要遵守的计划，符合句意。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞不能变成法律，句子说的是立法。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：游戏是娱乐活动，不会变成法律，与“人人都要遵守”的语境冲突。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，不能用于说明法律效力的正式语境。"}], "explanations": {"法案": "法案：变成法律后大家要遵守的计划，符合句意。", "雨伞": "语义：雨伞不能变成法律，句子说的是立法。", "游戏": "语义：游戏是娱乐活动，不会变成法律，与“人人都要遵守”的语境冲突。", "玩意儿": "语域：“玩意儿”是口语，不能用于说明法律效力的正式语境。"}, "sentence_index": 0, "correct_answer": "法案"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的学习法案每天要背十个单词。", "explanation": "这里应该用〈计划〉。法案是变成法律后大家都要遵守的计划，个人的学习安排不会成为法律。"}, {"text": "我们公司内部的法案规定周末不能加班。", "explanation": "这里应该用〈规定〉。法案要变成法律才有约束力，公司内部的规定不叫法案。"}, {"text": "学校的法案是每周五下午放假。", "explanation": "这里应该用〈安排〉。法案要变成法律才能约束大家，学校的日程安排不是法案。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021b7708-422e-43eb-844c-1e7609f00d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid =