INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27470, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "法案", "is_correct": true, "explanation": "法案：变成法律后大家要遵守的计划，符合“课上学习”的语境。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“学习”的对象是知识或技能，不能说学习天气。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：课上学习的是知识内容，不能学习一个食堂。"}, {"text": "勾当", "is_correct": false, "explanation": "语域：“勾当”含贬义且是口语，不能用于描述课上学习的内容。"}], "explanations": {"法案": "法案：变成法律后大家要遵守的计划，符合“课上学习”的语境。", "天气": "搭配：“学习”的对象是知识或技能，不能说学习天气。", "食堂": "语义：课上学习的是知识内容，不能学习一个食堂。", "勾当": "语域：“勾当”含贬义且是口语，不能用于描述课上学习的内容。"}, "sentence_index": 6, "correct_answer": "法案"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "法案教我们怎么用洗衣机。", "explanation": "这里应该用〈手册〉。法案是变成法律后大家要遵守的计划，教人操作方法的应是手册。"}, {"text": "他按照法案弹了一首曲子。", "explanation": "这里应该用〈乐谱〉。法案是变成法律后要遵守的计划，弹奏曲子应依据乐谱。"}, {"text": "我的法案拍得很清楚。", "explanation": "这里应该用〈照片〉。法案是变成法律后要遵守的计划，不能用来拍照。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021b7708-422e-43eb-844c-1e7609f00d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
