INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27474, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "别人给你东西，你拿过来，说谢谢。", "primary_collocate": null, "pronunciation": "jiē shòu", "ipa": "tɕjɛ˥ ʂoʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "她笑着接受了朋友的礼物。", "target_word": "接受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你送的花很漂亮，我接受了，谢谢你。", "target_word": "接受", "complexity_tier": "T3", "furigana": "Nǐ sòng de huā hěn piàoliang, wǒ jiēshòu le, xièxie nǐ.", "sentence_source": "generated"}, {"text": "小明接受了老师送的书。", "target_word": "接受", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶不愿意接受我们的钱。", "target_word": "接受", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他接受了生日礼物，对大家说谢谢。", "target_word": "接受", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小礼物请你接受。", "target_word": "接受", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "朋友给我一杯茶，我高兴地接受了。", "target_word": "接受", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人接受了主人送的水果。", "target_word": "接受", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从来不接受别人的东西。", "target_word": "接受", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我接受过同学送的小花。", "target_word": "接受", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "接受了", "label": "体标"}, {"form": "接受过", "label": "体标"}, {"form": "接受着", "label": "体标"}, {"form": "接受者", "label": "复合"}], "register": "中性", "sense_fingerprint": "别人送东西给你，你收下并道谢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '228a4112-dbe4-4f55-9364-4edc773aa3f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27474, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "接受", "is_correct": true, "explanation": "正确：“接受”表示收下别人送的东西，与“礼物”搭配，符合“笑着”的语气。"}, {"text": "发表", "is_correct": false, "explanation": "搭配：“发表”用于言论、文章，不能用于礼物。"}, {"text": "批评", "is_correct": false, "explanation": "搭配：“批评”的对象是人或行为，不能说“批评朋友的礼物”。"}, {"text": "指责", "is_correct": false, "explanation": "搭配：“指责”的对象是人或行为，不能说“指责朋友的礼物”。"}], "explanations": {"接受": "正确：“接受”表示收下别人送的东西，与“礼物”搭配，符合“笑着”的语气。", "发表": "搭配：“发表”用于言论、文章，不能用于礼物。", "批评": "搭配：“批评”的对象是人或行为，不能说“批评朋友的礼物”。", "指责": "搭配：“指责”的对象是人或行为，不能说“指责朋友的礼物”。"}, "sentence_index": 0, "correct_answer": "接受"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个卫星接受了一段新的信号。", "explanation": "这里应该用〈接收〉。接受指同意收下别人送的东西或意见；接收信号、电波要用接收。"}, {"text": "妈妈接受了一封远方寄来的信。", "explanation": "这里应该用〈收到〉。接受指同意收下别人送的东西；收信件要用收到。"}, {"text": "我在商店接受了一件新衣服，花了两百块。", "explanation": "这里应该用〈买〉。接受指同意收下别人给的东西，不能用来说花钱购买；在商店花钱买东西要用买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4ef227a-ccf3-4885-bd62-7a306efce275') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27474, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "接受", "is_correct": true, "explanation": "正确：“接受”表示高兴地收下别人送的东西，符合句意。"}, {"text": "推开", "is_correct": false, "explanation": "语义：“推开”表示拒绝或躲开，与“高兴地”矛盾。"}, {"text": "摔碎", "is_correct": false, "explanation": "语义：“摔碎”指打破器物，与“高兴地收下”的情境不符。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”表示想不起来，与“高兴地收下茶”的情境不符。"}], "explanations": {"接受": "正确：“接受”表示高兴地收下别人送的东西，符合句意。", "推开": "语义：“推开”表示拒绝或躲开，与“高兴地”矛盾。", "摔碎": "语义：“摔碎”指打破器物，与“高兴地收下”的情境不符。", "忘记": "语义：“忘记”表示想不起来，与“高兴地收下茶”的情境不符。"}, "sentence_index": 6, "correct_answer": "接受"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她用手接受了朋友扔过来的球。", "explanation": "这里应该用〈接住〉。接受指收下别人送的东西；用手把飞来的东西拿住要用接住。"}, {"text": "学校接受了一场音乐会。", "explanation": "这里应该用〈举办〉。接受指同意收下别人送的东西；组织音乐会要用举办。"}, {"text": "我在路上接受了一个钱包，交给了警察。", "explanation": "这里应该用〈捡到〉。接受指收下别人送给你的东西；在路上发现并拿起东西要用捡到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4ef227a-ccf3-4885-bd62-7a306efce275') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27474, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她会接受了朋友的礼物。", "corrected_sentence": "她会接受朋友的礼物。", "error_description": "“会”表示将来或可能，不能与“了”同用；“接受”后不加“了”。正确形式为“她会接受朋友的礼物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4ef227a-ccf3-4885-bd62-7a306efce275') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27474, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从来不接受过别人的礼物。", "corrected_sentence": "我从来没接受过别人的礼物。", "error_description": "否定词错误：表示从未有过某种经历，“过”前应用“没”，不能用“不”。正确形式为“从来没接受过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4ef227a-ccf3-4885-bd62-7a306efce275') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
