INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27476, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "能证明一件事是真的东西。", "primary_collocate": null, "pronunciation": "zhèng jù", "ipa": "ʈʂɤŋ˥˩ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "你说他撒谎，有什么证据吗？", "target_word": "证据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机里的聊天记录就是证据。", "target_word": "证据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈想知道真相，可是没有证据。", "target_word": "证据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我拿不出证据，所以没人相信我。", "target_word": "证据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他丢了钱包，监控录像是最好的证据。", "target_word": "证据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地上的脚印是他来过的证据。", "target_word": "证据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张发票可以当作证据。", "target_word": "证据", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说，说话要有证据。", "target_word": "证据", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家都想看到你说的证据。", "target_word": "证据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他笑着拿出了一份证据。", "target_word": "证据", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "證據", "label": "繁体"}], "register": "中性", "sense_fingerprint": "证据|名词|能证明一件事是真的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dab0c558-bacf-42b5-ac45-3bf523f0ba2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27476, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "证据", "is_correct": true, "explanation": "证据：zhèng jù，指能证明一件事是真的东西。"}, {"text": "政局", "is_correct": false, "explanation": "jú（第二声）与 jù（第四声）声调不同，意思是政治局势。"}, {"text": "正序", "is_correct": false, "explanation": "xù 与 jù 声母不同（x／j），意思是正常的顺序。"}, {"text": "整句", "is_correct": false, "explanation": "zhěng（第三声）与 zhèng（第四声）声调不同，意思是完整的句子。"}], "explanations": {"证据": "证据：zhèng jù，指能证明一件事是真的东西。", "政局": "jú（第二声）与 jù（第四声）声调不同，意思是政治局势。", "正序": "xù 与 jù 声母不同（x／j），意思是正常的顺序。", "整句": "zhěng（第三声）与 zhèng（第四声）声调不同，意思是完整的句子。"}, "sentence_index": null, "correct_answer": "证据"}, "level_3": {"options": [{"text": "证据", "is_correct": true, "explanation": "“有什么证据吗”询问对方能否拿出证明撒谎的东西，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与“撒谎”无关，不能用来质问对方能否证明撒谎。"}, {"text": "香味", "is_correct": false, "explanation": "语义：“香味”指气味，与质问对方撒谎时要求拿出的证明无关。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”不能作为证明撒谎的东西，“有什么脾气吗”搭配不当。"}], "explanations": {"证据": "“有什么证据吗”询问对方能否拿出证明撒谎的东西，符合句意。", "颜色": "语义：“颜色”与“撒谎”无关，不能用来质问对方能否证明撒谎。", "香味": "语义：“香味”指气味，与质问对方撒谎时要求拿出的证明无关。", "脾气": "搭配：“脾气”不能作为证明撒谎的东西，“有什么脾气吗”搭配不当。"}, "sentence_index": 0, "correct_answer": "证据"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拿出了一份出生证据。", "explanation": "这里应该用〈证明〉。出生证明是官方开具的文件；证据指证明事实的材料，不能说“出生证据”。"}, {"text": "他许下了一个证据。", "explanation": "这里应该用〈愿望〉。许下的是愿望，证据是证明事实的材料，不能被“许下”。"}, {"text": "他讲了一个证据，大家都笑了。", "explanation": "这里应该用〈笑话〉。讲的是能让人发笑的笑话，证据不能用来逗人笑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27476, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "证据", "is_correct": true, "explanation": "证据：zhèng jù，指能证明一件事是真的东西。"}, {"text": "整局", "is_correct": false, "explanation": "zhěng jú：zhěng（第三声）与 zhèng（第四声）、jú（第二声）与 jù（第四声）声调都不同，意思是一整局比赛。"}, {"text": "战局", "is_correct": false, "explanation": "zhàn jú：zhàn 与 zhèng 韵母不同，jú（第二声）与 jù（第四声）声调不同，意思是战争的局势。"}, {"text": "正取", "is_correct": false, "explanation": "zhèng qǔ：qǔ 与 jù 声母（q／j）和声调都不同，意思是正式录取。"}], "explanations": {"证据": "证据：zhèng jù，指能证明一件事是真的东西。", "整局": "zhěng jú：zhěng（第三声）与 zhèng（第四声）、jú（第二声）与 jù（第四声）声调都不同，意思是一整局比赛。", "战局": "zhàn jú：zhàn 与 zhèng 韵母不同，jú（第二声）与 jù（第四声）声调不同，意思是战争的局势。", "正取": "zhèng qǔ：qǔ 与 jù 声母（q／j）和声调都不同，意思是正式录取。"}, "sentence_index": null, "correct_answer": "证据"}, "level_3": {"options": [{"text": "证据", "is_correct": true, "explanation": "“当作证据”指发票能作为证明事实的材料，符合句意。"}, {"text": "食物", "is_correct": false, "explanation": "语义：发票不能当作食物来吃，与发票的性质相冲突。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“当作”后接“歌曲”不通，发票不能被当作歌曲。"}, {"text": "座位", "is_correct": false, "explanation": "语义：发票不能用来坐，与句子所说的用途无关。"}], "explanations": {"证据": "“当作证据”指发票能作为证明事实的材料，符合句意。", "食物": "语义：发票不能当作食物来吃，与发票的性质相冲突。", "歌曲": "搭配：“当作”后接“歌曲”不通，发票不能被当作歌曲。", "座位": "语义：发票不能用来坐，与句子所说的用途无关。"}, "sentence_index": 6, "correct_answer": "证据"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这份证据当成生日祝福送给了朋友。", "explanation": "这里应该用〈祝福〉之类的心意。送给朋友的可以是祝福，证据是证明事实的材料，不能当作祝福送人。"}, {"text": "他向我表达了证据。", "explanation": "这里应该用〈歉意〉。能被表达的是歉意、感情，证据不能被“表达”。"}, {"text": "他露出了证据。", "explanation": "这里应该用〈笑容〉。露出的是表情，证据不是表情，不能“露出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27476, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们终于找了到证据。", "corrected_sentence": "我们终于找到了证据。", "error_description": "“到”是“找”的结果补语，“了”应放在补语之后，应说“找到了证据”，不能说“找了到证据”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27476, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只证据很重要。", "corrected_sentence": "这份证据很重要。", "error_description": "错误：“只”不能用来计数“证据”，证据通常用“条”“份”等量词。应改为“这份证据”。正确的说法是：这份证据很重要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27478, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99170a0b-fcd3-4dc8-a365-086528c87822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27478, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99170a0b-fcd3-4dc8-a365-086528c87822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27478, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "跑在最前面，别人在后面追。", "primary_collocate": null, "pronunciation": "lǐng xiān", "ipa": "liŋ˨˩ ɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "比赛开始后，他很快就领先了。", "target_word": "领先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小李一直领先，别的人都在后面。", "target_word": "领先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跑到第三圈时，她领先了所有人。", "target_word": "领先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的车领先第二名一百米。", "target_word": "领先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在最后一圈还是领先的。", "target_word": "领先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那匹白马一直领先，跑在最前面。", "target_word": "领先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥起跑很快，一路领先。", "target_word": "领先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他领先后面的人二十米。", "target_word": "领先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骑车上山时，姐姐总是领先我。", "target_word": "领先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在谁领先？穿红衣服的那个人。", "target_word": "领先", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "领先了", "label": "完成体（了）"}, {"form": "领先过", "label": "经历体（过）"}, {"form": "一路领先", "label": "复合"}, {"form": "領先", "label": "繁体"}], "register": "中性", "sense_fingerprint": "赛跑、骑车等比赛中位置在最前面，别人落在后面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbcaf301-82fc-4b3d-abe8-64f62bf9c1e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27478, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "领先", "is_correct": true, "explanation": "正确：“领先”表示比赛中跑在最前面，与“比赛开始后”“很快就”的语境相符。"}, {"text": "发表", "is_correct": false, "explanation": "配价：“发表”需要宾语（如意见、文章），此处缺少宾语，句子不完整。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”与比赛开始后的语境不符。"}, {"text": "装饰", "is_correct": false, "explanation": "配价：“装饰”需要宾语，此处缺少宾语，句子不完整。"}], "explanations": {"领先": "正确：“领先”表示比赛中跑在最前面，与“比赛开始后”“很快就”的语境相符。", "发表": "配价：“发表”需要宾语（如意见、文章），此处缺少宾语，句子不完整。", "退休": "语义：“退休”与比赛开始后的语境不符。", "装饰": "配价：“装饰”需要宾语，此处缺少宾语，句子不完整。"}, "sentence_index": 0, "correct_answer": "领先"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很快就领先了老师的意思。", "explanation": "这里应该用〈领会〉。领先指跑在前面、比别人更快，理解意思要说领会。"}, {"text": "这个月我的体重领先了三公斤。", "explanation": "这里应该用〈增加〉。领先用于比赛中的前后位置，体重的增加要说增加。"}, {"text": "这个地方的风景很领先，我们都很喜欢。", "explanation": "这里应该用〈美丽〉。领先不用于描述风景，风景优美要说美丽。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99170a0b-fcd3-4dc8-a365-086528c87822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27478, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "领先", "is_correct": true, "explanation": "正确：“领先”表示位置靠前，与“起跑很快”“一路”的语境一致。"}, {"text": "落后", "is_correct": false, "explanation": "语义：“落后”与“起跑很快”的语境相矛盾。"}, {"text": "停止", "is_correct": false, "explanation": "搭配：“一路”后接“停止”不自然，不符合常规表达。"}, {"text": "发愁", "is_correct": false, "explanation": "语义：“发愁”与“起跑很快”的积极语境不符。"}], "explanations": {"领先": "正确：“领先”表示位置靠前，与“起跑很快”“一路”的语境一致。", "落后": "语义：“落后”与“起跑很快”的语境相矛盾。", "停止": "搭配：“一路”后接“停止”不自然，不符合常规表达。", "发愁": "语义：“发愁”与“起跑很快”的积极语境不符。"}, "sentence_index": 6, "correct_answer": "领先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他领先了自己的极限，变得更强。", "explanation": "这里应该用〈超越〉。领先指位置靠前，突破自己的极限要说超越。"}, {"text": "他领先了一杯水，一口就喝完了。", "explanation": "这里应该用〈喝〉。领先指位置靠前，喝水要说喝，不能说“领先水”。"}, {"text": "妈妈领先了一双新鞋。", "explanation": "这里应该用〈购买〉。领先不表示买东西，买鞋要说购买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99170a0b-fcd3-4dc8-a365-086528c87822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27478, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从比赛开始就一路了领先，最后赢得了冠军。", "corrected_sentence": "他从比赛开始就一路领先，最后赢得了冠军。", "error_description": "错误形式：“一路了领先”。正确形式：“一路领先”。“了”是完成体标记，不能插在状语“一路”与动词“领先”之间，删去即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99170a0b-fcd3-4dc8-a365-086528c87822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27478, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "骑车上山时，他领先我了二十米。", "corrected_sentence": "骑车上山时，他领先了我二十米。", "error_description": "错误形式：“领先我了二十米”。正确形式：“领先了我二十米”。“了”应紧跟动词“领先”，表示动作完成，位置放错。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99170a0b-fcd3-4dc8-a365-086528c87822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
