INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27488, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个地方管的范围，比如这个警察管哪块地方，这就是他管的辖区。", "primary_collocate": null, "pronunciation": "xiá qū", "ipa": "ɕja˧˥ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "这块地方是李警察的辖区。", "target_word": "辖区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察要熟悉自己的辖区。", "target_word": "辖区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街不属于我们的辖区。", "target_word": "辖区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的辖区里住着很多老人。", "target_word": "辖区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家就在这个派出所的辖区。", "target_word": "辖区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察在辖区里走了一圈。", "target_word": "辖区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "辖区太大，警察忙不过来。", "target_word": "辖区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察对辖区的每条路都很熟。", "target_word": "辖区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出了辖区，他就不能管了。", "target_word": "辖区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的警察第一天就走遍了辖区。", "target_word": "辖区", "complexity_tier": "T3", "furigana": "xīnlái de jǐngchá dì yī tiān jiù zǒubiàn le xiáqū", "sentence_source": "generated"}], "morphological_forms": [{"form": "轄區", "label": "繁体"}], "register": "正式", "sense_fingerprint": "警察等负责管理的那块地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c6d0dad-2ddf-4382-b7de-80be2a8c3a9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27488, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宠物", "is_correct": false, "explanation": "语义：宠物是动物，不能说“这块地方是李警察的宠物”。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”是人的身体特征，不能指一块地方。"}, {"text": "辖区", "is_correct": true, "explanation": "“辖区”指警察负责管理的地方，与“李警察的”搭配，句子成立。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工资”可以属于人，但不能用来指一块地方。"}], "explanations": {"宠物": "语义：宠物是动物，不能说“这块地方是李警察的宠物”。", "体重": "体貌：“体重”是人的身体特征，不能指一块地方。", "辖区": "“辖区”指警察负责管理的地方，与“李警察的”搭配，句子成立。", "工资": "搭配：“工资”可以属于人，但不能用来指一块地方。"}, "sentence_index": 0, "correct_answer": "辖区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的这只辖区里住着很多老人。", "explanation": "这里应该用〈片〉。辖区是一片范围，“只”多用于动物，不能说“这只辖区”。"}, {"text": "他的辖区是一位老人。", "explanation": "这里不能说“辖区是一位老人”。辖区是管辖的地方，不是人，应说“辖区里住着一位老人”。"}, {"text": "他的辖区吃了三碗饭。", "explanation": "这里应该用〈人〉。辖区是地方，不会吃饭，“吃饭”的主语应是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83165e94-7919-4e31-9338-a38194427f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27488, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "字体", "is_correct": false, "explanation": "语义：字体太大与警察忙不过来无关，句子说不通。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：脚步太大与警察忙不过来无关，句子说不通。"}, {"text": "辖区", "is_correct": true, "explanation": "“辖区太大”说明管理范围过大，警察因此忙不过来，句子成立。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”是人的体形，不能说它太大导致警察忙不过来。"}], "explanations": {"字体": "语义：字体太大与警察忙不过来无关，句子说不通。", "脚步": "语义：脚步太大与警察忙不过来无关，句子说不通。", "辖区": "“辖区太大”说明管理范围过大，警察因此忙不过来，句子成立。", "身材": "体貌：“身材”是人的体形，不能说它太大导致警察忙不过来。"}, "sentence_index": 6, "correct_answer": "辖区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新来的警察第一天就成了辖区。", "explanation": "这里应该用〈民警〉。辖区是一片管理范围，不是人；“成了”后应接职务或身份，如“成了一名民警”。"}, {"text": "新来的警察第一天就喝光了辖区。", "explanation": "这里应该用〈饮料〉。辖区是地方，不能喝；“喝光”的对象应是饮料，如“喝光了饮料”。"}, {"text": "新来的警察第一天就抱起了辖区。", "explanation": "这里应该用〈箱子〉。辖区是一片范围，不能抱；“抱起”的对象应是具体的东西，如“抱起了箱子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83165e94-7919-4e31-9338-a38194427f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27488, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条辖区有三条主要街道。", "corrected_sentence": "这片辖区有三条主要街道。", "error_description": "量词错误：辖区是一片范围，应用“片”，不能用“条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83165e94-7919-4e31-9338-a38194427f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27488, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "辖区的内有一座公园。", "corrected_sentence": "辖区内有一座公园。", "error_description": "多余的“的”：方位词“内”前不加“的”，应说“辖区内”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83165e94-7919-4e31-9338-a38194427f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27490, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99170a0b-fcd3-4dc8-a365-086528c87822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27490, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99170a0b-fcd3-4dc8-a365-086528c87822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27490, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大家相信某个人或某个机构的程度。", "primary_collocate": null, "pronunciation": "gōng xìn lì", "ipa": "kʊŋ˥ ɕin˥˩ li˥˩", "syllable_count": 3, "sentences": [{"text": "这位医生很有公信力，大家都相信他。", "target_word": "公信力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他总是说谎，已经没有公信力了。", "target_word": "公信力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公开信息可以增强公司的公信力。", "target_word": "公信力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个网站的公信力不太高。", "target_word": "公信力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察的公信力来自公平做事。", "target_word": "公信力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新闻要真实，才有公信力。", "target_word": "公信力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那家银行的公信力很强。", "target_word": "公信力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做错事后，他的公信力下降了。", "target_word": "公信力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校用这种方法提高了公信力。", "target_word": "公信力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都说，这个节目的公信力最高。", "target_word": "公信力", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人们对某人或某机构信任的程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbcaf301-82fc-4b3d-abe8-64f62bf9c1e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27490, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公信力", "is_correct": true, "explanation": "“很有公信力”说医生被大家相信，与后一分句“大家都相信他”一致。"}, {"text": "数量", "is_correct": false, "explanation": "搭配：“很有”一般不接“数量”，数量应说“很多”。"}, {"text": "长度", "is_correct": false, "explanation": "语义：长度说的是事物的尺寸，与医生被相信的程度无关。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：海拔是地面的高度，不能用来形容人，句意不通。"}], "explanations": {"公信力": "“很有公信力”说医生被大家相信，与后一分句“大家都相信他”一致。", "数量": "搭配：“很有”一般不接“数量”，数量应说“很多”。", "长度": "语义：长度说的是事物的尺寸，与医生被相信的程度无关。", "海拔": "语义：海拔是地面的高度，不能用来形容人，句意不通。"}, "sentence_index": 0, "correct_answer": "公信力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小明的公信力很烫，一摸就缩手。", "explanation": "这里应该用〈温度〉。烫说的是温度，公信力指大家相信某人或机构的程度，不能用来形容温度。"}, {"text": "这位歌手的公信力很高，几乎人人都认识他。", "explanation": "这里应该用〈知名度〉。知名度说的是被人知道的程度，公信力说的是被相信的程度，不能用来表示“被认识”。"}, {"text": "他这个月的公信力减轻了三公斤。", "explanation": "这里应该用〈体重〉。公信力是抽象的信任程度，不能用公斤计量，说体重减轻才用“体重”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99170a0b-fcd3-4dc8-a365-086528c87822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27490, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公信力", "is_correct": true, "explanation": "“公信力很强”说银行被大家相信，与句意一致。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是人的高矮，不能用来形容银行，句意不通。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是人体的温度，银行没有体温，句意不通。"}, {"text": "密度", "is_correct": false, "explanation": "搭配：“很强”一般形容能力、影响等，不说“密度很强”。"}], "explanations": {"公信力": "“公信力很强”说银行被大家相信，与句意一致。", "身高": "语义：身高是人的高矮，不能用来形容银行，句意不通。", "体温": "语义：体温是人体的温度，银行没有体温，句意不通。", "密度": "搭配：“很强”一般形容能力、影响等，不说“密度很强”。"}, "sentence_index": 6, "correct_answer": "公信力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老人的公信力很远，能看见远处的鸟。", "explanation": "这里应该用〈视力〉。能看见远处的东西说的是视力，公信力指大家的信任程度，不能用“远”来形容。"}, {"text": "这道菜的公信力最好，我吃了还想吃。", "explanation": "这里应该用〈味道〉。“最好”形容味道时指好吃，公信力是抽象的信任，不能用来描述食物。"}, {"text": "这幅画的公信力很鲜艳，好看极了。", "explanation": "这里应该用〈颜色〉。“鲜艳”形容颜色，公信力是抽象的信任，不能用“鲜艳”来描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99170a0b-fcd3-4dc8-a365-086528c87822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27490, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那家店地公信力很高，很多人都愿意来。", "corrected_sentence": "那家店的公信力很高，很多人都愿意来。", "error_description": "错误：“地”是状语的结构助词，这里“那家店”修饰“公信力”，是定语，应用“的”。正确是“那家店的公信力很高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99170a0b-fcd3-4dc8-a365-086528c87822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27490, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那家医院有一只公信力，大家都信任它。", "corrected_sentence": "那家医院有一定的公信力，大家都信任它。", "error_description": "错误：“只”是量词，用于动物、手等，不能修饰抽象的“公信力”。这里应直接用“一定的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99170a0b-fcd3-4dc8-a365-086528c87822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
