INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27496, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "数据流是像河水一样流动的数字和信息。", "primary_collocate": null, "pronunciation": "shù jù liú", "ipa": "ʂu˥˩ tɕy˥˩ ljoʊ˧˥", "syllable_count": 3, "sentences": [{"text": "数据流像小河，把信息送到各地。", "target_word": "数据流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络里的数据流就像一条河。", "target_word": "数据流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说数据流像水一样往前走。", "target_word": "数据流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的电脑里每天都有数据流经过。", "target_word": "数据流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据流在网线里慢慢流动。", "target_word": "数据流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小河里是水，数据流里是信息。", "target_word": "数据流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看这张图，数据流从左边流向右边。", "target_word": "数据流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水会流进海里，数据流会流进电脑。", "target_word": "数据流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问：数据流为什么像小河？", "target_word": "数据流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据流很大，就像一条大河。", "target_word": "数据流", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "数据流量", "label": "复合"}], "register": "中性", "sense_fingerprint": "像小河一样流动的数字和信息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c6d0dad-2ddf-4382-b7de-80be2a8c3a9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27496, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "数据流", "is_correct": true, "explanation": "正确：「数据流像小河，把信息送到各地」中，数据流作主语，比喻其流动送达信息，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能像小河一样把信息送到各地，这与句中的比喻相矛盾。"}, {"text": "砖块", "is_correct": false, "explanation": "语义：砖块不具备流动和送达信息的特征，句子无法成立。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：「把信息送到各地」的主语需能发送信息，眼睛与这一搭配不符。"}], "explanations": {"数据流": "正确：「数据流像小河，把信息送到各地」中，数据流作主语，比喻其流动送达信息，符合句意。", "石头": "语义：石头不能像小河一样把信息送到各地，这与句中的比喻相矛盾。", "砖块": "语义：砖块不具备流动和送达信息的特征，句子无法成立。", "眼睛": "搭配：「把信息送到各地」的主语需能发送信息，眼睛与这一搭配不符。"}, "sentence_index": 0, "correct_answer": "数据流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河的数据流很急。", "explanation": "这里应该用〈水流〉。河里湍急的流动要说水流，数据流指数字和信息。"}, {"text": "这条马路上的数据流很多。", "explanation": "这里应该用〈车流〉。马路上的车辆流动要说车流，数据流指数字和信息，不能用来描述车辆。"}, {"text": "妈妈把数据流切开，放进了盘子里。", "explanation": "这里应该用〈蛋糕〉。固体食物可以切开装盘，数据流不能被切开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83165e94-7919-4e31-9338-a38194427f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27496, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数据流", "is_correct": true, "explanation": "正确：「看这张图，数据流从左边流向右边」中，数据流作主语，表示其流动方向，符合句意。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不会流动，「从左边流向右边」的主语不能是书包。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能流动，这与句中「流向」的动作相矛盾。"}, {"text": "电灯", "is_correct": false, "explanation": "搭配：「流」用于液体、气体或数据，不与「电灯」搭配。"}], "explanations": {"数据流": "正确：「看这张图，数据流从左边流向右边」中，数据流作主语，表示其流动方向，符合句意。", "书包": "语义：书包不会流动，「从左边流向右边」的主语不能是书包。", "桌子": "语义：桌子不能流动，这与句中「流向」的动作相矛盾。", "电灯": "搭配：「流」用于液体、气体或数据，不与「电灯」搭配。"}, "sentence_index": 6, "correct_answer": "数据流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "房间里的数据流很亮。", "explanation": "这里应该用〈灯光〉。说亮度要用灯光，数据流不能发亮。"}, {"text": "今天的数据流很热。", "explanation": "这里应该用〈天气〉。说冷热要用天气，数据流不能用来描述温度。"}, {"text": "他的数据流很高。", "explanation": "这里应该用〈身高〉。形容人的高矮要用身高，数据流不能这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83165e94-7919-4e31-9338-a38194427f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27496, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些数据流们都很平稳。", "corrected_sentence": "这些数据流都很平稳。", "error_description": "「们」只用于指人的名词，数据流不能加「们」，应说「这些数据流都很平稳」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83165e94-7919-4e31-9338-a38194427f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27496, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一座数据流从网线里流过。", "corrected_sentence": "一股数据流从网线里流过。", "error_description": "量词「座」用于山、桥、楼等大型物体，数据流应用「股」或「条」，不能说「一座数据流」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83165e94-7919-4e31-9338-a38194427f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27498, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "善意", "is_correct": true, "explanation": "正确。“善意”与“恶意”相对，指好的、善良的用意，二者是反义词。"}, {"text": "礼貌", "is_correct": false, "explanation": "与“恶意”没有反义关系。“礼貌”指待人有礼节，与用意的好坏不构成对立。"}, {"text": "信心", "is_correct": false, "explanation": "与“恶意”没有反义关系。“信心”指对成功的相信，与用意无关。"}, {"text": "书籍", "is_correct": false, "explanation": "与“恶意”没有反义关系。“书籍”是具体事物，与用意无关。"}], "correct_answer": "善意", "explanations": {"善意": "正确。“善意”与“恶意”相对，指好的、善良的用意，二者是反义词。", "礼貌": "与“恶意”没有反义关系。“礼貌”指待人有礼节，与用意的好坏不构成对立。", "信心": "与“恶意”没有反义关系。“信心”指对成功的相信，与用意无关。", "书籍": "与“恶意”没有反义关系。“书籍”是具体事物，与用意无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83165e94-7919-4e31-9338-a38194427f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27498, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "善意", "is_correct": true, "explanation": "正确。“善意”与“恶意”相对，指好的、善良的用意，二者是反义词。"}, {"text": "窗户", "is_correct": false, "explanation": "与“恶意”没有反义关系。“窗户”是具体事物，与用意无关。"}, {"text": "道路", "is_correct": false, "explanation": "与“恶意”没有反义关系。“道路”是具体事物，与用意无关。"}, {"text": "粮食", "is_correct": false, "explanation": "与“恶意”没有反义关系。“粮食”是具体事物，与用意无关。"}], "correct_answer": "善意", "explanations": {"善意": "正确。“善意”与“恶意”相对，指好的、善良的用意，二者是反义词。", "窗户": "与“恶意”没有反义关系。“窗户”是具体事物，与用意无关。", "道路": "与“恶意”没有反义关系。“道路”是具体事物，与用意无关。", "粮食": "与“恶意”没有反义关系。“粮食”是具体事物，与用意无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83165e94-7919-4e31-9338-a38194427f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27498, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "存心伤害别人的坏念头，或故意做坏事。", "primary_collocate": null, "pronunciation": "è yì", "ipa": "ɤ˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "他故意弄坏我的书，是恶意的。", "target_word": "恶意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明对新同学没有恶意。", "target_word": "恶意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要用恶意去揣测别人。", "target_word": "恶意", "complexity_tier": "T3", "furigana": "bù yào yòng è yì qù chuāi cè bié rén。", "sentence_source": "generated"}, {"text": "她的笑里带着一点恶意。", "target_word": "恶意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人心里有恶意，你要小心。", "target_word": "恶意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心怀恶意，骗了老人的钱。", "target_word": "恶意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那些恶意的话让她很难过。", "target_word": "恶意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有恶意，请你相信我。", "target_word": "恶意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的恶意评论伤害了他。", "target_word": "恶意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师看出他的话里有恶意，很生气。", "target_word": "恶意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "恶意软件", "label": "复合"}, {"form": "恶意攻击", "label": "复合"}], "register": "中性", "sense_fingerprint": "故意做坏事的坏想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c6d0dad-2ddf-4382-b7de-80be2a8c3a9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27498, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "恶意", "is_correct": true, "explanation": "正确。“是恶意的”说明他故意弄坏书的用意是存心伤害，与前句“故意弄坏”吻合。"}, {"text": "无意", "is_correct": false, "explanation": "语义：“无意”表示没有想到或不是故意，与前句“故意弄坏”矛盾。"}, {"text": "善意", "is_correct": false, "explanation": "语义：“善意”表示好的用意，与“故意弄坏我的书”的行为矛盾。"}, {"text": "客气", "is_correct": false, "explanation": "搭配：“客气”形容态度，不用来说明行为的性质。"}], "explanations": {"恶意": "正确。“是恶意的”说明他故意弄坏书的用意是存心伤害，与前句“故意弄坏”吻合。", "无意": "语义：“无意”表示没有想到或不是故意，与前句“故意弄坏”矛盾。", "善意": "语义：“善意”表示好的用意，与“故意弄坏我的书”的行为矛盾。", "客气": "搭配：“客气”形容态度，不用来说明行为的性质。"}, "sentence_index": 0, "correct_answer": "恶意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师的恶意让我很温暖。", "explanation": "这里应该用〈关怀〉。“恶意”指故意做不好的事或坏的念头，学习者易把它与“关怀”混淆，不能用来形容让人温暖的关心。"}, {"text": "他帮我修好了车，他的恶意真让人感动。", "explanation": "这里应该用〈善意〉。“恶意”指存心伤害别人，不能用来形容帮助别人的好心。"}, {"text": "她送我生日礼物，表达了她的恶意。", "explanation": "这里应该用〈心意〉。送礼物表达的是好的心意，“恶意”指存心伤害别人的坏念头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83165e94-7919-4e31-9338-a38194427f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27498, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "恶意", "is_correct": true, "explanation": "正确。“恶意的话”指存心伤人的话，与“让她很难过”的结果吻合。"}, {"text": "温暖", "is_correct": false, "explanation": "语义：“温暖的话”应使人感到安慰，与“让她很难过”的结果矛盾。"}, {"text": "亲切", "is_correct": false, "explanation": "语义：“亲切的话”通常令人感到温馨，与“让她很难过”的结果矛盾。"}, {"text": "旺盛", "is_correct": false, "explanation": "搭配：“旺盛”形容生命力或精力，不用来修饰“话”。"}], "explanations": {"恶意": "正确。“恶意的话”指存心伤人的话，与“让她很难过”的结果吻合。", "温暖": "语义：“温暖的话”应使人感到安慰，与“让她很难过”的结果矛盾。", "亲切": "语义：“亲切的话”通常令人感到温馨，与“让她很难过”的结果矛盾。", "旺盛": "搭配：“旺盛”形容生命力或精力，不用来修饰“话”。"}, "sentence_index": 6, "correct_answer": "恶意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们只是恶意，没有别的意思。", "explanation": "这里应该用〈开玩笑〉。“恶意”指存心伤害，不能用来说明说话时的玩笑态度。"}, {"text": "这次考试他考了恶意的高分。", "explanation": "这里不能用〈恶意〉。学习者易把“恶意”当作“极端、过分”的程度词，但它指故意做坏事或坏的念头，不能形容成绩，应说〈优异〉。"}, {"text": "他对待工作很恶意，经常迟到。", "explanation": "这里不能用〈恶意〉。“恶意”描述的是用意，不用来评价工作的态度，应说〈懈怠〉或〈马虎〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83165e94-7919-4e31-9338-a38194427f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27498, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她没有恶意过，只是说错了话。", "corrected_sentence": "她没有恶意，只是说错了话。", "error_description": "“恶意”是名词，后面不能加动态助词“过”，应说“她没有恶意”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83165e94-7919-4e31-9338-a38194427f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27498, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的话里充满了恶意的。", "corrected_sentence": "他的话里充满了恶意。", "error_description": "“恶意”在这里是“充满”的宾语，是名词，句末不能再加“的”，应说“充满了恶意”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83165e94-7919-4e31-9338-a38194427f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27500, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30e01f3b-6813-4633-bc7a-b4a3994fd854') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
