INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27500, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "想要得到或找到某样东西。", "primary_collocate": null, "pronunciation": "xún qiú", "ipa": "ɕyn˧˥ tɕʰjoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "很多年轻人去大城市寻求发展。", "target_word": "寻求", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在书里寻求生活的答案。", "target_word": "寻求", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们正在寻求解决问题的办法。", "target_word": "寻求", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她来这里寻求安静的生活。", "target_word": "寻求", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们寻求的不是钱，而是机会。", "target_word": "寻求", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "受伤以后，他马上寻求医生的帮助。", "target_word": "寻求", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想寻求朋友的理解。", "target_word": "寻求", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人去山里寻求安静，也寻求健康。", "target_word": "寻求", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她为了寻求帮助，给很多人打过电话。", "target_word": "寻求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直在寻求成功的机会，从不放弃。", "target_word": "寻求", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "寻求了", "label": "体标"}, {"form": "寻求过", "label": "体标"}, {"form": "寻求着", "label": "体标"}], "register": "书面", "sense_fingerprint": "想要得到或找到某样东西（寻求发展、寻求答案、寻求温暖）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88bcbd-fe2c-4dba-ab0f-04f6851766bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27500, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”与年轻人去大城市谋求发展的意思相反，句子说不通"}, {"text": "寻求", "is_correct": true, "explanation": "正确：“寻求”表示想要得到，句中“去大城市寻求发展”正合适"}, {"text": "离开", "is_correct": false, "explanation": "搭配：“离开”后面接处所，不接“发展”作宾语"}, {"text": "忽视", "is_correct": false, "explanation": "语义：“忽视”表示不重视，与年轻人去大城市的目的矛盾"}], "explanations": {"放弃": "语义：“放弃”与年轻人去大城市谋求发展的意思相反，句子说不通", "寻求": "正确：“寻求”表示想要得到，句中“去大城市寻求发展”正合适", "离开": "搭配：“离开”后面接处所，不接“发展”作宾语", "忽视": "语义：“忽视”表示不重视，与年轻人去大城市的目的矛盾"}, "sentence_index": 0, "correct_answer": "寻求"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在厨房里寻求一把剪刀。", "explanation": "这里应该用〈寻找〉。寻求多指向帮助、机会、答案等，找具体的物品要用寻找"}, {"text": "警察在街上寻求那辆失窃的汽车。", "explanation": "这里应该用〈搜寻〉。搜寻指在一定范围内找人或物，寻求不用于找具体的车辆"}, {"text": "他去超市寻求了一瓶酱油。", "explanation": "这里应该用〈买〉。寻求指想要得到帮助、机会、答案等，买具体的商品要用买，不能用寻求。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30e01f3b-6813-4633-bc7a-b4a3994fd854') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27500, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打", "is_correct": false, "explanation": "搭配：“打”不能带“理解”这样的抽象宾语，“打朋友的理解”不成立。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能说“吃理解”。"}, {"text": "寻求", "is_correct": true, "explanation": "正确：“寻求”表示想要得到，“寻求朋友的理解”搭配恰当。"}, {"text": "砸", "is_correct": false, "explanation": "搭配：“砸”的对象是具体物品，不能“砸理解”。"}], "explanations": {"打": "搭配：“打”不能带“理解”这样的抽象宾语，“打朋友的理解”不成立。", "吃": "搭配：“吃”的宾语应是食物，不能说“吃理解”。", "寻求": "正确：“寻求”表示想要得到，“寻求朋友的理解”搭配恰当。", "砸": "搭配：“砸”的对象是具体物品，不能“砸理解”。"}, "sentence_index": 6, "correct_answer": "寻求"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我去银行寻求存款的余额。", "explanation": "这里应该用〈查询〉。查询指查看账户、资料等信息，寻求用于要帮助、机会、答案等"}, {"text": "孩子去书店寻求了一本漫画书。", "explanation": "这里应该用〈买〉。寻求指想要得到帮助、机会、答案等，买漫画书这样的具体商品要用买，不能用寻求。"}, {"text": "他去窗口寻求了身份证。", "explanation": "这里应该用〈领取〉。领取指从窗口等处拿到办好的东西，寻求不能用于拿身份证"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30e01f3b-6813-4633-bc7a-b4a3994fd854') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27500, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他正在寻求了一份合适的工作。", "corrected_sentence": "他正在寻求一份合适的工作。", "error_description": "「正在」表示动作正在进行，不能与表示完成的「了」同用，应说「正在寻求」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30e01f3b-6813-4633-bc7a-b4a3994fd854') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27500, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子遇到困难，常对父母寻求安慰。", "corrected_sentence": "孩子遇到困难，常向父母寻求安慰。", "error_description": "引出「寻求」的对象时要用介词「向」，应说「向父母寻求安慰」；「对」多用于表示对待、针对，不能用在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30e01f3b-6813-4633-bc7a-b4a3994fd854') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27502, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "关闭", "is_correct": true, "explanation": "“关闭”指停止对外开放、不让人进入，与“公园开放”的意思正相反。"}, {"text": "修建", "is_correct": false, "explanation": "“修建”指建造，与是否允许人进入没有反义关系。"}, {"text": "清洁", "is_correct": false, "explanation": "“清洁”指把场所弄干净，与解除限制无关，不是反义词。"}, {"text": "装修", "is_correct": false, "explanation": "“装修”指装饰房屋，与允许人进入、不封闭没有对立关系。"}], "correct_answer": "关闭", "explanations": {"关闭": "“关闭”指停止对外开放、不让人进入，与“公园开放”的意思正相反。", "修建": "“修建”指建造，与是否允许人进入没有反义关系。", "清洁": "“清洁”指把场所弄干净，与解除限制无关，不是反义词。", "装修": "“装修”指装饰房屋，与允许人进入、不封闭没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c56a0ea9-c8d7-4fa3-ad4e-ab5f94a36891') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27502, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "关闭", "is_correct": true, "explanation": "“关闭”指停止对外开放、不让人进入，与“游泳池冬天开放”的意思正相反。"}, {"text": "研究", "is_correct": false, "explanation": "“研究”指探讨问题，与是否允许人进入没有对立关系。"}, {"text": "讨论", "is_correct": false, "explanation": "“讨论”指交换意见，与解除限制无关，不是反义词。"}, {"text": "提醒", "is_correct": false, "explanation": "“提醒”指使人注意，与场所开放、封闭没有反义关系。"}], "correct_answer": "关闭", "explanations": {"关闭": "“关闭”指停止对外开放、不让人进入，与“游泳池冬天开放”的意思正相反。", "研究": "“研究”指探讨问题，与是否允许人进入没有对立关系。", "讨论": "“讨论”指交换意见，与解除限制无关，不是反义词。", "提醒": "“提醒”指使人注意，与场所开放、封闭没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c56a0ea9-c8d7-4fa3-ad4e-ab5f94a36891') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27502, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西不再关着，别人可以进去或使用。", "primary_collocate": null, "pronunciation": "kāi fàng", "ipa": "kʰai˥ faŋ˥˩", "syllable_count": 2, "sentences": [{"text": "公园早上六点开放，欢迎大家来玩。", "target_word": "开放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆周末也开放，你可以去看书。", "target_word": "开放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新建的游泳馆明天开始对外开放。", "target_word": "开放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥修好了，下个月就开放。", "target_word": "开放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆每天九点开放，下午五点关门。", "target_word": "开放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物园开放了新的熊猫馆，很多人去看。", "target_word": "开放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的学校周六不开放，你周一再来吧。", "target_word": "开放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "展览馆今天开放了三个新房间。", "target_word": "开放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的路下雪后关了，现在又开放了。", "target_word": "开放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游泳池冬天不开放，夏天才开放。", "target_word": "开放", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开放了", "label": "完成体"}, {"form": "开放着", "label": "持续体"}, {"form": "开放过", "label": "经历体"}, {"form": "開放", "label": "繁体"}], "register": "中性", "sense_fingerprint": "场所、设施不再关闭，允许人们进入或使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df6c5434-bf82-45b0-9904-96dfe8a36f91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27502, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开放", "is_correct": true, "explanation": "“公园早上六点开放”指到时间允许人进入，与“欢迎大家来玩”相符。"}, {"text": "关门", "is_correct": false, "explanation": "语义：“关门”与“欢迎大家来玩”的意思矛盾。"}, {"text": "迁移", "is_correct": false, "explanation": "语义：“迁移”指转移位置，公园不能迁移，句意不通。"}, {"text": "歇菜", "is_correct": false, "explanation": "语域：“歇菜”是口语，指停止运转，与这类告示式的语体不符，且与“欢迎大家来玩”矛盾。"}], "explanations": {"开放": "“公园早上六点开放”指到时间允许人进入，与“欢迎大家来玩”相符。", "关门": "语义：“关门”与“欢迎大家来玩”的意思矛盾。", "迁移": "语义：“迁移”指转移位置，公园不能迁移，句意不通。", "歇菜": "语域：“歇菜”是口语，指停止运转，与这类告示式的语体不符，且与“欢迎大家来玩”矛盾。"}, "sentence_index": 0, "correct_answer": "开放"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈开放了窗户。", "explanation": "这里应该用〈打开〉。打开用于门窗的开合；开放用于场所或资源对外允许使用，窗户的开关不能说开放。"}, {"text": "工人开放了灯。", "explanation": "这里应该用〈开〉。开指打开电器使其运转，灯要用开；开放指让场所或资源对外允许接近或使用，不用于电器的开关。"}, {"text": "老师开放了作业本。", "explanation": "这里应该用〈发放〉。发放指分发物品，作业本要用发放；开放指让场所或资源对外允许接近或使用，不用于分发物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c56a0ea9-c8d7-4fa3-ad4e-ab5f94a36891') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27502, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开放", "is_correct": true, "explanation": "“周六不开放”指周六不允许进入，与“你周一再来吧”相符。"}, {"text": "毕业", "is_correct": false, "explanation": "搭配：“毕业”的主语是人，学校不能毕业，句意不通。"}, {"text": "发表", "is_correct": false, "explanation": "语义：“发表”指公开刊登文章或言论，与学校能否进入无关。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：“发芽”指植物长出芽，学校不会发芽，句意不通。"}], "explanations": {"开放": "“周六不开放”指周六不允许进入，与“你周一再来吧”相符。", "毕业": "搭配：“毕业”的主语是人，学校不能毕业，句意不通。", "发表": "语义：“发表”指公开刊登文章或言论，与学校能否进入无关。", "发芽": "语义：“发芽”指植物长出芽，学校不会发芽，句意不通。"}, "sentence_index": 6, "correct_answer": "开放"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电影院昨晚开放了新片。", "explanation": "这里应该用〈放映〉。放映指把电影放给观众看，新片要用放映；开放用于场所或设施允许进入或使用。"}, {"text": "妈妈开放了一条围巾。", "explanation": "这里应该用〈织〉。织指用线编成衣物，围巾要用织；开放指让场所或资源对外允许接近或使用，不用于织物。"}, {"text": "他开放了那条绳子。", "explanation": "这里应该用〈解开〉。解开指松开打结或绑着的东西，绳子要用解开；开放指让场所或资源对外允许接近或使用，不用于松绑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c56a0ea9-c8d7-4fa3-ad4e-ab5f94a36891') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27502, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座公园现在还没开放了，你下午再来吧。", "corrected_sentence": "这座公园现在还没开放，你下午再来吧。", "error_description": "“没”与“了”不能同用：表示尚未发生应说“还没开放”，句末加“了”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c56a0ea9-c8d7-4fa3-ad4e-ab5f94a36891') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27502, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "博物馆昨天没开放了，我们白跑了一趟。", "corrected_sentence": "博物馆昨天没开放，我们白跑了一趟。", "error_description": "“没”与“了”不能同用：说明过去某天未开放应说“没开放”，句末不加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c56a0ea9-c8d7-4fa3-ad4e-ab5f94a36891') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
