INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27504, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变得不一样。", "primary_collocate": null, "pronunciation": "chā yì huà", "ipa": "ʈʂʰa˥ i˥˩ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "公司想实现产品差异化。", "target_word": "差异化", "complexity_tier": "T3", "furigana": "gōng sī xiǎng shí xiàn chǎn pǐn chā yì huà.", "sentence_source": "generated"}, {"text": "我们要提供差异化服务，吸引更多客人。", "target_word": "差异化", "complexity_tier": "T3", "furigana": "wǒ men yào tí gōng chā yì huà fú wù, xī yǐn gèng duō kè rén.", "sentence_source": "generated"}, {"text": "这家店努力差异化，不想和别人一样。", "target_word": "差异化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了差异化，他们换了新包装。", "target_word": "差异化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师会对教学进行差异化，照顾每个学生。", "target_word": "差异化", "complexity_tier": "T3", "furigana": "lǎo shī huì duì jiào xué jìn xíng chā yì huà, zhào gù měi gè xué shēng.", "sentence_source": "generated"}, {"text": "小店必须差异化，才能和大店竞争。", "target_word": "差异化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们实行差异化定价，让不同的人都能买。", "target_word": "差异化", "complexity_tier": "T3", "furigana": "tā men shí xíng chā yì huà dìng jià, ràng bù tóng de rén dōu néng mǎi.", "sentence_source": "generated"}, {"text": "品牌想差异化，就要有自己的特点。", "target_word": "差异化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们的菜单还需要更多差异化。", "target_word": "差异化", "complexity_tier": "T3", "furigana": "nǐ men de cài dān hái xū yào gèng duō chā yì huà.", "sentence_source": "generated"}, {"text": "我们打算差异化经营，不卖别家的东西。", "target_word": "差异化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "差异", "label": "复合"}, {"form": "差异化了", "label": "体标"}, {"form": "差異化", "label": "繁体"}], "register": "正式", "sense_fingerprint": "使东西与别的不同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2be58e91-1e7c-48b9-beed-073729f7dde7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27504, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "差异化", "is_correct": true, "explanation": "正确。“实现产品差异化”中，“差异化”指使产品与别的不同，符合句意。"}, {"text": "摧毁", "is_correct": false, "explanation": "语义：“公司想实现”的目标是产品与别的不同，摧毁产品与句意相反。"}, {"text": "失业", "is_correct": false, "explanation": "语义：“失业”指没有工作，与产品无关，不能用于“实现产品”。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：“跑步”是一种运动，不能说“实现产品跑步”，句意不通。"}], "explanations": {"差异化": "正确。“实现产品差异化”中，“差异化”指使产品与别的不同，符合句意。", "摧毁": "语义：“公司想实现”的目标是产品与别的不同，摧毁产品与句意相反。", "失业": "语义：“失业”指没有工作，与产品无关，不能用于“实现产品”。", "跑步": "语义：“跑步”是一种运动，不能说“实现产品跑步”，句意不通。"}, "sentence_index": 0, "correct_answer": "差异化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "为了让顾客差异化我们，他们换了新包装。", "explanation": "这里应该用〈区分〉。差异化是使事物本身变得不同，让顾客辨认出我们要用〈区分〉。"}, {"text": "他们差异化了资料，方便大家看。", "explanation": "这里应该用〈整理〉。差异化是使东西与别的不同，把资料理顺、分类要用〈整理〉。"}, {"text": "他们差异化了洗衣机，很快就修好了。", "explanation": "这里应该用〈修理〉。差异化是使东西与别的不同，把坏的东西修好要用〈修理〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7920bec-511e-4978-abf0-7c5fcd4f53ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27504, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "差异化", "is_correct": true, "explanation": "正确。“实行差异化定价”是动词修饰定价，指定价因人而异、各不相同。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”是休息的动作，不能修饰“定价”，句意不通。"}, {"text": "抢购", "is_correct": false, "explanation": "搭配：“定价”前常用“统一、分级、浮动”等词，“抢购”不能修饰定价。"}, {"text": "失业", "is_correct": false, "explanation": "语义：“失业”指没有工作，与定价方式无关，句意不通。"}], "explanations": {"差异化": "正确。“实行差异化定价”是动词修饰定价，指定价因人而异、各不相同。", "睡觉": "语义：“睡觉”是休息的动作，不能修饰“定价”，句意不通。", "抢购": "搭配：“定价”前常用“统一、分级、浮动”等词，“抢购”不能修饰定价。", "失业": "语义：“失业”指没有工作，与定价方式无关，句意不通。"}, "sentence_index": 6, "correct_answer": "差异化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们打算差异化一顿午饭，吃完再去上班。", "explanation": "这里应该用〈吃〉。差异化是使东西与别的不同，吃午饭要用〈吃〉。"}, {"text": "他把这篇文章差异化成了英文。", "explanation": "这里应该用〈翻译〉。差异化是使东西与别的不同，把文章换成另一种语言要用〈翻译〉。"}, {"text": "他用计算器差异化出了总数。", "explanation": "这里应该用〈计算〉。差异化是使东西与别的不同，算出总数要用〈计算〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7920bec-511e-4978-abf0-7c5fcd4f53ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27504, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们没被产品差异化，所以顾客还分不清。", "corrected_sentence": "他们没把产品差异化，所以顾客还分不清。", "error_description": "“把”字句中的“把”误写成“被”。“被”表被动，不能引出“产品”作为“差异化”的对象；应说“他们没把产品差异化”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7920bec-511e-4978-abf0-7c5fcd4f53ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27504, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把菜单差异化了过，价格没变。", "corrected_sentence": "他们把菜单差异化了，价格没变。", "error_description": "“了”和“过”不能同时用在同一个动词后面。应只保留“了”，写成“把菜单差异化了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7920bec-511e-4978-abf0-7c5fcd4f53ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27506, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "顺向", "is_correct": true, "explanation": "正确。“顺向”与“逆向”相对，指朝同一个方向走或想，二者构成反义关系。"}, {"text": "停留", "is_correct": false, "explanation": "与“逆向”没有反义关系。“停留”指停下不动，与方向相反无关。"}, {"text": "观望", "is_correct": false, "explanation": "与“逆向”没有反义关系。“观望”指先看形势再决定，与行走的方向无关。"}, {"text": "购买", "is_correct": false, "explanation": "与“逆向”没有反义关系。“购买”指花钱买东西，与方向无关。"}], "correct_answer": "顺向", "explanations": {"顺向": "正确。“顺向”与“逆向”相对，指朝同一个方向走或想，二者构成反义关系。", "停留": "与“逆向”没有反义关系。“停留”指停下不动，与方向相反无关。", "观望": "与“逆向”没有反义关系。“观望”指先看形势再决定，与行走的方向无关。", "购买": "与“逆向”没有反义关系。“购买”指花钱买东西，与方向无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83165e94-7919-4e31-9338-a38194427f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27506, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "顺向", "is_correct": true, "explanation": "正确。“顺向”与“逆向”相对，指朝同一个方向走或想，二者构成反义关系。"}, {"text": "等待", "is_correct": false, "explanation": "与“逆向”没有反义关系。“等待”指停下来期望某事发生，与方向无关。"}, {"text": "休息", "is_correct": false, "explanation": "与“逆向”没有反义关系。“休息”指停止劳动或活动，与方向无关。"}, {"text": "散步", "is_correct": false, "explanation": "与“逆向”没有反义关系。“散步”指悠闲地走，只是一种行动，与朝哪个方向走无关。"}], "correct_answer": "顺向", "explanations": {"顺向": "正确。“顺向”与“逆向”相对，指朝同一个方向走或想，二者构成反义关系。", "等待": "与“逆向”没有反义关系。“等待”指停下来期望某事发生，与方向无关。", "休息": "与“逆向”没有反义关系。“休息”指停止劳动或活动，与方向无关。", "散步": "与“逆向”没有反义关系。“散步”指悠闲地走，只是一种行动，与朝哪个方向走无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83165e94-7919-4e31-9338-a38194427f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27506, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "action", "definition": "朝着相反的方向走或者想。", "primary_collocate": null, "pronunciation": "nì xiàng", "ipa": "ni˥˩ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "大家都往前走，他却逆向而行。", "target_word": "逆向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼一路逆向洄游，想回到老家。", "target_word": "逆向", "complexity_tier": "T3", "furigana": "yú yí lù nì xiàng huí yóu, xiǎng huí dào lǎo jiā。", "sentence_source": "generated"}, {"text": "遇到问题时，你可以逆向想一想。", "target_word": "逆向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人群向东走，她一个人逆向走着。", "target_word": "逆向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总爱逆向思考，想法和别人不同。", "target_word": "逆向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走廊里人太多，我们只好逆向慢慢挤过去。", "target_word": "逆向", "complexity_tier": "T3", "furigana": "zǒu láng lǐ rén tài duō, wǒ men zhǐ hǎo nì xiàng màn màn jǐ guò qù。", "sentence_source": "generated"}, {"text": "走错路后，他们决定逆向折回，重新找路。", "target_word": "逆向", "complexity_tier": "T3", "furigana": "zǒu cuò lù hòu, tā men jué dìng nì xiàng zhé huí, chóng xīn zhǎo lù。", "sentence_source": "generated"}, {"text": "从结果逆向想，就能找到原因。", "target_word": "逆向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们逆向跑，撞到了朋友。", "target_word": "逆向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人往上爬，他偏要逆向往下走。", "target_word": "逆向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "逆向思维", "label": "复合"}, {"form": "逆向工程", "label": "复合"}], "register": "中性", "sense_fingerprint": "朝相反方向走或想", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c6d0dad-2ddf-4382-b7de-80be2a8c3a9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27506, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "逆向", "is_correct": true, "explanation": "正确。目标词读 nì xiàng（第四声、第四声），意思是朝相反的方向走或想。"}, {"text": "内向", "is_correct": false, "explanation": "nèi（第四声）与 nì（第四声）声调相同，韵母不同（ei 与 i），意思是性格向内、不爱外露。"}, {"text": "意向", "is_correct": false, "explanation": "yì 与 nì 声母不同（零声母与 n），声调相同，意思是打算或意图。"}, {"text": "立项", "is_correct": false, "explanation": "lì 与 nì 声母不同（l 与 n），第二音节 xiàng 相同，意思是批准设立一个项目。"}, {"text": "志向", "is_correct": false, "explanation": "zhì 与 nì 声母不同（zh 与 n），声调相同，意思是立志追求的目标。"}], "explanations": {"逆向": "正确。目标词读 nì xiàng（第四声、第四声），意思是朝相反的方向走或想。", "内向": "nèi（第四声）与 nì（第四声）声调相同，韵母不同（ei 与 i），意思是性格向内、不爱外露。", "意向": "yì 与 nì 声母不同（零声母与 n），声调相同，意思是打算或意图。", "立项": "lì 与 nì 声母不同（l 与 n），第二音节 xiàng 相同，意思是批准设立一个项目。", "志向": "zhì 与 nì 声母不同（zh 与 n），声调相同，意思是立志追求的目标。"}, "sentence_index": null, "correct_answer": "逆向"}, "level_3": {"options": [{"text": "逆向", "is_correct": true, "explanation": "正确。“逆向而行”指朝相反方向走，与“大家都往前走”形成对比，“却”的转折成立。"}, {"text": "随从", "is_correct": false, "explanation": "语义：“随从”表示跟着别人走，与“大家都往前走”的走向一致，与“却”的转折矛盾。"}, {"text": "前进", "is_correct": false, "explanation": "语义：“前进”与前句“往前走”重复，不能构成“却”所要求的转折对比。"}, {"text": "同行", "is_correct": false, "explanation": "搭配：“同行”指一起走，不说“同行而行”，与“他却”的语境也不合。"}], "explanations": {"逆向": "正确。“逆向而行”指朝相反方向走，与“大家都往前走”形成对比，“却”的转折成立。", "随从": "语义：“随从”表示跟着别人走，与“大家都往前走”的走向一致，与“却”的转折矛盾。", "前进": "语义：“前进”与前句“往前走”重复，不能构成“却”所要求的转折对比。", "同行": "搭配：“同行”指一起走，不说“同行而行”，与“他却”的语境也不合。"}, "sentence_index": 0, "correct_answer": "逆向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他总是逆向吃饭，吃得很慢。", "explanation": "这里不能用〈逆向〉。学习者易把“逆向”理解为“与众不同的做法”，但它只指朝相反方向走或想，不能用来说“吃饭”的方式。"}, {"text": "他逆向了大家的意愿。", "explanation": "这里应该用〈违背〉。“逆向”只表示朝相反方向走或想，不表示违反大家的意愿。"}, {"text": "人群向东走，她一个人逆向地睡着了。", "explanation": "这里不能用〈逆向〉。学习者易受上句“人群向东走”影响，把“逆向”理解为“逆着人群”，但它不能修饰“睡着”这类静止的状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83165e94-7919-4e31-9338-a38194427f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27506, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "逆向", "is_correct": true, "explanation": "正确。“逆向折回”指朝相反方向往回走，与“走错路后”“重新找路”的语境吻合。"}, {"text": "直行", "is_correct": false, "explanation": "语义：“直行”指一直向前走，与“折回”的方向相反，句意矛盾。"}, {"text": "跳过", "is_correct": false, "explanation": "搭配：“跳过”指越过某段，不能与“折回”组合，句意不通。"}, {"text": "并排", "is_correct": false, "explanation": "搭配：“并排”说位置相邻，不修饰“折回”这种改变方向的动作。"}], "explanations": {"逆向": "正确。“逆向折回”指朝相反方向往回走，与“走错路后”“重新找路”的语境吻合。", "直行": "语义：“直行”指一直向前走，与“折回”的方向相反，句意矛盾。", "跳过": "搭配：“跳过”指越过某段，不能与“折回”组合，句意不通。", "并排": "搭配：“并排”说位置相邻，不修饰“折回”这种改变方向的动作。"}, "sentence_index": 6, "correct_answer": "逆向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子逆向地爱上了那位老师。", "explanation": "这里不能用〈逆向〉。学习者易把“逆向”理解为“与常情相反”的感情，但它只指朝相反方向走或想，不表示感情的变化。"}, {"text": "这次比赛他的成绩很逆向。", "explanation": "这里应该用〈糟糕〉。学习者易把“逆向”理解为“反常”，但它只指朝相反方向走或想，不能用来评价成绩。"}, {"text": "这座山很逆向，我们爬得很轻松。", "explanation": "这里应该用〈陡峭〉或〈平缓〉。学习者易把“逆向”理解为“难爬”，但它只描述方向或思路，不用来形容山的难易。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83165e94-7919-4e31-9338-a38194427f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27506, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他逆向了走了一段路。", "corrected_sentence": "他逆向走了一段路。", "error_description": "错误形式“逆向了走了”，正确形式“逆向走了”。“了”只能放在动词“走”之后，“逆向”与动词之间不能插入“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83165e94-7919-4e31-9338-a38194427f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27506, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们只好逆向了折回，重新找路。", "corrected_sentence": "他们只好逆向折回，重新找路。", "error_description": "错误形式“逆向了折回”，正确形式“逆向折回”。“逆向”作状语修饰动词“折回”，二者之间不能插入“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83165e94-7919-4e31-9338-a38194427f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27508, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f05e7d5-5a65-4a7f-99e6-119fbf78b385') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27508, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f05e7d5-5a65-4a7f-99e6-119fbf78b385') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27508, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "竞争力就是看谁做得更好、更快的能力。", "primary_collocate": null, "pronunciation": "jìng zhēng lì", "ipa": "tɕiŋ˥˩ ʈʂɤŋ˥ li˥˩", "syllable_count": 3, "sentences": [{"text": "这个队跑得又快又稳，竞争力很强。", "target_word": "竞争力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小店的菜便宜又好吃，很有竞争力。", "target_word": "竞争力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会三种语言，找工作更有竞争力。", "target_word": "竞争力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的手机比别人的便宜，有竞争力。", "target_word": "竞争力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂做得慢，没有竞争力。", "target_word": "竞争力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学新技术可以提高你的竞争力。", "target_word": "竞争力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的蛋糕又新鲜又便宜，竞争力很强。", "target_word": "竞争力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想赢比赛，球队要有竞争力。", "target_word": "竞争力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "速度慢的公司，竞争力会变弱。", "target_word": "竞争力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学电脑，让自己更有竞争力。", "target_word": "竞争力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "核心竞争力", "label": "复合"}], "register": "中性", "sense_fingerprint": "比别人做得更好更快的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84e52338-d86c-46e6-8c0d-e6c3d2a19ae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27508, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "竞争力", "is_correct": true, "explanation": "正确。“竞争力”指比别人做得更好更快的能力，与“跑得又快又稳”照应。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色指色彩，与“跑得又快又稳”所说的能力无关，“颜色很强”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高描述高矮，不能用“很强”来形容一个队的表现。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道指口感或气味，与“跑得快、稳”无关，“味道很强”在这里说不通。"}], "explanations": {"竞争力": "正确。“竞争力”指比别人做得更好更快的能力，与“跑得又快又稳”照应。", "颜色": "语义：颜色指色彩，与“跑得又快又稳”所说的能力无关，“颜色很强”说不通。", "身高": "体貌：身高描述高矮，不能用“很强”来形容一个队的表现。", "味道": "语义：味道指口感或气味，与“跑得快、稳”无关，“味道很强”在这里说不通。"}, "sentence_index": 0, "correct_answer": "竞争力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车的竞争力很快，跑得很稳。", "explanation": "这里应该用〈速度〉。竞争力指比别人更好更快的能力，描述快慢要说“速度”，不能直接说“竞争力很快”。"}, {"text": "两家工厂之间的竞争力很激烈。", "explanation": "这里应该用〈竞争〉。“激烈”形容的是竞争的过程；竞争力是能力，不能说“竞争力很激烈”。"}, {"text": "这家工厂有了一辆很强的竞争力。", "explanation": "这里应该用〈种〉。竞争力是抽象能力，量词用“种”；“辆”只用于车辆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f05e7d5-5a65-4a7f-99e6-119fbf78b385') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27508, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "竞争力", "is_correct": true, "explanation": "正确。“竞争力”指做得更好更快的能力，与“又新鲜又便宜”所说的优势相合。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材描述人的体型，蛋糕没有身材，不能说“身材很强”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄只用于人或动物，不能形容蛋糕，“年龄很强”说不通。"}, {"text": "脸色", "is_correct": false, "explanation": "语义：脸色指人的面部气色，与蛋糕无关，不能说明它的优势。"}], "explanations": {"竞争力": "正确。“竞争力”指做得更好更快的能力，与“又新鲜又便宜”所说的优势相合。", "身材": "体貌：身材描述人的体型，蛋糕没有身材，不能说“身材很强”。", "年龄": "语义：年龄只用于人或动物，不能形容蛋糕，“年龄很强”说不通。", "脸色": "语义：脸色指人的面部气色，与蛋糕无关，不能说明它的优势。"}, "sentence_index": 6, "correct_answer": "竞争力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位选手有一只很强的竞争力。", "explanation": "这里应该用〈种〉。竞争力是抽象能力，量词用“种”；“只”用于动物等，不能用于能力。"}, {"text": "他们的竞争力越来越多。", "explanation": "这里应该用〈竞争对手〉。竞争力是能力，不能按数量增加；“越来越多”说的是对手。"}, {"text": "这场竞争力很激烈。", "explanation": "这里应该用〈竞赛〉。竞争力是能力，不指比赛本身；“激烈”形容的是竞赛或竞争的过程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f05e7d5-5a65-4a7f-99e6-119fbf78b385') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27508, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店的服务很好，有一台很强的竞争力。", "corrected_sentence": "这家店的服务很好，有一种很强的竞争力。", "error_description": "量词错误：“竞争力”是抽象能力，应用“种”，不用“台”（“台”用于机器等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f05e7d5-5a65-4a7f-99e6-119fbf78b385') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27508, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这支球队的竞争力的很强。", "corrected_sentence": "这支球队的竞争力很强。", "error_description": "多余的“的”：“竞争力”后不应再接“的”，应说“球队的竞争力很强”，不说“球队的竞争力的很强”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f05e7d5-5a65-4a7f-99e6-119fbf78b385') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27510, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进攻性", "is_correct": true, "explanation": "进攻性与防御性相对：防御性指保护自己，进攻性指主动攻击。"}, {"text": "柔软", "is_correct": false, "explanation": "不在反义关系内：柔软形容质地，与“防御性”没有对应的反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "不在反义关系内：明亮形容光线或颜色，与“防御性”没有对应的反义关系。"}, {"text": "宽广", "is_correct": false, "explanation": "不在反义关系内：宽广形容面积或胸怀，与“防御性”没有对应的反义关系。"}], "correct_answer": "进攻性", "explanations": {"进攻性": "进攻性与防御性相对：防御性指保护自己，进攻性指主动攻击。", "柔软": "不在反义关系内：柔软形容质地，与“防御性”没有对应的反义关系。", "明亮": "不在反义关系内：明亮形容光线或颜色，与“防御性”没有对应的反义关系。", "宽广": "不在反义关系内：宽广形容面积或胸怀，与“防御性”没有对应的反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30e01f3b-6813-4633-bc7a-b4a3994fd854') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27510, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "攻击性", "is_correct": true, "explanation": "攻击性与防御性相对：前者指主动攻击，后者指保护自己。"}, {"text": "清澈", "is_correct": false, "explanation": "不在反义关系内：清澈形容水或眼神干净透明，与“防御性”没有反义关系。"}, {"text": "沉重", "is_correct": false, "explanation": "不在反义关系内：沉重形容分量或心情，与“防御性”没有反义关系。"}, {"text": "狭窄", "is_correct": false, "explanation": "不在反义关系内：狭窄形容空间小，与“防御性”没有反义关系。"}], "correct_answer": "攻击性", "explanations": {"攻击性": "攻击性与防御性相对：前者指主动攻击，后者指保护自己。", "清澈": "不在反义关系内：清澈形容水或眼神干净透明，与“防御性”没有反义关系。", "沉重": "不在反义关系内：沉重形容分量或心情，与“防御性”没有反义关系。", "狭窄": "不在反义关系内：狭窄形容空间小，与“防御性”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30e01f3b-6813-4633-bc7a-b4a3994fd854') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27510, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "用来保护自己，不让别人伤害。", "primary_collocate": null, "pronunciation": "fáng yù xìng", "ipa": "fɑŋ˧˥ y˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "刺猬身上的刺有防御性，能保护自己。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一种防御性武器，只能用来保护自己。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他举起手臂，做了一个防御性的动作。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城墙是防御性建筑，能挡住外面的敌人。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫看到大狗，身体缩成一团，这是防御性姿势。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到危险时，很多动物会有防御性行为。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拳击手双手护头，先采取防御性站位。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个防御性装备能保护你的头，让你不受伤。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在课上学防御性技巧，遇到坏人不怕。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乌龟的壳有防御性作用，不让敌人伤害它。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "防禦性", "label": "繁体"}, {"form": "防御性武器", "label": "复合"}], "register": "中性", "sense_fingerprint": "防御性：用来保护自己、不让别人伤害的（武器、动作、行为）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88bcbd-fe2c-4dba-ab0f-04f6851766bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27510, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "防御性", "is_correct": true, "explanation": "防御性指用来保护自己、不让别人伤害的，刺用来保护身体，与句意一致。"}, {"text": "柔软性", "is_correct": false, "explanation": "语义：刺应是尖硬的，“柔软性”与“刺”的特点相反，也与“能保护自己”矛盾。"}, {"text": "装饰性", "is_correct": false, "explanation": "语义：“装饰性”指起美化作用，刺的功能是保护身体，不能用来说明它能保护自己。"}, {"text": "透明性", "is_correct": false, "explanation": "搭配：“透明性”说的是能否透光，不能用来修饰刺。"}], "explanations": {"防御性": "防御性指用来保护自己、不让别人伤害的，刺用来保护身体，与句意一致。", "柔软性": "语义：刺应是尖硬的，“柔软性”与“刺”的特点相反，也与“能保护自己”矛盾。", "装饰性": "语义：“装饰性”指起美化作用，刺的功能是保护身体，不能用来说明它能保护自己。", "透明性": "搭配：“透明性”说的是能否透光，不能用来修饰刺。"}, "sentence_index": 0, "correct_answer": "防御性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只狗的防御性很强，常常主动扑向路人。", "explanation": "这里应该用〈攻击性〉。防御性指被动保护自己，主动扑向别人属于攻击，应说“攻击性很强”。"}, {"text": "这首歌的防御性很高，旋律十分轻快。", "explanation": "这里应该用〈感染力〉。防御性指用来保护自己，形容歌曲打动人心的力量要说“感染力”，不能用防御性。"}, {"text": "这支部队的防御性很强，专门负责偷袭敌人的后方。", "explanation": "这里应该用〈进攻性〉。防御性指保护自己，偷袭敌人的后方是进攻行为，要说“进攻性很强”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30e01f3b-6813-4633-bc7a-b4a3994fd854') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27510, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "防御性", "is_correct": true, "explanation": "双手护头是为了保护自己，所以这里应用〈防御性〉。"}, {"text": "观赏性", "is_correct": false, "explanation": "语义：护头是为了保护自己，“观赏性”指供人欣赏的效果，与句中的保护动作不符。"}, {"text": "季节性", "is_correct": false, "explanation": "搭配：“季节性”说的是随季节变化的特点，不能用来修饰站位。"}, {"text": "附着性", "is_correct": false, "explanation": "搭配：“附着性”说的是附在其他物体上的能力，不能用来修饰站位。"}], "explanations": {"防御性": "双手护头是为了保护自己，所以这里应用〈防御性〉。", "观赏性": "语义：护头是为了保护自己，“观赏性”指供人欣赏的效果，与句中的保护动作不符。", "季节性": "搭配：“季节性”说的是随季节变化的特点，不能用来修饰站位。", "附着性": "搭配：“附着性”说的是附在其他物体上的能力，不能用来修饰站位。"}, "sentence_index": 6, "correct_answer": "防御性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个国家的防御性很强，不断派兵攻打邻国。", "explanation": "这里应该用〈侵略性〉。防御性指保护自己，派兵攻打邻国属于侵略，应说“侵略性很强”。"}, {"text": "他说话很有防御性，故意挑起争端。", "explanation": "这里应该用〈挑衅性〉。防御性指保护自己，故意挑起争端是挑衅，应说“挑衅性很强”。"}, {"text": "这种药水的防御性很强，会让皮肤发红发痒。", "explanation": "这里应该用〈刺激性〉。防御性用于保护自己的武器、装备、行为，药水伤害皮肤的性质应说“刺激性”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30e01f3b-6813-4633-bc7a-b4a3994fd854') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27510, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他防御性的抬起手臂，挡住了对方的拳头。", "corrected_sentence": "他防御性地抬起手臂，挡住了对方的拳头。", "error_description": "助词错误：修饰动词“抬起”的成分应用“地”，写作“防御性地抬起”；这里误用“的”，应改为“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30e01f3b-6813-4633-bc7a-b4a3994fd854') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27510, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块盾牌很防御性，能挡住刀剑。", "corrected_sentence": "这块盾牌很有防御性，能挡住刀剑。", "error_description": "词语漏用：“防御性”是名词，不能直接受“很”修饰，要说“很有防御性”，漏掉“有”是常见错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30e01f3b-6813-4633-bc7a-b4a3994fd854') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
