INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27520, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "意思是很好，没有不好的地方。", "primary_collocate": null, "pronunciation": "wán měi", "ipa": "wan³⁵ mei̯²¹⁴", "syllable_count": 2, "sentences": [{"text": "这道菜的味道很完美，我吃了两碗饭。", "target_word": "完美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的字写得很完美，像印出来的一样。", "target_word": "完美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个答案很完美，一个错误也没有。", "target_word": "完美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚的音乐会完美结束，观众都站起来鼓掌。", "target_word": "完美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服的大小对我来说太完美了。", "target_word": "完美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结果很完美，我们队拿了第一。", "target_word": "完美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得这个房子的位置很完美，离学校很近。", "target_word": "完美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的回答很完美，老师很满意。", "target_word": "完美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气、风景和朋友，一切都很完美。", "target_word": "完美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他完美地完成了任务，经理非常高兴。", "target_word": "完美", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "完美地", "label": "状语形式"}, {"form": "完美主义", "label": "复合词"}, {"form": "完美无缺", "label": "复合词"}], "register": "中性", "sense_fingerprint": "形容词：很好，没有不好的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bc8be5-758a-4101-a27b-8c54507243b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27520, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "完美", "is_correct": true, "explanation": "正确。「我吃了两碗饭」说明味道很好，「完美」指很好、没有不好的地方，正相符。"}, {"text": "苦", "is_correct": false, "explanation": "语义：「苦」是不好的味道，与「我吃了两碗饭」所表示的满意相矛盾。"}, {"text": "粗", "is_correct": false, "explanation": "搭配：「粗」多形容粗细或质地，不用来形容味道。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：「硬」形容质地，不用来形容味道。"}], "explanations": {"完美": "正确。「我吃了两碗饭」说明味道很好，「完美」指很好、没有不好的地方，正相符。", "苦": "语义：「苦」是不好的味道，与「我吃了两碗饭」所表示的满意相矛盾。", "粗": "搭配：「粗」多形容粗细或质地，不用来形容味道。", "硬": "搭配：「硬」形容质地，不用来形容味道。"}, "sentence_index": 0, "correct_answer": "完美"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次作业很完美，错字多得数不清。", "explanation": "这里应该用〈马虎〉。「完美」表示没有任何缺点，错字多得数不清说明做得很不认真，应该用「马虎」。"}, {"text": "他太完美了，又把牛奶洒得桌上到处都是。", "explanation": "这里应该用〈粗心〉。「完美」表示没有缺点，又把牛奶洒得到处都是说明他不小心，应该用「粗心」。"}, {"text": "他的身体很完美，在床上躺了整整两天。", "explanation": "这里应该用〈虚弱〉。「完美」表示没有任何缺陷，躺了两天说明身体不好，应该用「虚弱」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27520, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "完美", "is_correct": true, "explanation": "正确。后半句「离学校很近」说明位置便利，「完美」表示很好、没有不好的地方，与之相合。"}, {"text": "远", "is_correct": false, "explanation": "语义：「远」与后半句「离学校很近」矛盾，位置不可能既远又近。"}, {"text": "寂寞", "is_correct": false, "explanation": "搭配：「寂寞」多用于人，不用来形容房子的位置。"}, {"text": "伤心", "is_correct": false, "explanation": "搭配：「伤心」形容人的情绪，不能用来形容房子的位置。"}], "explanations": {"完美": "正确。后半句「离学校很近」说明位置便利，「完美」表示很好、没有不好的地方，与之相合。", "远": "语义：「远」与后半句「离学校很近」矛盾，位置不可能既远又近。", "寂寞": "搭配：「寂寞」多用于人，不用来形容房子的位置。", "伤心": "搭配：「伤心」形容人的情绪，不能用来形容房子的位置。"}, "sentence_index": 6, "correct_answer": "完美"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盘菜很完美，咸得没法入口。", "explanation": "这里应该用〈难吃〉。「完美」表示没有缺点，咸得没法入口说明菜不好吃，应该用「难吃」。"}, {"text": "这次我的答题很完美，却只得了零分。", "explanation": "这里应该用〈认真〉。「完美」指结果没有缺陷，「只得了零分」说明答题并不好，两者矛盾；只说态度认真时用「认真」。"}, {"text": "这份合同的内容很完美，还漏掉了一条重要条款。", "explanation": "这里应该用〈基本完整〉。「完美」指没有任何缺陷，「漏掉了一条重要条款」是缺陷，两者矛盾；只说大体齐全时用「基本完整」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27520, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把晚餐安排完美极了，大家都吃得很开心。", "corrected_sentence": "她把晚餐安排得完美极了，大家都吃得很开心。", "error_description": "错误形式：「安排完美极了」。正确形式：「安排得完美极了」。动词后面用形容词说明程度时，要用「得」连接，漏掉「得」不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27520, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这份报告写很完美，老师很满意。", "corrected_sentence": "他把这份报告写得很完美，老师很满意。", "error_description": "错误形式：「写很完美」。正确形式：「写得很完美」。表示程度的补语要用「得」连接动词和形容词，漏掉「得」不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
