INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27524, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "“还”表示做另外一件事，或者事情没有变。", "primary_collocate": null, "pronunciation": "hái", "ipa": "xaɪ˧˥", "syllable_count": 1, "sentences": [{"text": "他还在家。", "target_word": "还", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我还要一杯水。", "target_word": "还", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "现在还很早。", "target_word": "还", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们还没吃饭。", "target_word": "还", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "雨还在下，你别出去。", "target_word": "还", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他吃了饭，还喝了茶。", "target_word": "还", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她会说汉语，还会说英语。", "target_word": "还", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看完电影，还去买了东西。", "target_word": "还", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这么晚了，妈妈还在工作。", "target_word": "还", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我已经吃了很多，可是还想再吃一点儿。", "target_word": "还", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词：表示另外还有，或表示情况继续不变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9421cf6-24de-499f-a0bb-a94d3893ac19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27524, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "还", "is_correct": true, "explanation": "正确。还读 hái，是副词，表示另外还有或情况没有变。"}, {"text": "海", "is_correct": false, "explanation": "hǎi（第三声）与 hái（第二声）声调不同，意思是海洋。"}, {"text": "寒", "is_correct": false, "explanation": "hán 与 hái 韵母不同（an 与 ai），意思是寒冷。"}, {"text": "嗨", "is_correct": false, "explanation": "hāi（第一声）与 hái（第二声）声调不同，是打招呼的感叹词。"}, {"text": "害", "is_correct": false, "explanation": "hài（第四声）与 hái（第二声）声调不同，意思是伤害。"}], "explanations": {"还": "正确。还读 hái，是副词，表示另外还有或情况没有变。", "海": "hǎi（第三声）与 hái（第二声）声调不同，意思是海洋。", "寒": "hán 与 hái 韵母不同（an 与 ai），意思是寒冷。", "嗨": "hāi（第一声）与 hái（第二声）声调不同，是打招呼的感叹词。", "害": "hài（第四声）与 hái（第二声）声调不同，意思是伤害。"}, "sentence_index": null, "correct_answer": "还"}, "level_3": {"options": [{"text": "还", "is_correct": true, "explanation": "正确。“还”表示情况没有变，与“他还在家”的持续语境相符。"}, {"text": "业已", "is_correct": false, "explanation": "语域：“业已”是书面语，放在口语叙述里很生硬。"}, {"text": "从", "is_correct": false, "explanation": "语法：“从”是介词，后面要接起点，“他从在家”不成句。"}, {"text": "被", "is_correct": false, "explanation": "语法：“被”表示被动，“他被在家”不成句。"}], "explanations": {"还": "正确。“还”表示情况没有变，与“他还在家”的持续语境相符。", "业已": "语域：“业已”是书面语，放在口语叙述里很生硬。", "从": "语法：“从”是介词，后面要接起点，“他从在家”不成句。", "被": "语法：“被”表示被动，“他被在家”不成句。"}, "sentence_index": 0, "correct_answer": "还"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一到车站，车还开走了。", "explanation": "这里应该用〈就〉。“一…就…”表示前一动作紧接着发生，“还”不能表示这种紧接的先后关系。"}, {"text": "请还说一遍，好吗？", "explanation": "这里应该用〈再〉。“还”不表示重复一次，请人重说要用“再”。"}, {"text": "他还洗完澡，电话就响了。", "explanation": "这里应该用〈刚〉。“刚”表示动作不久前完成，“还”不能表示刚刚完成的意思，应说“刚洗完澡”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27524, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "还", "is_correct": true, "explanation": "正确。还读 hái，是副词，表示另外还有或情况没有变。"}, {"text": "害", "is_correct": false, "explanation": "hài（第四声）与 hái（第二声）声调不同，意思是伤害。"}, {"text": "含", "is_correct": false, "explanation": "hán 与 hái 韵母不同（an 与 ai），意思是包含。"}, {"text": "嗨", "is_correct": false, "explanation": "hāi（第一声）与 hái（第二声）声调不同，是打招呼的感叹词。"}, {"text": "航", "is_correct": false, "explanation": "háng 与 hái 韵母不同（ang 与 ai），意思是航行。"}], "explanations": {"还": "正确。还读 hái，是副词，表示另外还有或情况没有变。", "害": "hài（第四声）与 hái（第二声）声调不同，意思是伤害。", "含": "hán 与 hái 韵母不同（an 与 ai），意思是包含。", "嗨": "hāi（第一声）与 hái（第二声）声调不同，是打招呼的感叹词。", "航": "háng 与 hái 韵母不同（ang 与 ai），意思是航行。"}, "sentence_index": null, "correct_answer": "还"}, "level_3": {"options": [{"text": "还", "is_correct": true, "explanation": "正确。“还”表示另外还有，与“她会说汉语”的并列语境相符。"}, {"text": "就", "is_correct": false, "explanation": "语义：“就”表示正好或只是，与并列补充的语境不符。"}, {"text": "仅", "is_correct": false, "explanation": "语义：“仅”表示只有，与“会说汉语”的并列语境矛盾。"}, {"text": "再", "is_correct": false, "explanation": "搭配：“再”表示又一次，不能用来修饰“会说”这类能力。"}], "explanations": {"还": "正确。“还”表示另外还有，与“她会说汉语”的并列语境相符。", "就": "语义：“就”表示正好或只是，与并列补充的语境不符。", "仅": "语义：“仅”表示只有，与“会说汉语”的并列语境矛盾。", "再": "搭配：“再”表示又一次，不能用来修饰“会说”这类能力。"}, "sentence_index": 6, "correct_answer": "还"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她二十岁还学会做饭。", "explanation": "这里应该用〈才〉。“二十岁才学会”表示学会得晚，“还”不能表达这种晚到的意味。"}, {"text": "他八点还到了办公室。", "explanation": "这里应该用〈就〉。表示时间早要说“八点就到了”，“还”不能表示早到。"}, {"text": "我等了一个小时，他还来了。", "explanation": "这里应该用〈才〉。等了很久以后他终于来了，要说“才来”，“还”不能表示来得晚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27524, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在还喝茶。", "corrected_sentence": "他还在喝茶。", "error_description": "副词位置错误：表示动作持续的“还”要放在“在”前面，说“还在喝茶”，不能说“在还喝茶”。错误形式是“在还喝茶”，正确形式是“还在喝茶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27524, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这间房子很大，房租很还便宜。", "corrected_sentence": "这间房子很大，房租还很便宜。", "error_description": "副词位置错误：“还”要放在“很”前面，说“还很便宜”，不能放在“很”后面。错误形式是“很还便宜”，正确形式是“还很便宜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27526, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "坏", "is_correct": true, "explanation": "正确：“坏”与“好”构成反义关系，指心情不好。"}, {"text": "慢", "is_correct": false, "explanation": "与“好”无反义或近义关系：“慢”是“快”的反义词。"}, {"text": "远", "is_correct": false, "explanation": "与“好”无反义或近义关系：“远”指距离长。"}, {"text": "硬", "is_correct": false, "explanation": "与“好”无反义或近义关系：“硬”指质地坚实。"}], "correct_answer": "坏", "explanations": {"坏": "正确：“坏”与“好”构成反义关系，指心情不好。", "慢": "与“好”无反义或近义关系：“慢”是“快”的反义词。", "远": "与“好”无反义或近义关系：“远”指距离长。", "硬": "与“好”无反义或近义关系：“硬”指质地坚实。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27526, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "差", "is_correct": true, "explanation": "正确：“差”与“好”构成反义关系，指质量不好。"}, {"text": "厚", "is_correct": false, "explanation": "与“好”无反义或近义关系：“厚”指厚度大。"}, {"text": "重", "is_correct": false, "explanation": "与“好”无反义或近义关系：“重”指分量大。"}, {"text": "高", "is_correct": false, "explanation": "与“好”无反义或近义关系：“高”指高度。"}], "correct_answer": "差", "explanations": {"差": "正确：“差”与“好”构成反义关系，指质量不好。", "厚": "与“好”无反义或近义关系：“厚”指厚度大。", "重": "与“好”无反义或近义关系：“重”指分量大。", "高": "与“好”无反义或近义关系：“高”指高度。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27526, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "好的意思是让人觉得开心、满意。", "primary_collocate": null, "pronunciation": "hǎo", "ipa": "xau˨˩˦", "syllable_count": 1, "sentences": [{"text": "今天天气真好。", "target_word": "好", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家店的服务很好。", "target_word": "好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我有一个好朋友。", "target_word": "好", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的心情今天很好。", "target_word": "好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书很好，我想再看一遍。", "target_word": "好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹的成绩很好，妈妈很高兴。", "target_word": "好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天晚上我睡得很好。", "target_word": "好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的空气比城里好。", "target_word": "好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天是出去玩的好时候。", "target_word": "好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说他的字写得很好。", "target_word": "好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "好好", "label": "重叠"}, {"form": "更好", "label": "比较"}, {"form": "好看", "label": "复合"}], "register": "口语", "sense_fingerprint": "好：事物或人的质量、状态令人开心、满意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfff504e-4568-4828-bef5-09ba6f7af341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27526, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "好", "is_correct": true, "explanation": "正确答案。hǎo（第三声）是“好”的读音，表示令人开心、满意。"}, {"text": "号", "is_correct": false, "explanation": "hào（第四声）与 hǎo（第三声）声调不同，意思是号码、号召。"}, {"text": "毫", "is_correct": false, "explanation": "háo（第二声）与 hǎo（第三声）声调不同，意思是毫米、一点点（毫不）。"}, {"text": "海", "is_correct": false, "explanation": "hǎi 与 hǎo 韵母不同（ai 与 ao），意思是海洋。"}, {"text": "考", "is_correct": false, "explanation": "kǎo 与 hǎo 声母不同（k 与 h），意思是考试。"}, {"text": "老", "is_correct": false, "explanation": "lǎo 与 hǎo 声母不同（l 与 h），意思是年纪大、陈旧。"}], "explanations": {"好": "正确答案。hǎo（第三声）是“好”的读音，表示令人开心、满意。", "号": "hào（第四声）与 hǎo（第三声）声调不同，意思是号码、号召。", "毫": "háo（第二声）与 hǎo（第三声）声调不同，意思是毫米、一点点（毫不）。", "海": "hǎi 与 hǎo 韵母不同（ai 与 ao），意思是海洋。", "考": "kǎo 与 hǎo 声母不同（k 与 h），意思是考试。", "老": "lǎo 与 hǎo 声母不同（l 与 h），意思是年纪大、陈旧。"}, "sentence_index": null, "correct_answer": "好"}, "level_3": {"options": [{"text": "好", "is_correct": true, "explanation": "正确：“真好”评价天气令人满意，符合语境。"}, {"text": "快", "is_correct": false, "explanation": "语义：“快”说速度，不能用来形容天气。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”形容物体质地，不说天气硬。"}, {"text": "重", "is_correct": false, "explanation": "语义：“重”说分量，不能用来形容天气。"}], "explanations": {"好": "正确：“真好”评价天气令人满意，符合语境。", "快": "语义：“快”说速度，不能用来形容天气。", "硬": "搭配：“硬”形容物体质地，不说天气硬。", "重": "语义：“重”说分量，不能用来形容天气。"}, "sentence_index": 0, "correct_answer": "好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "作业终于做好了，我们可以去玩了。", "explanation": "这里的「好」表示完成、做完，是另一个意思，不表示令人开心、满意。"}, {"text": "好，我马上就去。", "explanation": "这里的「好」是应答语，表示同意，是另一个意思，不表示令人开心、满意。"}, {"text": "他的病好了，明天可以去上学了。", "explanation": "这里的「好」表示病愈，是另一个意思，不表示令人开心、满意。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27526, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "好", "is_correct": true, "explanation": "正确答案。hǎo（第三声）是“好”的读音。"}, {"text": "耗", "is_correct": false, "explanation": "hào（第四声）与 hǎo（第三声）声调不同，意思是消耗。"}, {"text": "豪", "is_correct": false, "explanation": "háo（第二声）与 hǎo（第三声）声调不同，意思是豪迈、豪华。"}, {"text": "草", "is_correct": false, "explanation": "cǎo 与 hǎo 声母不同（c 与 h），意思是草。"}, {"text": "宝", "is_correct": false, "explanation": "bǎo 与 hǎo 声母不同（b 与 h），意思是宝贝。"}], "explanations": {"好": "正确答案。hǎo（第三声）是“好”的读音。", "耗": "hào（第四声）与 hǎo（第三声）声调不同，意思是消耗。", "豪": "háo（第二声）与 hǎo（第三声）声调不同，意思是豪迈、豪华。", "草": "cǎo 与 hǎo 声母不同（c 与 h），意思是草。", "宝": "bǎo 与 hǎo 声母不同（b 与 h），意思是宝贝。"}, "sentence_index": null, "correct_answer": "好"}, "level_3": {"options": [{"text": "好", "is_correct": true, "explanation": "正确：“睡得很好”评价睡眠质量，符合语境。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”指光线明亮，不能形容睡眠。"}, {"text": "高", "is_correct": false, "explanation": "语义：“高”指高度，不能形容睡眠的状态。"}, {"text": "贵", "is_correct": false, "explanation": "搭配：“贵”形容价格，不能修饰“睡得”。"}], "explanations": {"好": "正确：“睡得很好”评价睡眠质量，符合语境。", "亮": "语义：“亮”指光线明亮，不能形容睡眠。", "高": "语义：“高”指高度，不能形容睡眠的状态。", "贵": "搭配：“贵”形容价格，不能修饰“睡得”。"}, "sentence_index": 6, "correct_answer": "好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "衣服洗好了，你去拿吧。", "explanation": "这里的“好”作结果补语，表示完成，是另一个意思，不表示令人开心、满意。"}, {"text": "公园里有好多人在跳舞。", "explanation": "这里的“好”表示数量多、程度高，相当于“很”，是另一个意思，不表示令人开心、满意。"}, {"text": "这个问题很好回答。", "explanation": "这里的“好”表示容易，修饰动词，是另一个意思，不表示令人开心、满意。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27526, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹在学校有很好朋友。", "corrected_sentence": "我妹妹在学校有好朋友。", "error_description": "错误：“很好朋友”。正确：“好朋友”。“好”作定语修饰名词时，前面不能直接加“很”；要说“很好的朋友”需加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27526, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次旅行的天气好很。", "corrected_sentence": "这次旅行的天气很好。", "error_description": "错误：“好很”。正确：“很好”。副词“很”作状语，须放在形容词“好”的前面，不能放在后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
