INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27528, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "公开软件的源代码，让大家一起使用和改进。", "primary_collocate": null, "pronunciation": "kāi yuán", "ipa": "kʰaɪ˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这家公司决定开源这个软件。", "target_word": "开源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把自己的程序开源了。", "target_word": "开源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开源以后，很多人一起改进这个软件。", "target_word": "开源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件是开源的，大家都能免费用。", "target_word": "开源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们想把这个游戏开源。", "target_word": "开源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开源可以让更多人学习代码。", "target_word": "开源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在网上开源了一个小工具。", "target_word": "开源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把这个项目开源了，欢迎大家帮忙。", "target_word": "开源", "complexity_tier": "T3", "furigana": "tā men bǎ zhè ge xiàng mù kāi yuán le, huān yíng dà jiā bāng máng", "sentence_source": "generated"}, {"text": "这个工具已经开源了，很多人在用。", "target_word": "开源", "complexity_tier": "T3", "furigana": "zhè ge gōng jù yǐ jīng kāi yuán le, hěn duō rén zài yòng", "sentence_source": "generated"}, {"text": "学生们开源了自己做的网站代码。", "target_word": "开源", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开源了", "label": "体标"}, {"form": "开源过", "label": "体标"}, {"form": "开源软件", "label": "复合"}], "register": "中性", "sense_fingerprint": "公开软件代码，让大家一起使用和改进", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0457a638-19e5-4662-9085-4b0c62c030be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27528, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原谅", "is_correct": false, "explanation": "语义：软件不能被原谅，“原谅”的对象不是物品。"}, {"text": "开源", "is_correct": true, "explanation": "开源：公开软件代码，供大家使用和改进，与“这个软件”搭配自然。"}, {"text": "吃", "is_correct": false, "explanation": "语义：软件不能被“吃”，这一搭配在句中不通。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“种植”用于植物，不用于软件。"}], "explanations": {"原谅": "语义：软件不能被原谅，“原谅”的对象不是物品。", "开源": "开源：公开软件代码，供大家使用和改进，与“这个软件”搭配自然。", "吃": "语义：软件不能被“吃”，这一搭配在句中不通。", "种植": "搭配：“种植”用于植物，不用于软件。"}, "sentence_index": 0, "correct_answer": "开源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家医院每天早上八点开源。", "explanation": "这里应该用〈开门〉。开源专指公开软件代码，医院、商店开始营业用开门。"}, {"text": "这个公园对所有人开源。", "explanation": "这里应该用〈开放〉。开源只说软件代码的公开，公园、场所对外开放用开放。"}, {"text": "我们把照片开源给朋友看。", "explanation": "这里应该用〈分享〉。开源是指把软件代码公开，把照片给朋友看用分享。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27528, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象不能是工具，“在网上喝”也不通。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：“打碎”针对有形器物，网上的工具不能被打碎。"}, {"text": "开源", "is_correct": true, "explanation": "开源：公开软件代码，与“在网上”和“小工具”搭配自然。"}, {"text": "熬", "is_correct": false, "explanation": "搭配：“熬”用于汤药、粥等，不搭配“小工具”。"}], "explanations": {"喝": "语义：“喝”的对象不能是工具，“在网上喝”也不通。", "打碎": "语义：“打碎”针对有形器物，网上的工具不能被打碎。", "开源": "开源：公开软件代码，与“在网上”和“小工具”搭配自然。", "熬": "搭配：“熬”用于汤药、粥等，不搭配“小工具”。"}, "sentence_index": 6, "correct_answer": "开源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把家里的空房间开源给朋友住。", "explanation": "这里应该用〈借〉。开源专指公开软件代码，把房间借给朋友住用借。"}, {"text": "他把自己的钱开源给了灾区。", "explanation": "这里应该用〈捐献〉。开源只用于软件代码的公开，钱财赠予用捐献。"}, {"text": "我把一家好吃的饭馆开源给朋友。", "explanation": "这里应该用〈推荐〉。开源指公开软件代码，把好地方介绍给别人用推荐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27528, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们把这个游戏的开源了。", "corrected_sentence": "他们把这个游戏开源了。", "error_description": "“把”字句错误：“把”后的处置对象“这个游戏”后不能加“的”，应说“他们把这个游戏开源了”，不能写成“他们把这个游戏的开源了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27528, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生们把这个程序开源着。", "corrected_sentence": "学生们把这个程序开源了。", "error_description": "体标错误：“把”字句表示处置并完成，动词后要用“了”，不能用表示持续的“着”。应说“学生们把这个程序开源了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
