INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27538, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "帮别人做事情的人。", "primary_collocate": null, "pronunciation": "zhù shǒu", "ipa": "ʈʂu˥˩ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "小王是我的助手，每天帮我做事。", "target_word": "助手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厨师的助手在洗菜。", "target_word": "助手", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想找一个助手帮我看店。", "target_word": "助手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的助手把东西都准备好了。", "target_word": "助手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让两个学生做她的助手。", "target_word": "助手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个工作太多了，我需要助手。", "target_word": "助手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她当了医生的助手，学到很多。", "target_word": "助手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的助手每天早上八点来上班。", "target_word": "助手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好助手不会让老板担心。", "target_word": "助手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈做饭时，我是她的助手，帮她切菜。", "target_word": "助手", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个助手", "label": "量词"}, {"form": "小助手", "label": "复合"}], "register": "中性", "sense_fingerprint": "帮别人做事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f18f94-d445-4d0e-a98e-278af7fa0f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27538, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "助手", "is_correct": true, "explanation": "正确答案。助手 zhùshǒu，指帮别人做事的人。"}, {"text": "部首", "is_correct": false, "explanation": "部首 bùshǒu 第一个音节声母不同（b 与 zh），意思是汉字的偏旁部件。"}, {"text": "触手", "is_correct": false, "explanation": "触手 chùshǒu 第一个音节声母不同（ch 与 zh），意思是某些动物身上用来感觉、抓取的器官。"}, {"text": "祝寿", "is_correct": false, "explanation": "祝寿 zhùshòu 第二个音节声调不同（shòu 第四声，shǒu 第三声），意思是庆祝生日。"}, {"text": "猪手", "is_correct": false, "explanation": "猪手 zhūshǒu 第一个音节声调不同（zhū 第一声，zhù 第四声），意思是猪蹄。"}], "explanations": {"助手": "正确答案。助手 zhùshǒu，指帮别人做事的人。", "部首": "部首 bùshǒu 第一个音节声母不同（b 与 zh），意思是汉字的偏旁部件。", "触手": "触手 chùshǒu 第一个音节声母不同（ch 与 zh），意思是某些动物身上用来感觉、抓取的器官。", "祝寿": "祝寿 zhùshòu 第二个音节声调不同（shòu 第四声，shǒu 第三声），意思是庆祝生日。", "猪手": "猪手 zhūshǒu 第一个音节声调不同（zhū 第一声，zhù 第四声），意思是猪蹄。"}, "sentence_index": null, "correct_answer": "助手"}, "level_3": {"options": [{"text": "助手", "is_correct": true, "explanation": "正确答案。“小王是我的助手”指帮我做事的人，与“每天帮我做事”一致。"}, {"text": "老板", "is_correct": false, "explanation": "语义：老板是管理者，不会被说成每天来帮我做事，与句中“帮我做事”的语境冲突。"}, {"text": "钢笔", "is_correct": false, "explanation": "搭配：“钢笔”是物品，不能作为“每天帮我做事”的主语。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是建筑物，不能每天帮我做事，与句中语境冲突。"}], "explanations": {"助手": "正确答案。“小王是我的助手”指帮我做事的人，与“每天帮我做事”一致。", "老板": "语义：老板是管理者，不会被说成每天来帮我做事，与句中“帮我做事”的语境冲突。", "钢笔": "搭配：“钢笔”是物品，不能作为“每天帮我做事”的主语。", "房子": "语义：房子是建筑物，不能每天帮我做事，与句中语境冲突。"}, "sentence_index": 0, "correct_answer": "助手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我的助手，每天给我上课，教我很多知识。", "explanation": "这里应该用〈老师〉。给我上课、教我知识的人是老师，助手是帮别人做事的人。"}, {"text": "我的助手和我经常比赛，谁赢谁输都很高兴。", "explanation": "这里应该用〈对手〉。助手是帮别人做事的人，与自己比赛的是对手，两者不能互换。"}, {"text": "他是这家公司的助手，每天负责决定公司的发展方向。", "explanation": "助手是帮别人做事的人，不负责决定公司的方向。这里把决策者说成助手，角色用错了，应该用〈总经理〉或〈负责人〉之类的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0a2b70-9da1-43f2-b93f-cae70927e0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27538, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "助手", "is_correct": true, "explanation": "正确答案。助手 zhùshǒu，指帮别人做事的人。"}, {"text": "着手", "is_correct": false, "explanation": "着手 zhuóshǒu 第一个音节声调不同（zhuó 第二声，zhù 第四声），意思是开始动手去做。"}, {"text": "追手", "is_correct": false, "explanation": "追手 zhuīshǒu 第一个音节韵母与声调不同（zhuī 第一声，zhù 第四声），意思是追赶的人。"}, {"text": "只手", "is_correct": false, "explanation": "只手 zhīshǒu 第一个音节韵母与声调不同（zhī 第一声，zhù 第四声），意思是一只手，常见于“只手遮天”。"}], "explanations": {"助手": "正确答案。助手 zhùshǒu，指帮别人做事的人。", "着手": "着手 zhuóshǒu 第一个音节声调不同（zhuó 第二声，zhù 第四声），意思是开始动手去做。", "追手": "追手 zhuīshǒu 第一个音节韵母与声调不同（zhuī 第一声，zhù 第四声），意思是追赶的人。", "只手": "只手 zhīshǒu 第一个音节韵母与声调不同（zhī 第一声，zhù 第四声），意思是一只手，常见于“只手遮天”。"}, "sentence_index": null, "correct_answer": "助手"}, "level_3": {"options": [{"text": "助手", "is_correct": true, "explanation": "正确答案。“她当了医生的助手”指在医生身边协助工作，符合句中“学到很多”的语境。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是物品，不能“当”医生的什么人，也不能“学到很多”。"}, {"text": "药", "is_correct": false, "explanation": "搭配：“医生的药”不能说成“当了医生的药”，“当”后面不能接物品来表示职务。"}, {"text": "病历", "is_correct": false, "explanation": "语义：病历是记录病情的文件，不能被“当”成职务，与句中的语境冲突。"}], "explanations": {"助手": "正确答案。“她当了医生的助手”指在医生身边协助工作，符合句中“学到很多”的语境。", "桌子": "语义：桌子是物品，不能“当”医生的什么人，也不能“学到很多”。", "药": "搭配：“医生的药”不能说成“当了医生的药”，“当”后面不能接物品来表示职务。", "病历": "语义：病历是记录病情的文件，不能被“当”成职务，与句中的语境冲突。"}, "sentence_index": 6, "correct_answer": "助手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我生病了，所以去医院当医生的助手，请医生给我看病。", "explanation": "这里应该用〈病人〉。请医生看病的人是病人，助手是帮医生做事的人。"}, {"text": "我们班的助手是老师，负责管理全班。", "explanation": "助手是辅助性的角色，不负责全面管理。这里把老师说成助手，身份用错了。"}, {"text": "小狗是我的助手，每天负责睡觉。", "explanation": "这里把〈助手〉用成了〈宠物〉的意思，指陪伴人的动物，而不是协助别人做事的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0a2b70-9da1-43f2-b93f-cae70927e0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27538, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有一条助手，每天帮我做饭。", "corrected_sentence": "我有一位助手，每天帮我做饭。", "error_description": "量词错误：“助手”指人，应用“位”或“个”，“条”多用于细长的东西，不能用于人。错误形式“一条助手”应改为“一位助手”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0a2b70-9da1-43f2-b93f-cae70927e0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27538, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医院新请了一只助手，负责帮护士整理病历。", "corrected_sentence": "医院新请了一个助手，负责帮护士整理病历。", "error_description": "量词用错了。“助手”指人，应用“个”或“位”，不能用“只”。“只”多用于动物或成对的器物，错误形式把“助手”当成了动物或器物。正确形式是“一个助手”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0a2b70-9da1-43f2-b93f-cae70927e0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27540, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27540, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27540, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示重复或再次做同样的事。", "primary_collocate": null, "pronunciation": "yòu", "ipa": "joʊ˥˩", "syllable_count": 1, "sentences": [{"text": "今天又是星期一了。", "target_word": "又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我刚吃完饭，又饿了。", "target_word": "又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他又一次给我写信了。", "target_word": "又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事老师又讲了一遍。", "target_word": "又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的菜，他今天又热了一遍。", "target_word": "又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家饭店他上周去过，这周又去了。", "target_word": "又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟又把杯子打破了。", "target_word": "又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他又问了一次那个问题。", "target_word": "又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车刚修好，又坏了。", "target_word": "又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚洗完衣服，孩子又弄脏了。", "target_word": "又", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "同样的事或时间再一次出现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c5fcf5b-556e-47e4-b003-813f3f632225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27540, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "又", "is_correct": true, "explanation": "正确答案：又 yòu，表示同样的事或时间再一次出现。"}, {"text": "有", "is_correct": false, "explanation": "yǒu（第三声）与 yòu（第四声）声调不同，有意思是拥有。"}, {"text": "漏", "is_correct": false, "explanation": "lòu 与 yòu 声母不同（l 与 y），漏意思是漏出、漏洞。"}, {"text": "后", "is_correct": false, "explanation": "hòu 与 yòu 声母不同（h 与 y），后意思是之后。"}], "explanations": {"又": "正确答案：又 yòu，表示同样的事或时间再一次出现。", "有": "yǒu（第三声）与 yòu（第四声）声调不同，有意思是拥有。", "漏": "lòu 与 yòu 声母不同（l 与 y），漏意思是漏出、漏洞。", "后": "hòu 与 yòu 声母不同（h 与 y），后意思是之后。"}, "sentence_index": null, "correct_answer": "又"}, "level_3": {"options": [{"text": "又", "is_correct": true, "explanation": "正确：“又”表示星期一再一次出现，与“今天是星期一”的时间重复相符。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示从未发生过，与“今天是星期一”的事实相矛盾。"}, {"text": "永远", "is_correct": false, "explanation": "语义：“永远”表示持续不变，不能与已完成的“是星期一了”搭配表示重复。"}, {"text": "将", "is_correct": false, "explanation": "搭配：“将”表示将来，与“了”以及“今天”的已然时间不搭配。"}], "explanations": {"又": "正确：“又”表示星期一再一次出现，与“今天是星期一”的时间重复相符。", "从来": "语义：“从来”表示从未发生过，与“今天是星期一”的事实相矛盾。", "永远": "语义：“永远”表示持续不变，不能与已完成的“是星期一了”搭配表示重复。", "将": "搭配：“将”表示将来，与“了”以及“今天”的已然时间不搭配。"}, "sentence_index": 0, "correct_answer": "又"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他又出生于一九九〇年。", "explanation": "这里应该删去〈又〉。出生只发生一次，不能再次发生，与“又”表示再次的意思矛盾。"}, {"text": "这是我第一次又来这里。", "explanation": "这里应该删去〈又〉。“第一次”说明是首次，与“又”表示再次的意思矛盾。"}, {"text": "我从没吃过这道菜，昨天又吃了一次。", "explanation": "这里应该删去〈又〉。“从没吃过”表示以前从未发生，与“又”表示再次的意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27540, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "又", "is_correct": true, "explanation": "正确答案：又 yòu，表示同样的事或时间再一次出现。"}, {"text": "游", "is_correct": false, "explanation": "yóu（第二声）与 yòu（第四声）声调不同，游意思是游泳。"}, {"text": "友", "is_correct": false, "explanation": "yǒu（第三声）与 yòu（第四声）声调不同，友意思是朋友。"}, {"text": "优", "is_correct": false, "explanation": "yōu（第一声）与 yòu（第四声）声调不同，优意思是优秀。"}, {"text": "透", "is_correct": false, "explanation": "tòu 与 yòu 声母不同（t 与 y），透意思是穿过、透明。"}], "explanations": {"又": "正确答案：又 yòu，表示同样的事或时间再一次出现。", "游": "yóu（第二声）与 yòu（第四声）声调不同，游意思是游泳。", "友": "yǒu（第三声）与 yòu（第四声）声调不同，友意思是朋友。", "优": "yōu（第一声）与 yòu（第四声）声调不同，优意思是优秀。", "透": "tòu 与 yòu 声母不同（t 与 y），透意思是穿过、透明。"}, "sentence_index": null, "correct_answer": "又"}, "level_3": {"options": [{"text": "又", "is_correct": true, "explanation": "正确：“又”表示弟弟打碎杯子这件事再次发生，与前文的重复相符。"}, {"text": "不必", "is_correct": false, "explanation": "语义：“不必”表示没有必要，与“打破了”这一已发生的事实矛盾。"}, {"text": "千万", "is_correct": false, "explanation": "语义：“千万”多用于叮嘱，不能用来叙述弟弟打破杯子的事实。"}, {"text": "务必", "is_correct": false, "explanation": "语域：“务必”是要求将来一定要做的书面用语，不适合叙述已经发生的事。"}], "explanations": {"又": "正确：“又”表示弟弟打碎杯子这件事再次发生，与前文的重复相符。", "不必": "语义：“不必”表示没有必要，与“打破了”这一已发生的事实矛盾。", "千万": "语义：“千万”多用于叮嘱，不能用来叙述弟弟打破杯子的事实。", "务必": "语域：“务必”是要求将来一定要做的书面用语，不适合叙述已经发生的事。"}, "sentence_index": 6, "correct_answer": "又"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是我最后一次又去那里。", "explanation": "这里应该删去〈又〉。“最后一次”表示之后不再发生，与“又”表示再次的意思矛盾。"}, {"text": "我又第一次吃这道菜。", "explanation": "这里应该删去〈又〉。“第一次”表示首次，与“又”表示再次的意思矛盾。"}, {"text": "他直到昨天又开始学习。", "explanation": "这里应该用〈才〉。又表示再次，与“直到昨天”表示到那时才发生的意思矛盾；表示到那时才开始要用“才”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27540, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈又再做了一锅汤。", "corrected_sentence": "妈妈又做了一锅汤。", "error_description": "错误：“又再做”。正确：“又做”。“又”和“再”都表示重复，句中同用属于重复，应删去“再”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27540, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐去又了一次图书馆。", "corrected_sentence": "姐姐又去了一次图书馆。", "error_description": "错误：“去又了”。正确：“又去了”。“又”表示重复，应紧接在动词“去”之前修饰动作，不能放在动词之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
