INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27542, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27542, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "行程就是你出门去一个地方要走的路。", "primary_collocate": null, "pronunciation": "xíng chéng", "ipa": "ɕiŋ˧˥ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "从家到学校的行程不太远。", "target_word": "行程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这段行程要走两个小时。", "target_word": "行程", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "回家的行程很长，我们坐了火车。", "target_word": "行程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一路上的行程很累，大家都想睡觉。", "target_word": "行程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他开车走完了最后一段行程。", "target_word": "行程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从机场到市区的行程要一个小时。", "target_word": "行程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪天去郊外的行程会慢很多。", "target_word": "行程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次去山里的行程有五十公里。", "target_word": "行程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子走了一半行程，就想休息了。", "target_word": "行程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骑车去海边的行程只要二十分钟。", "target_word": "行程", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段行程", "label": "量词"}, {"form": "行程表", "label": "复合"}], "register": "通用", "sense_fingerprint": "从一个地方到另一个地方所走的路程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30a6cad1-527d-4756-8bdd-654c381daff9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27542, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气说的是冷热晴雨，不能用来说从家到学校的距离远近。"}, {"text": "行程", "is_correct": true, "explanation": "正确。行程指从一地到另一地所走的路程，可以说远或不远。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，不是路程，不能说远不远。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的外形特征，不能用来描述路程远近。"}], "explanations": {"天气": "语义：天气说的是冷热晴雨，不能用来说从家到学校的距离远近。", "行程": "正确。行程指从一地到另一地所走的路程，可以说远或不远。", "作业": "语义：作业是学习任务，不是路程，不能说远不远。", "身高": "体貌：身高是人的外形特征，不能用来描述路程远近。"}, "sentence_index": 0, "correct_answer": "行程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇作文的行程很长，写了三页。", "explanation": "这里应该用〈篇幅〉。行程指路程，文章的长短要用篇幅来说。"}, {"text": "我的行程增加了三公斤。", "explanation": "这里应该用〈体重〉。行程指所走的路程，人的重量要用体重。"}, {"text": "这场比赛的行程是三比一，我们赢了。", "explanation": "这里应该用〈比分〉。行程指路程，比赛的得分要用比分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27542, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心情", "is_correct": false, "explanation": "语义：心情没有快慢的速度概念，不能说“会慢很多”。"}, {"text": "行程", "is_correct": true, "explanation": "正确。下雪天走路程会变慢，行程可以说“慢很多”。"}, {"text": "生日", "is_correct": false, "explanation": "语义：生日是日期，不能说快慢，与句意不符。"}, {"text": "皮肤", "is_correct": false, "explanation": "体貌：皮肤属于外貌，不能用“慢很多”来形容。"}], "explanations": {"心情": "语义：心情没有快慢的速度概念，不能说“会慢很多”。", "行程": "正确。下雪天走路程会变慢，行程可以说“慢很多”。", "生日": "语义：生日是日期，不能说快慢，与句意不符。", "皮肤": "体貌：皮肤属于外貌，不能用“慢很多”来形容。"}, "sentence_index": 6, "correct_answer": "行程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把这首歌的行程改成了慢板。", "explanation": "这里应该用〈节奏〉。行程指路线，歌曲的快慢要用节奏来说。"}, {"text": "他的行程很温和，从不发脾气。", "explanation": "这里应该用〈性格〉。行程指路线，人的脾气和为人要用性格来说。"}, {"text": "这杯咖啡的行程很烫，我喝不了。", "explanation": "这里应该用〈温度〉。行程指路线，饮料的冷热要用温度来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27542, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "回家的一篇行程很累。", "corrected_sentence": "回家的一段行程很累。", "error_description": "量词错误：表示路程的“行程”应该用量词“段”，不能用“篇”（“篇”用于文章）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27542, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这段行程他走地很慢。", "corrected_sentence": "这段行程他走得很慢。", "error_description": "补语标志错误：动词后接程度补语要用“得”，应说“走得很慢”；“地”用在动词前作状语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
