INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27546, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "写出文字的东西给很多人看。", "primary_collocate": null, "pronunciation": "xiě wén zhāng", "ipa": "ɕjɛ˨˩˦ wən˧˥ ʈʂɑŋ˥", "syllable_count": 3, "sentences": [{"text": "她在网上写文章给大家看。", "target_word": "写文章", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他写文章介绍中国的美食。", "target_word": "写文章", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人喜欢在网站上写文章。", "target_word": "写文章", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想写文章，让更多人了解这座城市。", "target_word": "写文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生常写文章，教大家怎么健康生活。", "target_word": "写文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作是为报纸写文章。", "target_word": "写文章", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个星期他都会写文章发到网上。", "target_word": "写文章", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你为什么不写文章分享你的旅行呢？", "target_word": "写文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们也可以给学校的网站写文章。", "target_word": "写文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她写文章谈自己学汉语的经验。", "target_word": "写文章", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "写了文章", "label": "体标（了）"}, {"form": "写过文章", "label": "体标（过）"}], "register": "通用", "sense_fingerprint": "写出文章发表出来，给很多读者看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30a6cad1-527d-4756-8bdd-654c381daff9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27546, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发呆", "is_correct": false, "explanation": "语义：发呆没有可以给大家看的内容，与“写文章给大家看”不相配。"}, {"text": "写文章", "is_correct": true, "explanation": "正确。写文章后发布在网上，供大家阅读，符合“给大家看”的句意。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉不能给别人看，与“给大家看”的意思矛盾。"}, {"text": "修理", "is_correct": false, "explanation": "配价：“修理”要带宾语（修理什么），这里单独使用，句子不通。"}], "explanations": {"发呆": "语义：发呆没有可以给大家看的内容，与“写文章给大家看”不相配。", "写文章": "正确。写文章后发布在网上，供大家阅读，符合“给大家看”的句意。", "睡觉": "语义：睡觉不能给别人看，与“给大家看”的意思矛盾。", "修理": "配价：“修理”要带宾语（修理什么），这里单独使用，句子不通。"}, "sentence_index": 0, "correct_answer": "写文章"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天晚上写文章，记下今天花了多少钱。", "explanation": "这里应该用〈记账〉。写文章指写给很多读者看的文章，记录开支要用记账。"}, {"text": "我今天给老板写文章辞职。", "explanation": "这里应该用〈写辞职信〉。辞职信写给一个人，不是发表给很多读者看的文章。"}, {"text": "春节时我给朋友写文章拜年。", "explanation": "这里应该用〈写贺卡〉。拜年要写贺卡，不是发表给很多读者看的文章。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27546, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃饭", "is_correct": false, "explanation": "语义：吃饭不能发到网上，与“发到网上”的动作搭配不上。"}, {"text": "写文章", "is_correct": true, "explanation": "正确。写文章后发到网上，指写出作品供读者阅读。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步不是可以发到网上的成果，与“发到网上”的意思矛盾。"}, {"text": "删除", "is_correct": false, "explanation": "配价：“删除”要带宾语（删除什么），这里单独使用，句子不通。"}], "explanations": {"吃饭": "语义：吃饭不能发到网上，与“发到网上”的动作搭配不上。", "写文章": "正确。写文章后发到网上，指写出作品供读者阅读。", "散步": "语义：散步不是可以发到网上的成果，与“发到网上”的意思矛盾。", "删除": "配价：“删除”要带宾语（删除什么），这里单独使用，句子不通。"}, "sentence_index": 6, "correct_answer": "写文章"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他上课时写文章，记下老师讲的内容。", "explanation": "这里应该用〈写笔记〉。写笔记是记录课堂内容，不是写给很多人看的文章。"}, {"text": "他给老师写文章请假。", "explanation": "这里应该用〈写请假条〉。请假要写请假条，不是写成篇的文章。"}, {"text": "他在相册上写文章，写了照片的日期。", "explanation": "这里应该用〈写日期〉。相册上只标注日期，不是给很多人看的成篇文章。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27546, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她写文章写很好。", "corrected_sentence": "她写文章写得很好。", "error_description": "补语错误：“写”后面的程度补语要用“得”连接，应说“写得很好”，不能省掉“得”直接说“写很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27546, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她很写文章。", "corrected_sentence": "她很喜欢写文章。", "error_description": "搭配错误：“很”是程度副词，要修饰形容词或“喜欢”这类心理动词，不能直接放在“写文章”前，应说“很喜欢写文章”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
