INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27552, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "不是管理员，是平常使用电脑或手机的人。", "primary_collocate": null, "pronunciation": "pǔ tōng yòng hù", "ipa": "pʰu˨˩˦ tʰʊŋ˥ jʊŋ˥˩ xu˥˩", "syllable_count": 4, "sentences": [{"text": "我不是管理员，只是普通用户。", "target_word": "普通用户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "普通用户打开手机就能用这个软件。", "target_word": "普通用户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "普通用户没有权限进入后台。", "target_word": "普通用户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台电脑上有一个普通用户和一个管理员。", "target_word": "普通用户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是公司网站的普通用户，每天上网看新闻。", "target_word": "普通用户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "普通用户用手机买东西很方便。", "target_word": "普通用户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "管理员给普通用户发了一封邮件。", "target_word": "普通用户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏的普通用户有一百万人。", "target_word": "普通用户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "普通用户忘了密码，要找管理员帮忙。", "target_word": "普通用户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这款电脑操作简单，普通用户上手很快。", "target_word": "普通用户", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位普通用户", "label": "量词"}, {"form": "一个普通用户", "label": "量词"}], "register": "通用", "sense_fingerprint": "不是管理员、平常使用电脑或手机的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30a6cad1-527d-4756-8bdd-654c381daff9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27552, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "普通用户", "is_correct": true, "explanation": "正确。与前句「我不是管理员」相对，指不是管理员、平常使用电脑或手机的人。"}, {"text": "管理员", "is_correct": false, "explanation": "语义：与前句「我不是管理员」直接矛盾，「只是管理员」说不通。"}, {"text": "软件", "is_correct": false, "explanation": "搭配：「只是」后接的是身份类名词，不能接「软件」这类物品。"}, {"text": "服务器", "is_correct": false, "explanation": "语义：「服务器」不是人的身份，不能用来说明「我」的身份。"}], "explanations": {"普通用户": "正确。与前句「我不是管理员」相对，指不是管理员、平常使用电脑或手机的人。", "管理员": "语义：与前句「我不是管理员」直接矛盾，「只是管理员」说不通。", "软件": "搭配：「只是」后接的是身份类名词，不能接「软件」这类物品。", "服务器": "语义：「服务器」不是人的身份，不能用来说明「我」的身份。"}, "sentence_index": 0, "correct_answer": "普通用户"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们公司来了一辆普通用户，想学习这个软件。", "explanation": "这里应该用〈位〉或〈个〉。「辆」用于车辆，不用来数人。"}, {"text": "教室里有一只普通用户在上网。", "explanation": "这里应该用〈位〉或〈个〉。「只」用于动物，不用来数指人的「普通用户」。"}, {"text": "院子里走来一头普通用户。", "explanation": "这里应该用〈位〉或〈个〉。「头」用于牲畜，不用来数人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27552, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "普通用户", "is_correct": true, "explanation": "正确。「管理员给……发了一封邮件」的收件人是使用系统的人，「普通用户」符合此语境。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户无法收信，不能作为「发了一封邮件」的收件人。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视不能阅读邮件，与「发了一封邮件」的收件人不符。"}, {"text": "空气", "is_correct": false, "explanation": "配价：「给……发邮件」的受事须是能收信的人或机构，「空气」不能充当。"}], "explanations": {"普通用户": "正确。「管理员给……发了一封邮件」的收件人是使用系统的人，「普通用户」符合此语境。", "窗户": "语义：窗户无法收信，不能作为「发了一封邮件」的收件人。", "电视": "语义：电视不能阅读邮件，与「发了一封邮件」的收件人不符。", "空气": "配价：「给……发邮件」的受事须是能收信的人或机构，「空气」不能充当。"}, "sentence_index": 6, "correct_answer": "普通用户"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位普通用户管理着整个系统的权限。", "explanation": "这里应该用〈管理员〉。普通用户指不是管理员的人，不能管理系统权限。"}, {"text": "这家餐厅的普通用户负责做菜。", "explanation": "这里应该用〈厨师〉。普通用户指使用服务的人，不负责做菜；「负责做菜」说的是厨师的工作。"}, {"text": "那位普通用户指挥了整场比赛。", "explanation": "这里应该用〈裁判〉。普通用户指没有特殊权限的使用者，不指负责执法的裁判。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27552, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屏幕前坐着一台普通用户。", "corrected_sentence": "屏幕前坐着一位普通用户。", "error_description": "「普通用户」指人，计量词应用「位」或「个」，不能用「台」（「台」用于机器、设备）。应说「一位普通用户」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27552, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个网站只有三个普通用户们。", "corrected_sentence": "这个网站只有三个普通用户。", "error_description": "错误在「们」。名词前已有数量词「三个」时，后面不能再加「们」。应去掉「们」，说「这个网站只有三个普通用户」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
