INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27553, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用来告诉电脑做什么的指令。", "primary_collocate": null, "pronunciation": "chéng xù dài mǎ", "ipa": "ʈʂʰɤŋ˧˥ ɕy˥˩ taɪ̯˥˩ ma˨˩˦", "syllable_count": 4, "sentences": [{"text": "电脑要看程序代码才知道做什么。", "target_word": "程序代码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥正在学写程序代码。", "target_word": "程序代码", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这是一段很短的程序代码。", "target_word": "程序代码", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "程序代码告诉电脑下一步做什么。", "target_word": "程序代码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把程序代码写在电脑里。", "target_word": "程序代码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏的程序代码很长。", "target_word": "程序代码", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我看不懂这些程序代码。", "target_word": "程序代码", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他写了十行程序代码。", "target_word": "程序代码", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "程序代码里有一个小错误。", "target_word": "程序代码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教我们怎么写程序代码。", "target_word": "程序代码", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段程序代码", "label": "量词"}, {"form": "一行程序代码", "label": "量词"}], "register": "中性", "sense_fingerprint": "告诉电脑该做什么的指令", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f18f94-d445-4d0e-a98e-278af7fa0f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27553, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "程序代码", "is_correct": true, "explanation": "正确：电脑通过读取程序指令，才知道下一步做什么。"}, {"text": "香水", "is_correct": false, "explanation": "语义：香水不是指令，电脑看了也不知道做什么。"}, {"text": "沙子", "is_correct": false, "explanation": "语义：沙子不是指令，电脑看了也不知道做什么。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：鸡蛋不是指令，电脑看了也不知道做什么。"}], "explanations": {"程序代码": "正确：电脑通过读取程序指令，才知道下一步做什么。", "香水": "语义：香水不是指令，电脑看了也不知道做什么。", "沙子": "语义：沙子不是指令，电脑看了也不知道做什么。", "鸡蛋": "语义：鸡蛋不是指令，电脑看了也不知道做什么。"}, "sentence_index": 0, "correct_answer": "程序代码"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这段程序代码是我们约定的暗号。", "explanation": "这里应该用〈暗号〉。“程序代码”指计算机指令，不指约定好的暗号。"}, {"text": "他的程序代码是“夜鹰”。", "explanation": "这里应该用〈代号〉。“代码”在这里指代号，程序代码只指计算机指令，不能用来称呼人。"}, {"text": "她现在是一位出色的程序代码。", "explanation": "这里应该用〈程序员〉。程序代码不是人，修饰“出色”的对象应是程序员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0a2b70-9da1-43f2-b93f-cae70927e0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27553, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "程序代码", "is_correct": true, "explanation": "正确：指看不懂的程序指令文本。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果是用来吃的，“看不懂这些水果”说不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“这些”一般修饰可数的东西，空气不可数，不说“这些空气”。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度是测量得出的数值，不是需要阅读理解的文字。"}], "explanations": {"程序代码": "正确：指看不懂的程序指令文本。", "水果": "语义：水果是用来吃的，“看不懂这些水果”说不通。", "空气": "搭配：“这些”一般修饰可数的东西，空气不可数，不说“这些空气”。", "温度": "语义：温度是测量得出的数值，不是需要阅读理解的文字。"}, "sentence_index": 6, "correct_answer": "程序代码"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个文件的程序代码是UTF-8。", "explanation": "这里应该用〈编码〉。“程序代码”指计算机指令，不能指文件的字符编码方式。"}, {"text": "公司制定了新的员工程序代码。", "explanation": "这里应该用〈准则〉。“程序代码”指计算机指令，不能指员工要遵守的行为规范。"}, {"text": "这个仪式的程序代码很长。", "explanation": "这里应该用〈流程〉。“程序代码”指计算机指令，不能用来说仪式的先后步骤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0a2b70-9da1-43f2-b93f-cae70927e0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27553, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师给我们看了一只程序代码。", "corrected_sentence": "老师给我们看了一段程序代码。", "error_description": "量词错误：程序代码应用“段”或“行”计量，“只”不能用于程序代码，应改为“一段”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0a2b70-9da1-43f2-b93f-cae70927e0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27553, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他写了一朵程序代码。", "corrected_sentence": "他写了一段程序代码。", "error_description": "量词错误：“朵”用于花、云等，程序代码应用“段”或“行”计量，“一朵”应改为“一段”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0a2b70-9da1-43f2-b93f-cae70927e0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27556, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "好事", "is_correct": true, "explanation": "正确：「好事」与「坏事」为反义词，指好的事情。"}, {"text": "窗户", "is_correct": false, "explanation": "无关：「窗户」是建筑部件，与「坏事」不构成反义。"}, {"text": "草地", "is_correct": false, "explanation": "无关：「草地」指长满草的地面，与「坏事」没有反义关系。"}, {"text": "钥匙", "is_correct": false, "explanation": "无关：「钥匙」是开锁的工具，与「坏事」不构成反义。"}], "correct_answer": "好事", "explanations": {"好事": "正确：「好事」与「坏事」为反义词，指好的事情。", "窗户": "无关：「窗户」是建筑部件，与「坏事」不构成反义。", "草地": "无关：「草地」指长满草的地面，与「坏事」没有反义关系。", "钥匙": "无关：「钥匙」是开锁的工具，与「坏事」不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27556, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "好事", "is_correct": true, "explanation": "正确：「好事」与「坏事」为反义词，指好的事情。"}, {"text": "冰箱", "is_correct": false, "explanation": "无关：「冰箱」是家用电器，与「坏事」不构成反义。"}, {"text": "花园", "is_correct": false, "explanation": "无关：「花园」指种花草的场地，与「坏事」没有反义关系。"}, {"text": "皮鞋", "is_correct": false, "explanation": "无关：「皮鞋」是穿在脚上的物品，与「坏事」不构成反义。"}], "correct_answer": "好事", "explanations": {"好事": "正确：「好事」与「坏事」为反义词，指好的事情。", "冰箱": "无关：「冰箱」是家用电器，与「坏事」不构成反义。", "花园": "无关：「花园」指种花草的场地，与「坏事」没有反义关系。", "皮鞋": "无关：「皮鞋」是穿在脚上的物品，与「坏事」不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27556, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "坏的事情，就是不好的事。", "primary_collocate": null, "pronunciation": "huài shì", "ipa": "xwai˥˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "有时候，坏事也能变成好事。", "target_word": "坏事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天一连发生了三件坏事。", "target_word": "坏事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏事总是一起来。", "target_word": "坏事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "丢了钱包是一件坏事。", "target_word": "坏事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把坏事都告诉了妈妈。", "target_word": "坏事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别怕，坏事很快就会过去。", "target_word": "坏事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好事和坏事，他都想跟家人说。", "target_word": "坏事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试没过，对他是坏事，也是机会。", "target_word": "坏事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天遇到了坏事，心情不好。", "target_word": "坏事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着说，坏事过去了，好事就会来。", "target_word": "坏事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}, {"form": "坏事变好事", "label": "复合"}], "register": "中性", "sense_fingerprint": "坏事：发生的不好的事情，与好事相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47fde9d4-8425-4c39-a479-f50644aa2214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27556, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "坏事", "is_correct": true, "explanation": "正确：huài shì，指发生的不好的事情，与「好事」相对。"}, {"text": "画室", "is_correct": false, "explanation": "huà 与 huài 韵母不同（少了 -i），意思是画室，与本词不同。"}, {"text": "坏死", "is_correct": false, "explanation": "坏死（huàisǐ）第二个音节声母为 s，与「事」的 sh 不同，意思是身体组织死亡。"}, {"text": "坏书", "is_correct": false, "explanation": "shū 与 shì 韵母不同，意思是坏的书，与「坏事」不同。"}], "explanations": {"坏事": "正确：huài shì，指发生的不好的事情，与「好事」相对。", "画室": "huà 与 huài 韵母不同（少了 -i），意思是画室，与本词不同。", "坏死": "坏死（huàisǐ）第二个音节声母为 s，与「事」的 sh 不同，意思是身体组织死亡。", "坏书": "shū 与 shì 韵母不同，意思是坏的书，与「坏事」不同。"}, "sentence_index": null, "correct_answer": "坏事"}, "level_3": {"options": [{"text": "坏事", "is_correct": true, "explanation": "正确：「坏事也能变成好事」中，坏事指不好的事情，符合句意。"}, {"text": "好事", "is_correct": false, "explanation": "语义：「好事也能变成好事」前后重复，与「坏事变成好事」的句意不符。"}, {"text": "坏人", "is_correct": false, "explanation": "语义：人不能「变成好事」，与句中的变化主体不符。"}, {"text": "坏话", "is_correct": false, "explanation": "搭配：「变成好事」的主语应是事件，「坏话」是言语，不宜作此主语。"}], "explanations": {"坏事": "正确：「坏事也能变成好事」中，坏事指不好的事情，符合句意。", "好事": "语义：「好事也能变成好事」前后重复，与「坏事变成好事」的句意不符。", "坏人": "语义：人不能「变成好事」，与句中的变化主体不符。", "坏话": "搭配：「变成好事」的主语应是事件，「坏话」是言语，不宜作此主语。"}, "sentence_index": 0, "correct_answer": "坏事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天拿到了奖学金，这是一件坏事。", "explanation": "这里应该用〈好事〉。拿到奖学金是好事，「坏事」指不好的事，不能用来形容好事。"}, {"text": "他是村里的坏事。", "explanation": "这里应该用〈祸害〉。坏事指事情，不能指人；指人要用「祸害」或「坏人」。"}, {"text": "这个苹果是坏事，不能吃了。", "explanation": "这里应该用〈坏的〉。「坏事」指不好的事情，不能用来说食物变质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27556, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "坏事", "is_correct": true, "explanation": "正确：「好事和坏事」构成对照，「坏事」正好与前面的「好事」相对。"}, {"text": "礼物", "is_correct": false, "explanation": "配价：「说」的对象应为事情或话语，「礼物」不能作说的内容。"}, {"text": "石头", "is_correct": false, "explanation": "语义：「石头」是物体，「好事和石头」不构成对照，与句中的对照结构不符。"}, {"text": "窗户", "is_correct": false, "explanation": "配价：「说」不能以「窗户」作宾语，句中要的是事情。"}], "explanations": {"坏事": "正确：「好事和坏事」构成对照，「坏事」正好与前面的「好事」相对。", "礼物": "配价：「说」的对象应为事情或话语，「礼物」不能作说的内容。", "石头": "语义：「石头」是物体，「好事和石头」不构成对照，与句中的对照结构不符。", "窗户": "配价：「说」不能以「窗户」作宾语，句中要的是事情。"}, "sentence_index": 6, "correct_answer": "坏事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他被法院判了坏事。", "explanation": "这里应该用〈罪〉。法院判的是「罪」，「坏事」不能被「判」，应说「判罪」。"}, {"text": "那件坏事抢走了我的钱包。", "explanation": "这里应该用〈坏人〉。能抢东西的是人，「坏事」指事情，不能作施事主语。"}, {"text": "他把这件坏事装进了箱子里。", "explanation": "此处把「坏事」当作具体物品，「坏事」指抽象的事情，不能装进箱子，应说具体的〈东西〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27556, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他遇到了一只坏事，心里很难过。", "corrected_sentence": "他遇到了一件坏事，心里很难过。", "error_description": "量词错误：「坏事」应用量词「件」；「只」多用于动物及成对物品中的一个，不用于事情。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27556, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那是一件让人难过坏事。", "corrected_sentence": "那是一件让人难过的坏事。", "error_description": "结构错误：修饰语「让人难过」与名词「坏事」之间要加「的」，应说「让人难过的坏事」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
