INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27562, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可以相信的。", "primary_collocate": null, "pronunciation": "kě xìn", "ipa": "kʰɤ˨˩˦ ɕin˥˩", "syllable_count": 2, "sentences": [{"text": "他看起来很老实，说的话可信。", "target_word": "可信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里的历史资料非常可信。", "target_word": "可信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察觉得他的解释不可信。", "target_word": "可信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条新闻没有来源，不太可信。", "target_word": "可信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生的建议当然比广告更可信。", "target_word": "可信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人的名声不好，很难让人觉得可信。", "target_word": "可信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她讲得很清楚，听起来十分可信。", "target_word": "可信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验结果可信，因为做了很多次。", "target_word": "可信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上的天气预报通常可信。", "target_word": "可信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王的借口一点也不可信。", "target_word": "可信", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不可信", "label": "否定形式"}], "register": "中性", "sense_fingerprint": "说法、资料、结果等可以相信，不是假的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47fde9d4-8425-4c39-a479-f50644aa2214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27562, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "可信", "is_correct": true, "explanation": "正确答案：可信（kěxìn），指可以相信、不是假的。"}, {"text": "可心", "is_correct": false, "explanation": "可心（kěxīn）与可信只差第二个音节的声调：「心」为第一声，「信」为第四声。可心意思是称心、合意。"}, {"text": "可行", "is_correct": false, "explanation": "可行（kěxíng）第二个音节的韵母为 íng，与可信的 ìn 不同，意思是行得通。"}, {"text": "可亲", "is_correct": false, "explanation": "可亲（kěqīn）与可信（kěxìn）的第二个音节声母不同（q／x），声调也不同（第一声／第四声）。可亲意思是和蔼、容易亲近。"}], "explanations": {"可信": "正确答案：可信（kěxìn），指可以相信、不是假的。", "可心": "可心（kěxīn）与可信只差第二个音节的声调：「心」为第一声，「信」为第四声。可心意思是称心、合意。", "可行": "可行（kěxíng）第二个音节的韵母为 íng，与可信的 ìn 不同，意思是行得通。", "可亲": "可亲（kěqīn）与可信（kěxìn）的第二个音节声母不同（q／x），声调也不同（第一声／第四声）。可亲意思是和蔼、容易亲近。"}, "sentence_index": null, "correct_answer": "可信"}, "level_3": {"options": [{"text": "可信", "is_correct": true, "explanation": "正确答案：“可信”指说法值得相信，与“老实”的语境相符。"}, {"text": "雪白", "is_correct": false, "explanation": "语义：“雪白”形容颜色，不能用来形容说的话。"}, {"text": "松软", "is_correct": false, "explanation": "搭配：“松软”多用于食物、土壤等，不能修饰说话的内容。"}, {"text": "结实", "is_correct": false, "explanation": "语义：“结实”指物体坚固，不能用来形容说话的可靠程度。"}], "explanations": {"可信": "正确答案：“可信”指说法值得相信，与“老实”的语境相符。", "雪白": "语义：“雪白”形容颜色，不能用来形容说的话。", "松软": "搭配：“松软”多用于食物、土壤等，不能修饰说话的内容。", "结实": "语义：“结实”指物体坚固，不能用来形容说话的可靠程度。"}, "sentence_index": 0, "correct_answer": "可信"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子很可信，坐上去很稳。", "explanation": "这里应该用〈稳固〉。“可信”指资料、说法值得相信，椅子的牢靠程度要用“稳固”。"}, {"text": "这位歌手的嗓子很可信，大家都爱听他唱歌。", "explanation": "这里应该用〈动听〉。“可信”用于说法、资料，不用来形容嗓音。"}, {"text": "这个运动员的跑步很可信，速度非常快。", "explanation": "这里应该用〈迅速〉。“可信”不用于描述动作的快慢，要用“迅速”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27562, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可信", "is_correct": true, "explanation": "正确答案：“可信”说明讲话内容值得相信，与“讲得很清楚”相符。"}, {"text": "狭窄", "is_correct": false, "explanation": "语义：“狭窄”指空间小，不能用来形容说话的声音或内容。"}, {"text": "方正", "is_correct": false, "explanation": "语义：“方正”形容形状，与“讲得很清楚”的语境无关，说不通。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容体形或物体，不能用来形容听起来的感觉。"}], "explanations": {"可信": "正确答案：“可信”说明讲话内容值得相信，与“讲得很清楚”相符。", "狭窄": "语义：“狭窄”指空间小，不能用来形容说话的声音或内容。", "方正": "语义：“方正”形容形状，与“讲得很清楚”的语境无关，说不通。", "高大": "搭配：“高大”形容体形或物体，不能用来形容听起来的感觉。"}, "sentence_index": 6, "correct_answer": "可信"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间房间很可信，阳光从窗户照进来。", "explanation": "这里应该用〈明亮〉。“可信”不用于描述房间的光线，要用“明亮”。"}, {"text": "这棵树很可信，枝叶十分高大。", "explanation": "这里应该用〈茂盛〉。“可信”指值得相信，不用于描述树木的生长状况，要用“茂盛”。"}, {"text": "这束花很可信，放在屋里很久都不会谢。", "explanation": "这里应该用〈持久〉。“可信”指说法值得相信，不用于描述花的存放时间，要用“持久”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27562, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些资料很可信过。", "corrected_sentence": "这些资料很可信。", "error_description": "错误在“过”：“可信”是形容词，描述资料的性质时不用“过”表示经历，应去掉“过”，说“这些资料很可信”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27562, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个说法没可信。", "corrected_sentence": "这个说法不可信。", "error_description": "错误在“没”：形容词“可信”的否定要用“不”，不能用“没”。应改为“这个说法不可信”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27564, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27564, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27564, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "表示事情的结果或者变化是因为前面说的原因。", "primary_collocate": null, "pronunciation": "zhè yàng yī lái", "ipa": "ʈʂɤ⁵¹ jɑŋ⁵¹ i⁵⁵ laɪ³⁵", "syllable_count": 4, "sentences": [{"text": "他每天都锻炼，这样一来，身体比以前好多了。", "target_word": "这样一来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店打折了，这样一来，买东西的人多起来了。", "target_word": "这样一来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们早点儿出门，这样一来，就不会迟到了。", "target_word": "这样一来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不再玩游戏了，这样一来，成绩好了很多。", "target_word": "这样一来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水太脏了，这样一来，鱼都死了。", "target_word": "这样一来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给他加工资，这样一来，他工作更努力了。", "target_word": "这样一来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机没电了，这样一来，我没法给家人打电话。", "target_word": "这样一来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李搬到了学校旁边，这样一来，上课方便多了。", "target_word": "这样一来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们少吃肉多吃菜，这样一来，大家都瘦了。", "target_word": "这样一来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板请了两个新人，这样一来，大家不那么累了。", "target_word": "这样一来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "说明后面的结果或变化是由前面的原因造成的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30a6cad1-527d-4756-8bdd-654c381daff9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27564, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "这样一来", "is_correct": true, "explanation": "正确。表示「每天锻炼」带来的结果：身体比以前好多了。"}, {"text": "不过", "is_correct": false, "explanation": "语义：「不过」表示转折，与「每天锻炼，身体变好」的顺接关系不符。"}, {"text": "然而", "is_correct": false, "explanation": "语域：「然而」偏书面，且表示转折，此处是顺接的结果，不相符。"}, {"text": "否则", "is_correct": false, "explanation": "语义：「否则」表示不然的后果，与「身体比以前好多了」的结果相矛盾。"}], "explanations": {"这样一来": "正确。表示「每天锻炼」带来的结果：身体比以前好多了。", "不过": "语义：「不过」表示转折，与「每天锻炼，身体变好」的顺接关系不符。", "然而": "语域：「然而」偏书面，且表示转折，此处是顺接的结果，不相符。", "否则": "语义：「否则」表示不然的后果，与「身体比以前好多了」的结果相矛盾。"}, "sentence_index": 0, "correct_answer": "这样一来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这样一来，我们先复习，再去考试。", "explanation": "这里应该用〈然后〉。「这样一来」表示由前面原因导致的结果，这里说的是先后顺序，不表示因果，应用〈然后〉。"}, {"text": "他喜欢画画，这样一来，他还会弹吉他。", "explanation": "这里应该用〈另外〉。「这样一来」表示由前面原因导致的结果，两件事没有因果关系，只是补充。"}, {"text": "他很努力，这样一来，成绩不好。", "explanation": "这里应该用〈但是〉。「这样一来」表示顺接的结果，不表示转折，前后是对立关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27564, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "这样一来", "is_correct": true, "explanation": "正确。表示「手机没电」造成的结果：没法给家人打电话。"}, {"text": "可是", "is_correct": false, "explanation": "语义：「可是」表示转折，与「手机没电」导致的结果是顺接关系，不符。"}, {"text": "但是", "is_correct": false, "explanation": "语义：「但是」表示转折，此处前后是因果关系，不能用转折。"}, {"text": "反之", "is_correct": false, "explanation": "语域：「反之」是书面语，表示相反的情况，与这句口语化的叙述不协调。"}], "explanations": {"这样一来": "正确。表示「手机没电」造成的结果：没法给家人打电话。", "可是": "语义：「可是」表示转折，与「手机没电」导致的结果是顺接关系，不符。", "但是": "语义：「但是」表示转折，此处前后是因果关系，不能用转折。", "反之": "语域：「反之」是书面语，表示相反的情况，与这句口语化的叙述不协调。"}, "sentence_index": 6, "correct_answer": "这样一来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很少运动，这样一来，他还是身体很好。", "explanation": "这里应该用〈尽管如此〉。「这样一来」表示顺接的结果，不表示让步，「很少运动还身体好」应用〈尽管如此〉引出转折。"}, {"text": "这样一来，你不去，我就去。", "explanation": "这里应该用〈如果〉。「这样一来」表示结果，不表示假设条件，「你不去」是假设，应用〈如果〉。"}, {"text": "这次比赛很难，这样一来，我们赢了。", "explanation": "这里应该用〈但是〉。「比赛很难」不会导致「赢了」，前后是转折关系，「这样一来」表示的因果关系不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27564, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家少开会，这样一来了，大家都省了不少力气。", "corrected_sentence": "大家少开会，这样一来，大家都省了不少力气。", "error_description": "「这样一来」是连词，后面不能加「了」。应去掉「了」，说「大家少开会，这样一来，大家都省了不少力气」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27564, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天早起，这样一来的就不容易生病了。", "corrected_sentence": "他每天早起，这样一来就不容易生病了。", "error_description": "错误在“的”。“这样一来”是连词，后面不能加“的”。应去掉“的”，说“他每天早起，这样一来就不容易生病了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
