INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27566, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "比一个东西大很多很多。", "primary_collocate": null, "pronunciation": "yuǎn dà yú", "ipa": "ɥɛn˨˩˦ ta˥˩ y˧˥", "syllable_count": 3, "sentences": [{"text": "木星的体积远大于地球。", "target_word": "远大于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间的面积远大于我的卧室。", "target_word": "远大于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大象的身体远大于老鼠。", "target_word": "远大于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个西瓜的个头远大于那个苹果。", "target_word": "远大于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳的大小远大于月亮。", "target_word": "远大于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家的院子远大于我家的。", "target_word": "远大于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的面积远大于那个小镇。", "target_word": "远大于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鲸鱼的个头远大于一般的鱼。", "target_word": "远大于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新体育馆的空间远大于旧的那个。", "target_word": "远大于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张桌子的尺寸远大于普通的书桌。", "target_word": "远大于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "远远大于", "label": "强调形式"}], "register": "中性", "sense_fingerprint": "具体事物在体积、面积、个头上比另一个大很多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47fde9d4-8425-4c39-a479-f50644aa2214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27566, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "远大于", "is_correct": true, "explanation": "远大于：木星的体积远远超过地球，符合事实。"}, {"text": "小于", "is_correct": false, "explanation": "语义：“小于”说木星的体积比地球小，与木星远大于地球的事实相反。"}, {"text": "远离", "is_correct": false, "explanation": "搭配：“远离”表示距离上离开，不能用于比较“体积”的大小。"}, {"text": "远眺", "is_correct": false, "explanation": "搭配：“远眺”指向远处望，不能修饰“体积”。"}], "explanations": {"远大于": "远大于：木星的体积远远超过地球，符合事实。", "小于": "语义：“小于”说木星的体积比地球小，与木星远大于地球的事实相反。", "远离": "搭配：“远离”表示距离上离开，不能用于比较“体积”的大小。", "远眺": "搭配：“远眺”指向远处望，不能修饰“体积”。"}, "sentence_index": 0, "correct_answer": "远大于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脾气远大于那只小猫。", "explanation": "这里误把〈远大于〉当作“差别悬殊”来用。它只比较同类事物的大小，脾气与小猫不是同类，无法比较大小。"}, {"text": "这份报告的字数远大于那张桌子。", "explanation": "这里误把〈远大于〉当作“差别悬殊”来用。它只比较同类事物的大小，字数与桌子不是同类，无法比较大小。"}, {"text": "这首歌的好听程度远大于那个苹果。", "explanation": "这里误把〈远大于〉当作“程度差别很大”来用。它只比较同类事物的大小，好听程度与苹果不是同类，无法比较大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27566, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "远大于", "is_correct": true, "explanation": "远大于：这座城市的面积远远超过小镇，符合句意。"}, {"text": "输给", "is_correct": false, "explanation": "语义：“输给”指在比赛或竞争中失败，不能用来比较面积的大小。"}, {"text": "压倒", "is_correct": false, "explanation": "搭配：“压倒”多用于声势、力量或优势，不说面积压倒某个地方。"}, {"text": "远胜于", "is_correct": false, "explanation": "搭配：“远胜于”多用于能力、成绩等方面的优越，不用来比较面积。"}], "explanations": {"远大于": "远大于：这座城市的面积远远超过小镇，符合句意。", "输给": "语义：“输给”指在比赛或竞争中失败，不能用来比较面积的大小。", "压倒": "搭配：“压倒”多用于声势、力量或优势，不说面积压倒某个地方。", "远胜于": "搭配：“远胜于”多用于能力、成绩等方面的优越，不用来比较面积。"}, "sentence_index": 6, "correct_answer": "远大于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇文章的颜色远大于它的字数。", "explanation": "这里误把〈远大于〉当作“格外醒目”来用。颜色与字数不是同类的大小，无法比较。"}, {"text": "这盏灯的温度远大于它的价格。", "explanation": "这里误把〈远大于〉当作“格外昂贵”来用。温度与价格不是同类的大小，无法比较。"}, {"text": "她的脾气远大于这个月的天气。", "explanation": "这里误把〈远大于〉当作“程度更严重”来用。脾气与天气不是同类的大小，无法比较。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27566, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这艘船的长度远大于。", "corrected_sentence": "这艘船的长度远大于那艘船的长度。", "error_description": "错误位置：“远大于”后面缺少比较对象，句子不完整。应补上与“长度”相对应的比较对象“那艘船的长度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27566, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个湖的面积很远大于那个池塘。", "corrected_sentence": "这个湖的面积远大于那个池塘。", "error_description": "错误位置：多出了副词“很”。“远”本身已表示程度，前面不能再加“很”，应说“远大于”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
