INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27568, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "到达某个地方，或者某个时间来到了。", "primary_collocate": null, "pronunciation": "dào", "ipa": "taʊ˥˩", "syllable_count": 1, "sentences": [{"text": "我们几点到学校？", "target_word": "到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车八点就到了。", "target_word": "到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他昨天到北京了。", "target_word": "到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间到了，我们下课吧。", "target_word": "到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你到家以后给我打电话。", "target_word": "到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人还没到，我们再等一下。", "target_word": "到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，花都开了。", "target_word": "到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我到了机场，才发现忘了带护照。", "target_word": "到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师到教室的时候，大家都坐好了。", "target_word": "到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天你几点到公司？", "target_word": "到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "到了", "label": "体标"}, {"form": "到过", "label": "体标"}, {"form": "到达", "label": "复合"}], "register": "中性", "sense_fingerprint": "到：作谓语的动词，指人或事物到达某地，或时间来临", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06ef7b24-878b-4d84-b099-4f00efa873d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27568, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "到", "is_correct": true, "explanation": "正确答案：到（dào），动词，表示人或事物到达某地或时间来临。"}, {"text": "掏", "is_correct": false, "explanation": "掏（tāo）与到（dào）声母不同（t／d），声调也不同（第一声／第四声），意思是“从里面拿出来”。"}, {"text": "导", "is_correct": false, "explanation": "导（dǎo）与到（dào）声调不同（第三声／第四声），意思是“引导”。"}, {"text": "刀", "is_correct": false, "explanation": "刀（dāo）与到（dào）声调不同（第一声／第四声），意思是“刀子”。"}], "explanations": {"到": "正确答案：到（dào），动词，表示人或事物到达某地或时间来临。", "掏": "掏（tāo）与到（dào）声母不同（t／d），声调也不同（第一声／第四声），意思是“从里面拿出来”。", "导": "导（dǎo）与到（dào）声调不同（第三声／第四声），意思是“引导”。", "刀": "刀（dāo）与到（dào）声调不同（第一声／第四声），意思是“刀子”。"}, "sentence_index": null, "correct_answer": "到"}, "level_3": {"options": [{"text": "到", "is_correct": true, "explanation": "到表示到达某地，与“几点”“学校”共同构成询问到达时间的句子。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”表示建造或修理，与问几点能到的时间不合。"}, {"text": "叫", "is_correct": false, "explanation": "搭配：“叫”不能带处所宾语表示到达，“叫学校”不成立。"}, {"text": "挑", "is_correct": false, "explanation": "搭配：“挑”表示挑选，不能表示到达某地，“挑学校”不能表达到达。"}], "explanations": {"到": "到表示到达某地，与“几点”“学校”共同构成询问到达时间的句子。", "修": "语义：“修”表示建造或修理，与问几点能到的时间不合。", "叫": "搭配：“叫”不能带处所宾语表示到达，“叫学校”不成立。", "挑": "搭配：“挑”表示挑选，不能表示到达某地，“挑学校”不能表达到达。"}, "sentence_index": 0, "correct_answer": "到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "只要努力，我们一定能到这件事。", "explanation": "这里应该用〈做到〉。到表示到达，完成某件事要用“做到”，应说“只要努力，我们一定能做到这件事”。"}, {"text": "我在路上到了老师。", "explanation": "这里应该用〈遇到〉。到表示到达某地，偶然碰见人要用“遇到”，应说“我在路上遇到了老师”。"}, {"text": "我一下子到了一个好办法。", "explanation": "这里应该用〈想到〉。到表示到达，想出办法要用“想到”，应说“我一下子想到了一个好办法”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27568, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "到", "is_correct": true, "explanation": "正确答案：到（dào），动词，表示人或事物到达某地或时间来临。"}, {"text": "岛", "is_correct": false, "explanation": "岛（dǎo）与到（dào）声调不同（第三声／第四声），意思是“岛屿”。"}, {"text": "捣", "is_correct": false, "explanation": "捣（dǎo）与到（dào）声调不同（第三声／第四声），意思是“捣碎”。"}, {"text": "套", "is_correct": false, "explanation": "套（tào）与到（dào）声母不同（t／d），声调相同，意思是“套子”。"}], "explanations": {"到": "正确答案：到（dào），动词，表示人或事物到达某地或时间来临。", "岛": "岛（dǎo）与到（dào）声调不同（第三声／第四声），意思是“岛屿”。", "捣": "捣（dǎo）与到（dào）声调不同（第三声／第四声），意思是“捣碎”。", "套": "套（tào）与到（dào）声母不同（t／d），声调相同，意思是“套子”。"}, "sentence_index": null, "correct_answer": "到"}, "level_3": {"options": [{"text": "到", "is_correct": true, "explanation": "到了表示春天已经来临，与“花都开了”的语境相符。"}, {"text": "赶", "is_correct": false, "explanation": "搭配：“赶”要有追赶的目标，不能表示季节来临，“春天赶了”不成立。"}, {"text": "撞", "is_correct": false, "explanation": "搭配：“撞”表示碰撞，不能用于季节的来临，“春天撞了”不通。"}, {"text": "逼", "is_correct": false, "explanation": "语义：“逼”表示强迫，与“春天”这种自然变化的主语不合。"}], "explanations": {"到": "到了表示春天已经来临，与“花都开了”的语境相符。", "赶": "搭配：“赶”要有追赶的目标，不能表示季节来临，“春天赶了”不成立。", "撞": "搭配：“撞”表示碰撞，不能用于季节的来临，“春天撞了”不通。", "逼": "语义：“逼”表示强迫，与“春天”这种自然变化的主语不合。"}, "sentence_index": 6, "correct_answer": "到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于到了奖学金。", "explanation": "这里应该用〈得到〉。到表示到达，获得东西要用“得到”，应说“他终于得到了奖学金”。"}, {"text": "我昨天到了一封信。", "explanation": "这里应该用〈收到〉。到表示到达某处，接收信件要用“收到”，应说“我昨天收到了一封信”。"}, {"text": "我翻了半天，才到了钥匙。", "explanation": "这里应该用〈找到〉。到表示到达，找寻到东西要用“找到”，应说“我翻了半天，才找到了钥匙”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27568, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我下午就家到了。", "corrected_sentence": "我下午就到家了。", "error_description": "“到家”是动词加宾语，应说“到家了”。“家到了”把宾语放在了动词前，语序颠倒，是错误用法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27568, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他明天就到过北京。", "corrected_sentence": "他明天就到北京。", "error_description": "“到过”表示曾经去过的经历，不能与“明天”这样的将来时间搭配；应去掉“过”，说“他明天就到北京”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
