INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27570, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "做坏事的人，大家都不喜欢他。", "primary_collocate": null, "pronunciation": "huài rén", "ipa": "xwaɪ⁵¹ ɻən³⁵", "syllable_count": 2, "sentences": [{"text": "大家都说他是坏人，没人想跟他玩儿。", "target_word": "坏人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里的坏人最后得到了教训。", "target_word": "坏人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友，坏人给的糖不能吃。", "target_word": "坏人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要告诉警察，那里有坏人。", "target_word": "坏人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他偷东西，大家都叫他坏人。", "target_word": "坏人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里的坏人长得很可怕。", "target_word": "坏人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人为什么总想骗别人的钱？", "target_word": "坏人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，不能因为他穷就说他是坏人。", "target_word": "坏人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里一个人走路，要小心坏人。", "target_word": "坏人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是坏人，只是脾气不好。", "target_word": "坏人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个坏人", "label": "量词：个"}], "register": "口语", "sense_fingerprint": "做坏事、让大家讨厌的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30a6cad1-527d-4756-8bdd-654c381daff9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27570, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "坏人", "is_correct": true, "explanation": "正确：“坏人”指做坏事、让人讨厌的人，与“大家都说他是”搭配，符合句意。"}, {"text": "英雄", "is_correct": false, "explanation": "语义：“英雄”受人敬佩，与“没人想跟他玩儿”矛盾。"}, {"text": "恩人", "is_correct": false, "explanation": "语义：“恩人”是帮助过别人的人，与“没人想跟他玩儿”的语境矛盾。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“是石头”不能指人，且与“没人想跟他玩儿”不搭配。"}], "explanations": {"坏人": "正确：“坏人”指做坏事、让人讨厌的人，与“大家都说他是”搭配，符合句意。", "英雄": "语义：“英雄”受人敬佩，与“没人想跟他玩儿”矛盾。", "恩人": "语义：“恩人”是帮助过别人的人，与“没人想跟他玩儿”的语境矛盾。", "石头": "搭配：“是石头”不能指人，且与“没人想跟他玩儿”不搭配。"}, "sentence_index": 0, "correct_answer": "坏人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨天我在路口看见一只坏人。", "explanation": "这里应该用〈个〉。“只”用于动物，指人要用“个”或“位”。"}, {"text": "他是打篮球的坏人，投篮总是投不进。", "explanation": "这里不能用坏人。此义项指做坏事、让人讨厌的人，篮球技术差应说“差”或“不行”。"}, {"text": "这家餐厅的菜是坏人，我们别去了。", "explanation": "这里不能用坏人。坏人指做坏事的人，菜不是人，难吃应说“难吃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27570, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "坏人", "is_correct": true, "explanation": "正确：“坏人”指做坏事的人，与“总想骗别人的钱”搭配，符合句意。"}, {"text": "好心人", "is_correct": false, "explanation": "语义：“好心人”指心地善良的人，与“总想骗别人的钱”矛盾。"}, {"text": "善人", "is_correct": false, "explanation": "语义：“善人”与“总想骗别人的钱”的意思相反，句子说不通。"}, {"text": "小猫", "is_correct": false, "explanation": "搭配：“骗钱”的主语须是能做事的人，小猫不能骗人的钱。"}], "explanations": {"坏人": "正确：“坏人”指做坏事的人，与“总想骗别人的钱”搭配，符合句意。", "好心人": "语义：“好心人”指心地善良的人，与“总想骗别人的钱”矛盾。", "善人": "语义：“善人”与“总想骗别人的钱”的意思相反，句子说不通。", "小猫": "搭配：“骗钱”的主语须是能做事的人，小猫不能骗人的钱。"}, "sentence_index": 6, "correct_answer": "坏人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他帮我找回了钱包，真是个坏人。", "explanation": "这里应该用〈好人〉。坏人指做坏事、让人讨厌的人，帮别人找回钱包是做好事。"}, {"text": "那个坏人扶老奶奶过马路，大家都很感谢他。", "explanation": "这里应该用〈好心人〉。坏人指做坏事的人，扶老人过马路、受人感谢的是好心人。"}, {"text": "我买了一条坏人，很有纪念意义。", "explanation": "这里应该用〈个〉。“条”用于细长的物品，指人要用“个”或“位”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27570, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一坏人，偷了我的钱。", "corrected_sentence": "他是一个坏人，偷了我的钱。", "error_description": "错误在量词。“坏人”前必须用量词，应说“一个坏人”，不能省略“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27570, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我不认识那个坏人们，别担心。", "corrected_sentence": "我不认识那个坏人，别担心。", "error_description": "错误在“们”。“那个”是单数指示词，“坏人”后不能再加表示复数的“们”，应删去“们”，说“那个坏人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
