INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27572, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "支持者就是站在你这边、帮你说话的人。", "primary_collocate": null, "pronunciation": "zhī chí zhě", "ipa": "ʈʂɻ̩˥ ʈʂʰɻ̩˧˥ ʈʂɤ˨˩˧", "syllable_count": 3, "sentences": [{"text": "我在公司有几个支持者。", "target_word": "支持者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有了家人这样的支持者，我不怕。", "target_word": "支持者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吵架时，妹妹总是我的支持者。", "target_word": "支持者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你需要一个站在你这边的支持者。", "target_word": "支持者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最好的支持者是我妈妈。", "target_word": "支持者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别担心，你不是没有支持者。", "target_word": "支持者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他找到了几个支持者，帮他说话。", "target_word": "支持者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，我的支持者替我说了话。", "target_word": "支持者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明有很多支持者，大家都愿意帮他。", "target_word": "支持者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛输了，她的支持者还在鼓掌。", "target_word": "支持者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "支持者们", "label": "复合"}], "register": "中性", "sense_fingerprint": "支持者：站在自己一边、替自己说话的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47fde9d4-8425-4c39-a479-f50644aa2214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27572, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "支持者", "is_correct": true, "explanation": "正确：「在公司有几个」指站在自己这边的人，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」不能「在公司有几个」，与句子主语不符。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：「雨水」不是人，不能说在公司「有几个雨水」，量词「个」也不搭配「雨水」。"}, {"text": "海风", "is_correct": false, "explanation": "语义：海风不可能存在于公司，与「在公司有」矛盾。"}], "explanations": {"支持者": "正确：「在公司有几个」指站在自己这边的人，符合句意。", "天气": "语义：「天气」不能「在公司有几个」，与句子主语不符。", "雨水": "语义：「雨水」不是人，不能说在公司「有几个雨水」，量词「个」也不搭配「雨水」。", "海风": "语义：海风不可能存在于公司，与「在公司有」矛盾。"}, "sentence_index": 0, "correct_answer": "支持者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你需要一位公正的支持者，判断谁对谁错。", "explanation": "这里应该用〈中立者〉。判断对错要中立，「支持者」是站在你这边的人，不能公正判断。"}, {"text": "你要防备那个站在你对面的支持者。", "explanation": "这里应该用〈对手〉。支持者是站在你这边的人，不能站在对面。"}, {"text": "我的支持者替我去吹哨子，判了对方犯规。", "explanation": "这里应该用〈裁判〉。吹哨判罚的是裁判，「支持者」是站在你这边的人，不负责判罚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27572, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "支持者", "is_correct": true, "explanation": "正确：「找到了几个支持者，帮他说话」指站在他这边的人，符合句意。"}, {"text": "对手", "is_correct": false, "explanation": "语义：对手不会「帮他说话」，与句中的帮助行为矛盾。"}, {"text": "敌人", "is_correct": false, "explanation": "语义：敌人不会「帮他说话」，与句意冲突。"}, {"text": "钥匙", "is_correct": false, "explanation": "配价：「帮……说话」的主语须是人，「钥匙」不能说话。"}], "explanations": {"支持者": "正确：「找到了几个支持者，帮他说话」指站在他这边的人，符合句意。", "对手": "语义：对手不会「帮他说话」，与句中的帮助行为矛盾。", "敌人": "语义：敌人不会「帮他说话」，与句意冲突。", "钥匙": "配价：「帮……说话」的主语须是人，「钥匙」不能说话。"}, "sentence_index": 6, "correct_answer": "支持者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比赛输了，她的支持者宣布了结果。", "explanation": "这里应该用〈裁判〉。宣布比赛结果的是裁判，支持者只是站在她这边的人，不负责此事。"}, {"text": "她有一个支持者，正在替对方说话，每天都来看她。", "explanation": "这里应该用〈反方〉。替对方说话的是反方，「支持者」是站在她这边、帮她说话的人。"}, {"text": "比赛输了，她的支持者一直在场上踢球。", "explanation": "这里应该用〈球员〉。场上踢球的是球员，「支持者」是站在她这边的人，不在场上比赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27572, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在家里有一只忠实的支持者。", "corrected_sentence": "我在家里有一位忠实的支持者。", "error_description": "量词错误：「支持者」指人，应用「位」，「只」用于动物，不用于人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27572, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有几位很重要支持者。", "corrected_sentence": "他有几位很重要的支持者。", "error_description": "结构错误：「很重要」修饰名词「支持者」时要加「的」，应说「很重要的支持者」，不说「很重要支持者」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
