INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27576, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "大家一起生活或在一起。", "primary_collocate": null, "pronunciation": "gòng chǔ", "ipa": "kʊŋ˥˩ ʈʂʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "他们三个人共处一室。", "target_word": "共处", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们在这个小岛上共处了十年。", "target_word": "共处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "兄弟俩从小共处，感情很深。", "target_word": "共处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些动物在同一个森林里共处。", "target_word": "共处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一家人共处一个屋檐下，很幸福。", "target_word": "共处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他和朋友在国外共处过一个夏天。", "target_word": "共处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家长期共处，难免有矛盾。", "target_word": "共处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两只小猫在家里共处得很好。", "target_word": "共处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们在同一个宿舍共处四年。", "target_word": "共处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雪夜里，旅客们共处一间小屋。", "target_word": "共处", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "共处了", "label": "体标"}, {"form": "共处过", "label": "体标"}], "register": "中性", "sense_fingerprint": "共处·多人同在一处生活或待在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c932acf-f05f-4d8d-ad7f-aaeceee4f32a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27576, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共处", "is_correct": true, "explanation": "共处：“共处一室”指几个人住在同一间屋子里，搭配自然。"}, {"text": "哭泣", "is_correct": false, "explanation": "配价：哭泣是不及物动词，后面不能带“一室”作宾语，句子不通。"}, {"text": "施肥", "is_correct": false, "explanation": "语义：施肥的对象是植物或土地，不能用于人与房间的关系。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：烘焙指做食物，句子说的是三个人住在一间屋里，与做饭无关。"}], "explanations": {"共处": "共处：“共处一室”指几个人住在同一间屋子里，搭配自然。", "哭泣": "配价：哭泣是不及物动词，后面不能带“一室”作宾语，句子不通。", "施肥": "语义：施肥的对象是植物或土地，不能用于人与房间的关系。", "烘焙": "语义：烘焙指做食物，句子说的是三个人住在一间屋里，与做饭无关。"}, "sentence_index": 0, "correct_answer": "共处"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们在山顶共处了一场比赛，最后分出了胜负。", "explanation": "这里应该用〈参加〉。共处表示待在一起，参加比赛要说参加，不能说共处。"}, {"text": "三位同事共处完成了这个项目，大家都很满意。", "explanation": "这里应该用〈合作〉。共处强调待在一起、和睦相处，共同完成工作要说合作。"}, {"text": "两家书店共处得很激烈，互相压价，生意都不好做。", "explanation": "这里应该用〈竞争〉。共处表示和睦地待在一起，互相压价、抢客人要说竞争。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27576, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共处", "is_correct": true, "explanation": "共处：“长期共处”指长时间待在一起，句子说长期相处会有矛盾，语境吻合。"}, {"text": "解散", "is_correct": false, "explanation": "语义：解散指分开、散去，与“长期”相矛盾。"}, {"text": "经过", "is_correct": false, "explanation": "配价：经过要带处所或事件作宾语，“大家长期经过”不完整。"}, {"text": "辞别", "is_correct": false, "explanation": "语义：辞别指告别离开，与“长期”相矛盾，句子强调长期在一起。"}], "explanations": {"共处": "共处：“长期共处”指长时间待在一起，句子说长期相处会有矛盾，语境吻合。", "解散": "语义：解散指分开、散去，与“长期”相矛盾。", "经过": "配价：经过要带处所或事件作宾语，“大家长期经过”不完整。", "辞别": "语义：辞别指告别离开，与“长期”相矛盾，句子强调长期在一起。"}, "sentence_index": 6, "correct_answer": "共处"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雪夜里，旅客们为了一间小屋共处得很激烈。", "explanation": "这里应该用〈争夺〉。共处表示和睦地待在一起，不能形容为抢一间小屋而激烈对立。"}, {"text": "雪夜里，旅客们共处了一段路，才找到小屋。", "explanation": "这里应该用〈同行〉。共处强调长时间待在一起，只一起走一段路要说同行。"}, {"text": "雪夜里，旅客们的意见始终共处，无法统一。", "explanation": "这里应该用〈对立〉。共处指和睦地在一起，意见相反、无法统一时要说对立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27576, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们没在这个小岛上共处了十年。", "corrected_sentence": "我们没在这个小岛上共处十年。", "error_description": "错误：用“没”否定时，动词后不能再加“了”。“没……共处了”错误，应删去“了”，为“没在这个小岛上共处十年”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27576, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "室友们共处很好，互相照顾。", "corrected_sentence": "室友们共处得很好，互相照顾。", "error_description": "“得”是补语标记，“共处”后带“很好”这类程度补语时要用“得”；“共处很好”错误，正确应为“共处得很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27578, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "微小", "is_correct": true, "explanation": "微小与宏大互为反义，指体积很小，与“很大”相对。"}, {"text": "朴素", "is_correct": false, "explanation": "朴素指简单不华丽，与体积的大小无关，不构成反义。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软指质地松软、不坚硬，与体积大小无关。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮指光线充足或颜色鲜亮，与体积大小无关。"}], "correct_answer": "微小", "explanations": {"微小": "微小与宏大互为反义，指体积很小，与“很大”相对。", "朴素": "朴素指简单不华丽，与体积的大小无关，不构成反义。", "柔软": "柔软指质地松软、不坚硬，与体积大小无关。", "明亮": "明亮指光线充足或颜色鲜亮，与体积大小无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27578, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "微小", "is_correct": true, "explanation": "微小与宏大互为反义，指体积很小，与“很大”相对。"}, {"text": "清脆", "is_correct": false, "explanation": "清脆形容声音或口感，与体积大小无关。"}, {"text": "温热", "is_correct": false, "explanation": "温热指温度适中偏暖，与体积大小无关。"}, {"text": "冰凉", "is_correct": false, "explanation": "冰凉指温度很低的触感，与体积大小无关。"}], "correct_answer": "微小", "explanations": {"微小": "微小与宏大互为反义，指体积很小，与“很大”相对。", "清脆": "清脆形容声音或口感，与体积大小无关。", "温热": "温热指温度适中偏暖，与体积大小无关。", "冰凉": "冰凉指温度很低的触感，与体积大小无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27578, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很大很大，比如一个很大的房子。", "primary_collocate": null, "pronunciation": "hóng dà", "ipa": "xʊŋ˧˥ ta˥˩", "syllable_count": 2, "sentences": [{"text": "山谷尽头有一座宏大的古城遗址。", "target_word": "宏大", "complexity_tier": "T3", "furigana": "shāngǔ jìntóu yǒu yí zuò hóngdà de gǔchéng yízhǐ", "sentence_source": "generated"}, {"text": "这座宫殿宏大又漂亮，游客都在拍照。", "target_word": "宏大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上有一座宏大的庙。", "target_word": "宏大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司新盖的大楼很宏大。", "target_word": "宏大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站在宏大的广场上，我觉得自己很小。", "target_word": "宏大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个体育馆很宏大，能坐五万人。", "target_word": "宏大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片草原宏大无边，我们骑马走了一天。", "target_word": "宏大", "complexity_tier": "T3", "furigana": "zhè piàn cǎoyuán hóngdà wúbiān, wǒmen qímǎ zǒu le yì tiān", "sentence_source": "generated"}, {"text": "城墙宏大，我们走了一个小时。", "target_word": "宏大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学的校园宏大，骑车也要半小时。", "target_word": "宏大", "complexity_tier": "T3", "furigana": "zhè suǒ dàxué de xiàoyuán hóngdà, qí chē yě yào bàn xiǎoshí", "sentence_source": "generated"}, {"text": "这个宏大的大厅里，放着一百张桌子。", "target_word": "宏大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "宏大的", "label": "结构助词"}, {"form": "宏大叙事", "label": "复合"}], "register": "书面", "sense_fingerprint": "体积或空间很大很大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf1fc5f1-3de3-49b7-bd2c-bca5dafc47e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27578, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宏大", "is_correct": true, "explanation": "宏大修饰“古城遗址”，指遗址的体积和范围很大，与“山谷尽头”的景象相符。"}, {"text": "崭新", "is_correct": false, "explanation": "语义：崭新指刚出现或没有用过，与“古城遗址”的古老相矛盾。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：年轻指时间短、不古老，与“古城遗址”相矛盾。"}, {"text": "光滑", "is_correct": false, "explanation": "搭配：光滑形容表面平滑，不用来形容遗址的整体规模。"}], "explanations": {"宏大": "宏大修饰“古城遗址”，指遗址的体积和范围很大，与“山谷尽头”的景象相符。", "崭新": "语义：崭新指刚出现或没有用过，与“古城遗址”的古老相矛盾。", "年轻": "语义：年轻指时间短、不古老，与“古城遗址”相矛盾。", "光滑": "搭配：光滑形容表面平滑，不用来形容遗址的整体规模。"}, "sentence_index": 0, "correct_answer": "宏大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛的失误很宏大，影响了整个团队。", "explanation": "这里应该用〈重大〉。宏大形容规模、体积，不修饰失误、事件的严重程度，这类要用重大。"}, {"text": "这位宏大的科学家刚获得了奖项。", "explanation": "这里应该用〈伟大〉。宏大形容规模或体积，不用来评价人的贡献，称赞人物要用伟大。"}, {"text": "宏大的农民都希望今年丰收。", "explanation": "这里应该用〈广大〉。宏大不修饰人群，指人多、范围广要用广大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27578, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宏大", "is_correct": true, "explanation": "宏大无边：宏大修饰草原，表示范围广阔，与“骑马走了一天”相符。"}, {"text": "狭小", "is_correct": false, "explanation": "语义：狭小指空间窄，与“宏大无边”相矛盾。"}, {"text": "拥挤", "is_correct": false, "explanation": "搭配：拥挤形容人或物聚集，不用来形容草原的范围。"}, {"text": "矮小", "is_correct": false, "explanation": "搭配：矮小形容身高或体型，不用来修饰草原。"}], "explanations": {"宏大": "宏大无边：宏大修饰草原，表示范围广阔，与“骑马走了一天”相符。", "狭小": "语义：狭小指空间窄，与“宏大无边”相矛盾。", "拥挤": "搭配：拥挤形容人或物聚集，不用来形容草原的范围。", "矮小": "搭配：矮小形容身高或体型，不用来修饰草原。"}, "sentence_index": 6, "correct_answer": "宏大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的身材很宏大，站在门口挡住了光。", "explanation": "这里应该用〈高大〉。宏大形容建筑、场地等的规模，不用来描述人的身材，形容身材高大要用高大。"}, {"text": "他承受着宏大的压力。", "explanation": "这里应该用〈巨大〉。宏大指规模、体积很大，压力、损失这类程度上的大要用巨大。"}, {"text": "这件外套很宏大，穿起来很暖和。", "explanation": "这里应该用〈宽大〉。宏大指体积或空间庞大，衣服的宽松要用宽大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27578, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座古城的城墙非常宏大过，游客要走很久才能绕完。", "corrected_sentence": "这座古城的城墙非常宏大，游客要走很久才能绕完。", "error_description": "体标错误：形容词“宏大”后不能加动态助词“过”，应删去“过”，说“城墙非常宏大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27578, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座牧场非常宏大极了，里面养着很多牛羊。", "corrected_sentence": "这座牧场非常宏大，里面养着很多牛羊。", "error_description": "程度重复：“宏大”前已有程度副词“非常”，后面不能再加“极了”。应删去“极了”，说“非常宏大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
