INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27588, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用心思考，看看事情有什么不同。", "primary_collocate": null, "pronunciation": "sī biàn", "ipa": "sɨ˥ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "做决定以前，我们要先思辨一下。", "target_word": "思辨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爱思辨，常常问为什么。", "target_word": "思辨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看新闻时要学会思辨。", "target_word": "思辨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们思辨两种办法的不同。", "target_word": "思辨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要多思辨，别听别人怎么说就怎么做。", "target_word": "思辨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到难题，她总是先安静地思辨。", "target_word": "思辨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们正在认真思辨这个问题。", "target_word": "思辨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有思辨，就看不出问题在哪儿。", "target_word": "思辨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他思辨了很久，才做出选择。", "target_word": "思辨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起思辨，看看谁的想法对。", "target_word": "思辨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "思辨了", "label": "完成体"}], "register": "书面", "sense_fingerprint": "用心思考并比较事情的不同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2e370e-2ea2-4fb6-b66c-628b6aedac9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27588, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "踢", "is_correct": false, "explanation": "语义：“踢”是脚部动作，与做决定前的思考无关，句意不通。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”是清洁动作，与做决定前的思考无关，句意不通。"}, {"text": "思辨", "is_correct": true, "explanation": "正确。“思辨一下”指做决定前用心思考，与句意相符。"}, {"text": "剪", "is_correct": false, "explanation": "语义：“剪”是切断的动作，与做决定前的思考无关，句意不通。"}], "explanations": {"踢": "语义：“踢”是脚部动作，与做决定前的思考无关，句意不通。", "擦": "语义：“擦”是清洁动作，与做决定前的思考无关，句意不通。", "思辨": "正确。“思辨一下”指做决定前用心思考，与句意相符。", "剪": "语义：“剪”是切断的动作，与做决定前的思考无关，句意不通。"}, "sentence_index": 0, "correct_answer": "思辨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他思辨了一下桌子。", "explanation": "这里应该用〈擦〉。思辨是用心思考，不能带“桌子”这类具体物品作宾语。"}, {"text": "她思辨地哭了。", "explanation": "这里应该用〈伤心〉。思辨是用心思考、比较不同的活动，不能用来形容哭的样子。"}, {"text": "他思辨了我的朋友。", "explanation": "这里应该用〈感谢〉。思辨是思考活动，不能以人作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9c7671-f8e6-4a19-9d02-eb896a1b505d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27588, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "忘记", "is_correct": false, "explanation": "语义：“认真”与“忘记”相矛盾，句意不通。"}, {"text": "喜欢", "is_correct": false, "explanation": "搭配：“认真”修饰动作，“喜欢”是心理动词，不能被“认真”修饰。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬不能作用于抽象的问题，与句意不符。"}, {"text": "思辨", "is_correct": true, "explanation": "正确。“认真思辨这个问题”指用心思考其中的不同，与句意相符。"}], "explanations": {"忘记": "语义：“认真”与“忘记”相矛盾，句意不通。", "喜欢": "搭配：“认真”修饰动作，“喜欢”是心理动词，不能被“认真”修饰。", "咬": "语义：咬不能作用于抽象的问题，与句意不符。", "思辨": "正确。“认真思辨这个问题”指用心思考其中的不同，与句意相符。"}, "sentence_index": 6, "correct_answer": "思辨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在思辨里吃了午饭。", "explanation": "这里应该用〈食堂〉。思辨是用心思考的活动，不是可以吃饭的场所。"}, {"text": "他把快乐思辨给大家。", "explanation": "这里应该用〈分享〉。思辨是用心思考、比较不同的活动，不能用来把快乐交给别人。"}, {"text": "他大声地思辨了一声。", "explanation": "这里应该用〈喊〉。思辨是用心思考的活动，不能用来发出声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9c7671-f8e6-4a19-9d02-eb896a1b505d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
